def _env_truthy(name: str) -> bool:
    return str(os.getenv(name) or "").strip().lower() in {"1", "true", "yes", "on"}


def operator_identity_mode() -> str:
    """The plane's missing-principal policy from TAKYON_REQUIRE_OPERATOR_IDENTITY: '' (unset —
    historical single-operator/worker behavior), 'warn' (allow + record evidence), or 'enforce'
    (fail closed). A NON-EMPTY mode also declares the plane PER-SESSION: process-global
    TAKYON_OPERATOR_USER_ID stops being an identity source everywhere on that plane, so identity
    can only arrive through the authenticated session path (transport principal, server-injected
    session params, or per-session TAKYON_SESSION_USER_ID env in a per-session child process)."""
    raw = str(os.getenv("TAKYON_REQUIRE_OPERATOR_IDENTITY") or "").strip().lower()
    if raw in {"1", "true", "yes", "on", "enforce"}:
        return "enforce"
    if raw == "warn":
        return "warn"
    return ""


def _normalized_host_role() -> str:
    # Thin shim over the one role truth table (Stage 3): core uses the canonical view.
    return environment.HostRole.canonical()


def _resolved_takyon_home() -> Path | None:
    raw = str(os.getenv("TAKYON_HOME") or "").strip()
    if not raw:
        return None
    try:
        return Path(raw).expanduser().resolve()
    except Exception:
        return None


def _remote_workspace_sync_allowed(backend_name: str) -> bool:
    if str(backend_name or "").strip().lower() != "supabase_s3":
        return True
    if _env_truthy(_ALLOW_REMOTE_STORAGE_SYNC_OUTSIDE_VPS_ENV):
        return True
    if platform.system().lower() != "linux":
        return False
    if _normalized_host_role() not in _APPROVED_REMOTE_WORKSPACE_SYNC_HOST_ROLES:
        return False
    home = _resolved_takyon_home()
    if home is None:
        return False
    return any(home == prefix or prefix in home.parents for prefix in _APPROVED_REMOTE_WORKSPACE_HOME_PREFIXES)
