_POSTGRES_POOL_MAX_SIZE = max(
    1,
    int(os.getenv("TAKYON_PG_POOL_SIZE", "8") or 8),
)
_POSTGRES_POOL_WAIT_SECONDS = max(
    1.0,
    float(os.getenv("TAKYON_PG_POOL_WAIT_SECONDS", "20") or 20),
)


class _PostgresPool:
    """Tiny in-process connection pool for the dashboard/store read path.

    Deploy currently rsyncs runtime files and compiles Python, but does not install new
    dependencies on the VPS. Keeping this pool local avoids adding a new package just to
    reuse psycopg connections across the gateway's concurrent dashboard reads.
    """

    def __init__(self, dsn: str, *, max_size: int) -> None:
        self._dsn = dsn
        self._max_size = max_size
        self._idle: list[Any] = []
        self._open = 0
        self._cond = threading.Condition()

    def acquire(self, factory: Any) -> Any:
        deadline = time.monotonic() + _POSTGRES_POOL_WAIT_SECONDS
        while True:
            with self._cond:
                while self._idle:
                    conn = self._idle.pop()
                    if not getattr(conn, "closed", False):
                        return conn
                    self._open = max(0, self._open - 1)
                if self._open < self._max_size:
                    self._open += 1
                    break
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise TimeoutError("Timed out waiting for a Takyon Postgres connection")
                self._cond.wait(timeout=remaining)
        try:
            return factory()
        except Exception:
            with self._cond:
                self._open = max(0, self._open - 1)
                self._cond.notify()
            raise

    def release(self, conn: Any, *, discard: bool = False) -> None:
        if conn is None:
            return
        broken = discard or bool(getattr(conn, "closed", False))
        if not broken:
            try:
                conn.rollback()
                conn.execute("reset role")
                # Deliberately NO takyon.rls_bypass scrub here. The live DSN is Supabase's
                # transaction-mode pooler (6543): a session-scope SET from this handback lands on an
                # arbitrary pooled server backend and poisons it for every other trusted-plane
                # client (2026-07-03 incident: intermittent empty control-plane reads / safebox
                # unknown_business). Bypass state is owned by role defaults
                # (db/migrations/0059_rls_bypass_role_defaults.sql) plus
                # configure_takyon_pg_session on every acquire. The three app-scope GUCs are still
                # zeroed as a conservative handback: '' is their fail-closed default, so the write
                # is harmless wherever it lands, and app scoping only ever binds
                # transaction-locally (_pg_app_scope) anyway.
                conn.execute(
                    "select"
                    " set_config('takyon.rls_business_slug', '', false),"
                    " set_config('takyon.rls_app_user_id', '', false),"
                    " set_config('takyon.rls_session_hash', '', false)"
                )
                conn.commit()
            except Exception:
                broken = True
        if broken:
            try:
                conn.close()
            except Exception:
                pass
            with self._cond:
                self._open = max(0, self._open - 1)
                self._cond.notify()
            return
        with self._cond:
            self._idle.append(conn)
            self._cond.notify()

    def close_all(self) -> None:
        with self._cond:
            idle = list(self._idle)
            self._idle.clear()
            self._open = 0
            self._cond.notify_all()
        for conn in idle:
            try:
                conn.close()
            except Exception:
                pass


_POSTGRES_POOLS: dict[str, _PostgresPool] = {}
_POSTGRES_POOLS_LOCK = threading.Lock()
_ACTIVE_DATABASE_PLANE: contextvars.ContextVar[str] = contextvars.ContextVar(
    "takyon_active_database_plane",
    default="",
)


def _postgres_pool(dsn: str, *, plane: str = "") -> _PostgresPool:
    dsn_key = str(dsn or "").strip()
    plane_key = str(plane or "").strip().lower()
    # Registry key composes environment.cache_scope() (plan R3: a dev-scoped instance must never
    # reuse a prod-scoped pool) with the Stage-4a plane key (e.g. "app-http") and the DSN.
    key = f"{environment.cache_scope()}\0{plane_key}\0{dsn_key}"
    with _POSTGRES_POOLS_LOCK:
        pool = _POSTGRES_POOLS.get(key)
        if pool is None:
            pool = _PostgresPool(dsn_key, max_size=_POSTGRES_POOL_MAX_SIZE)
            _POSTGRES_POOLS[key] = pool
        return pool


@contextmanager
def app_runtime_database_plane():
    """Bind shared product-app handlers to the app DB login for one request."""
    token = _ACTIVE_DATABASE_PLANE.set("app")
    try:
        yield
    finally:
        _ACTIVE_DATABASE_PLANE.reset(token)


def _close_postgres_pools() -> None:
    with _POSTGRES_POOLS_LOCK:
        pools = list(_POSTGRES_POOLS.values())
        _POSTGRES_POOLS.clear()
    for pool in pools:
        pool.close_all()

atexit.register(_close_postgres_pools)

