class TakyonError(RuntimeError):
    pass


class CreativeCreditBudgetExceeded(TakyonError):
    def __init__(
        self,
        *,
        bucket: str,
        requested_credits: int,
        remaining_credits: int,
        allocated_credits: int,
        used_credits: int,
        reserved_credits: int,
    ) -> None:
        self.bucket = str(bucket or "").strip()
        self.requested_credits = max(0, int(requested_credits or 0))
        self.remaining_credits = max(0, int(remaining_credits or 0))
        self.allocated_credits = max(0, int(allocated_credits or 0))
        self.used_credits = max(0, int(used_credits or 0))
        self.reserved_credits = max(0, int(reserved_credits or 0))
        super().__init__(
            f"channel_budget_exhausted:{self.bucket}: need {self.requested_credits}, "
            f"remaining {self.remaining_credits}"
        )


def _effective_business_mode(value: Any) -> str:
    mode = str(value or "").strip().lower()
    return "live" if mode != "live" else mode


def _requested_business_mode(value: Any, *, allow_empty: bool = False) -> str:
    mode = str(value or "").strip().lower()
    if not mode:
        return "" if allow_empty else "live"
    if mode == "test":
        raise TakyonError(
            "test mode is disabled; all businesses run live and missing providers hard-fail"
        )
    if mode not in _BUSINESS_MODES:
        raise TakyonError(f"business mode must be one of {sorted(_BUSINESS_MODES)}")
    return mode


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _future(minutes: int = 0, days: int = 0) -> str:
    return (datetime.now(timezone.utc) + timedelta(minutes=minutes, days=days)).isoformat()


def _parse_iso_datetime(value: Any) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _datetime_to_iso(value: datetime | None) -> str:
    return value.astimezone(timezone.utc).isoformat() if isinstance(value, datetime) else ""


def _latest_tree_file_updated_at(root: Path, *, skip_hidden: bool = False, skip_predicate: Any = None) -> datetime | None:
    latest: datetime | None = None
    if not root.exists() or not root.is_dir():
        return None
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        if skip_hidden and any(part.startswith(".") for part in path.parts):
            continue
        if callable(skip_predicate) and skip_predicate(path):
            continue
        try:
            updated = datetime.fromtimestamp(path.stat().st_mtime, timezone.utc)
        except OSError:
            continue
        if latest is None or updated > latest:
            latest = updated
    return latest


def _projection_freshness(
    *,
    projection: str,
    evidence: str,
    projection_updated_at: Any,
    evidence_updated_at: Any,
    stale_reason: str,
) -> dict[str, Any] | None:
    projection_dt = _parse_iso_datetime(projection_updated_at)
    evidence_dt = (
        evidence_updated_at
        if isinstance(evidence_updated_at, datetime)
        else _parse_iso_datetime(evidence_updated_at)
    )
    if evidence_dt is None:
        return None
    if projection_dt is not None and projection_dt >= evidence_dt:
        return None
    return {
        "projection": projection,
        "evidence": evidence,
        "authoritative": False,
        "status": "stale",
        "reason": stale_reason,
        "projection_updated_at": _datetime_to_iso(projection_dt),
        "evidence_updated_at": _datetime_to_iso(evidence_dt),
    }


def _normalize_guidance_skills(raw: Any) -> list[str]:
    if raw is None:
        return []
    values = [raw] if isinstance(raw, str) else list(raw) if isinstance(raw, (list, tuple, set)) else []
    normalized: list[str] = []
    seen: set[str] = set()
    for value in values:
        text = str(value or "").strip()
        if not text:
            continue
        key = text.lower()
        if key in seen:
            continue
        seen.add(key)
        normalized.append(text)
    return normalized


# Fallback design packs used ONLY when the caller passes no `guidance_skills`. The bootstrap CEO
# now selects the single fitting style pack per business and passes it explicitly, so this default
# is a backstop. Keep it lean — base method + one generic style — so a caller that omits guidance
# never silently makes the worker carry all six packs through its whole loop. Per-business fit comes
# from the CEO's explicit pick; this fallback is intentionally generic.
_DEFAULT_PRODUCT_DESIGN_GUIDANCE_SKILLS: tuple[str, ...] = (
    "claude-design",
    "claude-design-openai",
)
def _resolve_worker_guidance_skills(
    args: dict[str, Any],
    workspace_raw: str,
    *,
    surface: dict[str, Any] | None = None,
    instruction: str = "",
) -> tuple[list[str], str]:
    if "guidance_skills" in args:
        return _normalize_guidance_skills(args.get("guidance_skills")), "used explicit guidance_skills from caller"
    # Customer-facing product surfaces default to the full design-pack set so the worker always
    # builds with a coherent visual direction instead of bare layout rules. The caller can still
    # narrow to a subset, or pass an explicit ``guidance_skills: []`` to opt out.
    if _workspace_needs_runtime_ui_contract(workspace_raw) or _workspace_needs_customer_ai_copy_contract(workspace_raw):
        return list(_DEFAULT_PRODUCT_DESIGN_GUIDANCE_SKILLS), "auto-selected design packs for customer-facing product surface"
    return [], ""


def _normalize_runtime_features(raw: Any, *, strict: bool = False) -> list[str]:
    if raw is None:
        return []
    values: list[Any]
    if isinstance(raw, str):
        values = [raw]
    elif isinstance(raw, dict):
        values = [key for key, enabled in raw.items() if enabled]
    elif isinstance(raw, (list, tuple, set)):
        values = list(raw)
    else:
        values = []
    normalized: list[str] = []
    seen: set[str] = set()
    unknown: list[str] = []
    for value in values:
        text = re.sub(r"[\s-]+", "_", str(value or "").strip().lower())
        if not text or not re.match(r"^[a-z0-9][a-z0-9_]{0,63}$", text):
            continue
        expanded = _RUNTIME_FEATURE_LEGACY_ALIASES.get(text, (text,))
        invalid = [item for item in expanded if item not in PRODUCT_RUNTIME_RAILS or item == "billing"]
        if invalid:
            unknown.append(text)
            continue
        for item in expanded:
            if item in seen:
                continue
            seen.add(item)
            normalized.append(item)
    if strict and unknown:
        raise TakyonError(
            "unknown runtime_features: "
            + ", ".join(unknown)
            + f". Known rails: {', '.join(sorted(PRODUCT_RUNTIME_RAILS))}"
        )
    resolved: set[str] = set()

    def include(rail: str) -> None:
        if rail in resolved:
            return
        for dep in _RUNTIME_FEATURE_DEPENDENCIES.get(rail, ()):
            include(dep)
        resolved.add(rail)

    for item in normalized:
        include(item)

    ordered = [rail for rail in _RUNTIME_FEATURE_ORDER if rail in resolved]
    trailing = [rail for rail in normalized if rail in resolved and rail not in _RUNTIME_FEATURE_ORDER and rail not in ordered]
    return ordered + trailing


def _surface_declared_runtime_features(surface: dict[str, Any] | None) -> list[str]:
    if not isinstance(surface, dict):
        return []
    # `actions` is the one rail that MUST be file-backed — declaring it without on-disk action
    # files would expose an uncallable rail — so it is stripped from the directly-declared set
    # and only re-admitted from `_workspace_file_rails` below. Every other rail may be declared
    # directly AND/OR derived from the build (purely additive), so directly-declared rails are
    # never lost.
    direct = [
        rail
        for rail in _normalize_runtime_features(surface.get("runtime_features"))
        if rail != "actions"
    ]
    # `_workspace_file_rails` carries the rails DERIVED from the built source (actions from
    # on-disk files, plus records/media/directory/connections/generate/search from runtime-
    # client usage). Admit the whole build-derived set, not just actions, so a product that
    # calls a rail self-declares it even when the stored contract omitted it.
    file_backed = [
        rail
        for rail in _normalize_runtime_features(surface.get("_workspace_file_rails"))
        if rail in _BUILD_DERIVED_RAILS
    ]
    if direct or file_backed:
        return _normalize_runtime_features([*direct, *file_backed])
    metadata = surface.get("metadata") if isinstance(surface.get("metadata"), dict) else {}
    return [rail for rail in _normalize_runtime_features(metadata.get("runtime_features")) if rail != "actions"]


def _surface_runtime_features(surface: dict[str, Any] | None) -> list[str]:
    declared = _surface_declared_runtime_features(surface)
    if not isinstance(surface, dict):
        return declared
    return _canonical_runtime_features_for_surface_shape(declared)


def _surface_bootstrap_access_shell_runtime_features(
    surface: dict[str, Any] | None,
    *,
    declared_runtime_features: list[str] | None = None,
    customer_experience: dict[str, Any] | None = None,
) -> list[str]:
    if not isinstance(surface, dict) or _surface_allows_landing_only(surface):
        return []
    if _surface_product_workflow_shape(surface):
        return []
    declared = list(
        declared_runtime_features
        if declared_runtime_features is not None
        else _surface_runtime_features(surface)
    )
    if declared and not set(declared).issubset(set(DEFAULT_BOOTSTRAP_ACCESS_SHELL_RUNTIME_FEATURES)):
        return []
    customer_shape = (
        customer_experience
        if isinstance(customer_experience, dict)
        else _surface_customer_experience_shape(surface)
    )
    if customer_shape.get("required_app_tabs"):
        return []
    required_routes = customer_shape.get("required_routes") or []
    if not _surface_shape_requires_app_shell(
        runtime_features=declared,
        required_app_tabs=[],
        required_routes=required_routes,
    ):
        return []
    declared_app_routes = {
        route
        for route in _surface_routes(surface)
        if route != "/" and _PRODUCT_WORKFLOW_ROUTE_PATTERN.search(route) and not _is_shared_runtime_route_path(route)
    }
    if declared_app_routes and not declared_app_routes.issubset({"/app", "/app/profile"}):
        return []
    return list(DEFAULT_BOOTSTRAP_ACCESS_SHELL_RUNTIME_FEATURES)


def _surface_effective_runtime_features(surface: dict[str, Any] | None) -> list[str]:
    declared = _surface_runtime_features(surface)
    bootstrap = _surface_bootstrap_access_shell_runtime_features(
        surface,
        declared_runtime_features=declared,
    )
    if bootstrap:
        return bootstrap
    return declared


def _normalize_subuser_surface_choice(
    value: Any,
    *,
    allowed: frozenset[str],
) -> str:
    text = re.sub(r"[\s-]+", "_", str(value or "").strip().lower())
    if not text or text not in allowed:
        return ""
    return text


def _canonical_runtime_features_for_surface_shape(
    runtime_features: list[str] | None,
) -> list[str]:
    declared = list(runtime_features or [])

    def include(values: tuple[str, ...]) -> None:
        for rail in values:
            if rail not in declared:
                declared.append(rail)

    # `generate` is the only rail with an implicit dependency that is not already
    # captured by _RUNTIME_FEATURE_DEPENDENCIES. File-backed HTTP `actions` are
    # derived at workspace materialization time instead of being stored here.
    if "generate" in declared:
        include(("auth", "account"))
    return _normalize_runtime_features(declared, strict=True)


def _normalize_subuser_rail_state(
    raw: Any,
    *,
    declared_rails: list[str],
) -> dict[str, str]:
    if not isinstance(raw, dict):
        raw = {}
    normalized: dict[str, str] = {}
    for key, value in raw.items():
        rail = re.sub(r"[\s-]+", "_", str(key or "").strip().lower())
        state = re.sub(r"[\s-]+", "_", str(value or "").strip().lower())
        state = _LEGACY_SUBUSER_RAIL_STATE_ALIASES.get(state, state)
        if state not in SUBUSER_RAIL_STATE_CHOICES:
            continue
        expanded = _RUNTIME_FEATURE_LEGACY_ALIASES.get(rail, (rail,))
        for item in expanded:
            if item not in PRODUCT_RUNTIME_RAILS or item == "billing":
                continue
            normalized[item] = state
    for rail in declared_rails:
        normalized.setdefault(rail, "declared")
    return {rail: normalized[rail] for rail in declared_rails if rail in normalized}


def _surface_subuser_app_metadata(surface: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(surface, dict):
        return {}
    metadata = surface.get("metadata") if isinstance(surface.get("metadata"), dict) else {}
    payload = metadata.get("subuser_app") if isinstance(metadata.get("subuser_app"), dict) else {}
    return dict(payload)


def _surface_subuser_app_shape(surface: dict[str, Any] | None) -> dict[str, Any]:
    payload = _surface_subuser_app_metadata(surface)
    runtime_features = _surface_runtime_features(surface)
    rail_state = _normalize_subuser_rail_state(
        payload.get("rail_state"),
        declared_rails=runtime_features,
    )
    kit_path = str(payload.get("kit_path") or SUBUSER_KIT_DIRNAME).strip() or SUBUSER_KIT_DIRNAME
    # frontend_stack is hidden internal platform state (the scaffold key),
    # not an operator-authored field; it always resolves to the pinned scaffold.
    return {
        "frontend_api_mode": SUBUSER_FRONTEND_API_MODE,
        "frontend_stack": _normalize_frontend_stack_choice(payload.get("frontend_stack")) or DEFAULT_SUBUSER_FRONTEND_STACK,
        "kit_path": kit_path,
        "rail_state": rail_state,
    }


def _normalize_surface_string_list(raw: Any) -> list[str]:
    values = raw if isinstance(raw, list) else ([raw] if raw is not None else [])
    normalized: list[str] = []
    seen: set[str] = set()
    for item in values:
        if isinstance(item, dict):
            text = str(
                item.get("path")
                or item.get("route")
                or item.get("name")
                or item.get("label")
                or item.get("value")
                or ""
            ).strip()
        else:
            text = str(item or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        normalized.append(text)
    return normalized


_BOOTSTRAP_FREE_OR_TRIAL_PATTERN = re.compile(
    r"\b(free|trial|waitlist|starter|freemium)\b",
    re.IGNORECASE,
)
_BOOTSTRAP_DEBUG_NOTE_PATTERN = re.compile(
    r"(debug/?blocked|blocked state|not wired|missing app session|fake checkout|fake billing)",
    re.IGNORECASE,
)


def _canonical_bootstrap_conversion_model(
    raw: Any,
    *,
    bootstrap_seed: bool,
    app_shell_required: bool,
) -> str:
    text = str(raw or "").strip()
    if not (bootstrap_seed and app_shell_required):
        return text
    if not text or _BOOTSTRAP_FREE_OR_TRIAL_PATTERN.search(text):
        return "monthly subscription"
    return text


def _canonical_bootstrap_access_runtime_features(
    runtime_features: list[str],
    *,
    bootstrap_seed: bool,
    app_shell_required: bool,
) -> list[str]:
    if not (bootstrap_seed and app_shell_required):
        return runtime_features
    return list(DEFAULT_BOOTSTRAP_ACCESS_SHELL_RUNTIME_FEATURES)


def _validate_frontend_stack_runtime_feature_contract(
    *,
    frontend_stack: Any,
    runtime_features: list[str],
) -> None:
    normalized_frontend_stack = _normalize_frontend_stack_choice(frontend_stack) or DEFAULT_SUBUSER_FRONTEND_STACK
    if normalized_frontend_stack != "vite_react_ts":
        return
    if "generate" in set(runtime_features or []):
        raise TakyonError(
            "generate is not a declarable rail on the pinned Vite scaffold — AI generation must be "
            "implemented behind a product action file that calls the shared generate broker via ctx"
        )


def _canonical_bootstrap_surface_notes(
    raw: Any,
    *,
    bootstrap_seed: bool,
    app_shell_required: bool,
) -> str:
    text = str(raw or "").strip()
    if not (bootstrap_seed and app_shell_required):
        return text
    if _BOOTSTRAP_DEBUG_NOTE_PATTERN.search(text):
        return ""
    return text


def _surface_customer_experience_metadata(surface: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(surface, dict):
        return {}
    metadata = surface.get("metadata") if isinstance(surface.get("metadata"), dict) else {}
    payload = metadata.get("customer_experience") if isinstance(metadata.get("customer_experience"), dict) else {}
    return dict(payload)


def _surface_product_workflow_metadata(surface: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(surface, dict):
        return {}
    metadata = surface.get("metadata") if isinstance(surface.get("metadata"), dict) else {}
    payload = metadata.get("product_workflow") if isinstance(metadata.get("product_workflow"), dict) else {}
    return dict(payload)


def _normalize_surface_bool(raw: Any) -> bool | None:
    if raw is None:
        return None
    if isinstance(raw, bool):
        return raw
    text = str(raw).strip().lower()
    if not text:
        return None
    if text in {"1", "true", "yes", "y", "on"}:
        return True
    if text in {"0", "false", "no", "n", "off"}:
        return False
    return None


def _normalize_surface_int(raw: Any) -> int | None:
    if raw is None:
        return None
    text = str(raw).strip()
    if not text:
        return None
    try:
        return int(text)
    except (TypeError, ValueError):
        return None


def _normalize_runtime_rail_name(raw: Any) -> str:
    return re.sub(r"[\s-]+", "_", str(raw or "").strip().lower())


def _normalize_product_workflow_range(raw: Any) -> dict[str, int]:
    if not isinstance(raw, dict):
        return {}
    minimum = _normalize_surface_int(raw.get("min"))
    maximum = _normalize_surface_int(raw.get("max"))
    payload: dict[str, int] = {}
    if minimum is not None:
        payload["min"] = minimum
    if maximum is not None:
        payload["max"] = maximum
    return payload


def _surface_product_workflow_shape(surface: dict[str, Any] | None) -> dict[str, Any]:
    try:
        from . import app_actions as takyon_app_actions
    except Exception:
        from plugins.takyon import app_actions as takyon_app_actions

    payload = _surface_product_workflow_metadata(surface)
    shape: dict[str, Any] = {}

    def _set_text(key: str) -> None:
        text = str(payload.get(key) or "").strip()
        if text:
            shape[key] = text

    def _set_rules(key: str, rule_keys: tuple[str, ...]) -> None:
        raw = payload.get(key)
        if not isinstance(raw, dict):
            return
        normalized: dict[str, bool] = {}
        for rule_key in rule_keys:
            value = _normalize_surface_bool(raw.get(rule_key))
            if value is not None:
                normalized[rule_key] = value
        if normalized:
            shape[key] = normalized

    _set_text("primary_user")
    _set_text("workspace_model")
    _set_text("primary_job")

    raw_core_loop = payload.get("core_loop")
    if isinstance(raw_core_loop, dict):
        core_loop: dict[str, Any] = {}
        for key in ("input", "action", "result"):
            text = str(raw_core_loop.get(key) or "").strip()
            if text:
                core_loop[key] = text
        for key in ("save_record", "return_to_record_later"):
            value = _normalize_surface_bool(raw_core_loop.get(key))
            if value is not None:
                core_loop[key] = value
        if core_loop:
            shape["core_loop"] = core_loop

    _set_rules(
        "scope_rules",
        (
            "no_teams",
            "no_roles",
            "no_invites",
            "no_sharing",
            "no_public_pages",
            "no_admin_console",
        ),
    )

    raw_persistence_rules = payload.get("persistence_rules")
    if isinstance(raw_persistence_rules, dict):
        persistence_rules: dict[str, Any] = {}
        for key in (
            "requires_server_state",
            "survives_sign_out",
            "truthful_empty_state",
            "reopenable_history",
            "no_local_only_state",
        ):
            value = _normalize_surface_bool(raw_persistence_rules.get(key))
            if value is not None:
                persistence_rules[key] = value
        persistence_rail = _normalize_runtime_rail_name(raw_persistence_rules.get("persistence_rail"))
        if persistence_rail:
            persistence_rules["persistence_rail"] = persistence_rail
        if persistence_rules:
            shape["persistence_rules"] = persistence_rules

    raw_product_budget = payload.get("product_budget")
    if isinstance(raw_product_budget, dict):
        product_budget: dict[str, Any] = {}
        for key in ("screens", "entity_types", "backend_actions", "ai_flows"):
            normalized_range = _normalize_product_workflow_range(raw_product_budget.get(key))
            if normalized_range:
                product_budget[key] = normalized_range
        if product_budget:
            shape["product_budget"] = product_budget

    raw_first_run = payload.get("first_run")
    if isinstance(raw_first_run, dict):
        first_run: dict[str, Any] = {}
        strategy = str(raw_first_run.get("strategy") or "").strip()
        if strategy:
            first_run["strategy"] = strategy
        for key in ("empty_state_required", "pending_state_required", "error_state_required"):
            value = _normalize_surface_bool(raw_first_run.get(key))
            if value is not None:
                first_run[key] = value
        if first_run:
            shape["first_run"] = first_run

    _set_text("success_moment")

    acceptance_tests = _normalize_surface_string_list(payload.get("acceptance_tests"))
    if acceptance_tests:
        shape["acceptance_tests"] = acceptance_tests

    actions = takyon_app_actions.normalize_action_specs(payload.get("actions"))
    if actions:
        shape["actions"] = actions

    outbound_hosts = takyon_app_actions.normalize_outbound_hosts(payload.get("outbound_hosts"))
    if outbound_hosts:
        shape["outbound_hosts"] = outbound_hosts

    not_now = _normalize_surface_string_list(payload.get("not_now"))
    if not_now:
        shape["not_now"] = not_now

    return shape


def _merge_product_workflow_metadata(
    metadata: dict[str, Any] | None,
    *,
    product_workflow: Any = None,
) -> dict[str, Any]:
    merged = dict(metadata if isinstance(metadata, dict) else {})
    existing = (
        _surface_product_workflow_shape({"metadata": {"product_workflow": merged.get("product_workflow")}})
        if isinstance(merged.get("product_workflow"), dict)
        else {}
    )
    if product_workflow is None:
        if existing:
            merged["product_workflow"] = existing
        return merged
    if not isinstance(product_workflow, dict):
        raise TakyonError("product_workflow must be an object")
    if not product_workflow:
        merged.pop("product_workflow", None)
        return merged
    candidate = {
        **existing,
        **product_workflow,
    }
    normalized = _surface_product_workflow_shape({"metadata": {"product_workflow": candidate}})
    if normalized:
        merged["product_workflow"] = normalized
    else:
        merged.pop("product_workflow", None)
    return merged

def _product_workflow_screen_claims(customer_experience: dict[str, Any] | None) -> list[str]:
    if not isinstance(customer_experience, dict):
        return []
    claims: list[str] = []
    seen: set[str] = set()
    for tab in customer_experience.get("required_app_tabs") or []:
        label = f"app tab `{str(tab or '').strip()}`"
        if label != "app tab ``" and label not in seen:
            seen.add(label)
            claims.append(label)
    for route in customer_experience.get("required_routes") or []:
        route_text = str(route or "").strip()
        if not route_text or route_text == "/" or not _PRODUCT_WORKFLOW_ROUTE_PATTERN.search(route_text):
            continue
        label = f"workflow route `{route_text}`"
        if label not in seen:
            seen.add(label)
            claims.append(label)
    return claims


def _product_workflow_claims_mvp_completeness(product_workflow: dict[str, Any] | None) -> bool:
    if not isinstance(product_workflow, dict):
        return False
    return any(
        product_workflow.get(key)
        for key in (
            "core_loop",
            "persistence_rules",
            "product_budget",
            "first_run",
            "success_moment",
            "acceptance_tests",
            "not_now",
            "actions",
            "outbound_hosts",
        )
    )


def _product_workflow_completion_gaps(product_workflow: dict[str, Any] | None) -> list[str]:
    if not isinstance(product_workflow, dict):
        return []
    gaps: list[str] = []

    def require_text(key: str) -> None:
        if not str(product_workflow.get(key) or "").strip():
            gaps.append(key)

    require_text("primary_user")
    require_text("workspace_model")
    require_text("primary_job")
    require_text("success_moment")

    core_loop = product_workflow.get("core_loop") if isinstance(product_workflow.get("core_loop"), dict) else {}
    for key in ("input", "action", "result"):
        if not str(core_loop.get(key) or "").strip():
            gaps.append(f"core_loop.{key}")
    if core_loop.get("save_record") is not True:
        gaps.append("core_loop.save_record=true")
    if core_loop.get("return_to_record_later") is not True:
        gaps.append("core_loop.return_to_record_later=true")

    persistence_rules = (
        product_workflow.get("persistence_rules")
        if isinstance(product_workflow.get("persistence_rules"), dict)
        else {}
    )
    if persistence_rules.get("requires_server_state") is not True:
        gaps.append("persistence_rules.requires_server_state=true")
    if not str(persistence_rules.get("persistence_rail") or "").strip():
        gaps.append("persistence_rules.persistence_rail")
    if persistence_rules.get("truthful_empty_state") is not True:
        gaps.append("persistence_rules.truthful_empty_state=true")
    if persistence_rules.get("reopenable_history") is not True:
        gaps.append("persistence_rules.reopenable_history=true")

    acceptance_tests = product_workflow.get("acceptance_tests") or []
    if not isinstance(acceptance_tests, list) or not [item for item in acceptance_tests if str(item or "").strip()]:
        gaps.append("acceptance_tests")
    return gaps


def _product_workflow_is_mvp_complete(product_workflow: dict[str, Any] | None) -> bool:
    return bool(product_workflow) and not _product_workflow_completion_gaps(product_workflow)


def _validate_product_workflow_contract(
    *,
    surface: dict[str, Any] | None,
    runtime_features: list[str],
    customer_experience: dict[str, Any] | None = None,
    product_workflow: dict[str, Any] | None = None,
) -> None:
    return


def _render_product_workflow_range_label(label: str, raw: Any) -> str:
    if not isinstance(raw, dict):
        return ""
    minimum = raw.get("min")
    maximum = raw.get("max")
    if minimum is None and maximum is None:
        return ""
    if minimum is not None and maximum is not None:
        return f"{label} {minimum}-{maximum}"
    if minimum is not None:
        return f"{label} >= {minimum}"
    return f"{label} <= {maximum}"


def _is_shared_runtime_route_path(path: str) -> bool:
    route = str(path or "").strip()
    if not route:
        return False
    route = route.rstrip("/") or "/"
    if not route.startswith("/"):
        route = "/" + route
    route = route.lower()
    if route == "/records" or route.startswith("/records/"):
        return True
    if route == "/directory" or route.startswith("/directory/"):
        return True
    for rail in PRODUCT_RUNTIME_RAILS.values():
        endpoints = rail.get("endpoints") if isinstance(rail, dict) else ()
        for _method, endpoint in endpoints or ():
            candidate = "/" + str(endpoint or "").strip().lstrip("/")
            candidate = candidate.rstrip("/") or "/"
            if route == candidate.lower():
                return True
    return False


def _surface_has_explicit_workflow_route(routes: list[str] | None) -> bool:
    for route in routes or []:
        route_value = str(route or "").strip()
        if not route_value or route_value == "/" or _is_shared_runtime_route_path(route_value):
            continue
        if _PRODUCT_WORKFLOW_ROUTE_PATTERN.search(route_value):
            return True
    return False


def _surface_shape_requires_app_shell(
    *,
    runtime_features: list[str] | None = None,
    required_app_tabs: list[str] | None = None,
    required_routes: list[str] | None = None,
) -> bool:
    # App-shell need is derived from real signals — an explicit workflow route,
    # a declared access/AI rail, or app tabs — not from app-shape taxonomy.
    if _surface_has_explicit_workflow_route(required_routes):
        return True
    runtime_feature_set = set(runtime_features or [])
    if {"auth", "account", "checkout", "generate"} & runtime_feature_set:
        return True
    if required_app_tabs:
        return True
    return False


def _surface_requires_app_shell(
    surface: dict[str, Any] | None,
    *,
    runtime_features: list[str] | None = None,
    required_app_tabs: list[str] | None = None,
    required_routes: list[str] | None = None,
) -> bool:
    if _surface_product_workflow_shape(surface):
        return True
    if _surface_allows_landing_only(surface):
        return False
    return _surface_shape_requires_app_shell(
        runtime_features=runtime_features,
        required_app_tabs=required_app_tabs,
        required_routes=required_routes,
    )


def _normalize_required_routes_for_surface(
    surface: dict[str, Any] | None,
    *,
    required_routes: list[str],
    required_app_tabs: list[str] | None = None,
) -> list[str]:
    normalized: list[str] = []
    seen: set[str] = set()
    for route in required_routes:
        text = str(route or "").strip()
        if not text:
            continue
        route_value = text.rstrip("/") or "/"
        if route_value in seen:
            continue
        seen.add(route_value)
        normalized.append(route_value)
    if not _surface_requires_app_shell(
        surface,
        runtime_features=_surface_runtime_features(surface),
        required_app_tabs=required_app_tabs,
        required_routes=required_routes,
    ):
        return normalized
    for required in ("/", "/app"):
        if required not in seen:
            normalized.append(required)
            seen.add(required)
    return normalized


def _surface_customer_experience_shape(surface: dict[str, Any] | None) -> dict[str, Any]:
    payload = _surface_customer_experience_metadata(surface)
    required_app_tabs = _normalize_surface_string_list(
        payload.get("required_app_tabs") if payload.get("required_app_tabs") is not None else payload.get("tabs")
    )
    required_routes = _normalize_required_routes_for_surface(
        surface,
        required_routes=_normalize_surface_string_list(
            payload.get("required_routes") if payload.get("required_routes") is not None else payload.get("routes")
        ),
        required_app_tabs=required_app_tabs,
    )
    research_sources = _normalize_surface_string_list(
        payload.get("research_sources")
        if payload.get("research_sources") is not None
        else payload.get("research")
    )
    if not research_sources:
        research_sources = list(DEFAULT_CUSTOMER_EXPERIENCE_RESEARCH_SOURCES)
    return {
        "surface_goal": str(payload.get("surface_goal") or "").strip(),
        "conversion_model": str(payload.get("conversion_model") or "").strip(),
        "required_routes": required_routes,
        "required_sections": _normalize_surface_string_list(
            payload.get("required_sections") if payload.get("required_sections") is not None else payload.get("sections")
        ),
        "required_app_tabs": required_app_tabs,
        "research_sources": research_sources,
    }


def _merge_customer_experience_metadata(
    metadata: dict[str, Any] | None,
    *,
    surface_goal: Any = None,
    conversion_model: Any = None,
    required_routes: Any = None,
    required_sections: Any = None,
    required_app_tabs: Any = None,
    research_sources: Any = None,
) -> dict[str, Any]:
    merged = dict(metadata if isinstance(metadata, dict) else {})
    existing = merged.get("customer_experience") if isinstance(merged.get("customer_experience"), dict) else {}
    next_payload = {
        key: existing[key]
        for key in (
            "surface_goal",
            "conversion_model",
            "required_routes",
            "required_sections",
            "required_app_tabs",
            "research_sources",
        )
        if key in existing
    }

    def _merge_text_field(key: str, raw: Any) -> None:
        if raw is None:
            return
        text = str(raw or "").strip()
        if text:
            next_payload[key] = text
        else:
            next_payload.pop(key, None)

    def _merge_list_field(key: str, raw: Any, *, fallback: tuple[str, ...] | None = None) -> None:
        if raw is None:
            if key not in next_payload and fallback:
                next_payload[key] = list(fallback)
            return
        normalized = _normalize_surface_string_list(raw)
        if normalized:
            next_payload[key] = normalized
        else:
            next_payload.pop(key, None)
            if fallback:
                next_payload[key] = list(fallback)

    _merge_text_field("surface_goal", surface_goal)
    _merge_text_field("conversion_model", conversion_model)
    _merge_list_field("required_routes", required_routes)
    _merge_list_field("required_sections", required_sections)
    _merge_list_field("required_app_tabs", required_app_tabs)
    _merge_list_field("research_sources", research_sources, fallback=DEFAULT_CUSTOMER_EXPERIENCE_RESEARCH_SOURCES)

    if not next_payload.get("research_sources"):
        next_payload["research_sources"] = list(DEFAULT_CUSTOMER_EXPERIENCE_RESEARCH_SOURCES)
    merged["customer_experience"] = next_payload
    return merged


def _starter_plan_shape_payload(plans: list[dict[str, Any]] | None) -> list[dict[str, Any]]:
    payloads: list[dict[str, Any]] = []
    for raw in plans or []:
        if not isinstance(raw, dict):
            continue
        plan_key = str(raw.get("plan_key") or "").strip()
        if not plan_key:
            continue
        payloads.append(
            {
                "planKey": plan_key,
                "tier": str(raw.get("tier") or "").strip(),
                "priceCents": int(raw.get("price_cents") or 0),
                "currency": str(raw.get("currency") or "usd").strip().lower() or "usd",
                "billingInterval": _normalize_billing_interval(raw.get("billing_interval") or "month"),
                "includedAiBudgetMicrousd": int(raw.get("included_ai_budget_microusd") or 0),
                "includedActionQuota": int(raw.get("included_action_quota") or 0),
            }
        )
    return payloads


def _subuser_public_env_value(*names: str) -> str:
    resolved_names: list[str] = []
    for raw_name in names:
        name = str(raw_name or "").strip()
        if not name:
            continue
        resolved_names.append(name)
        direct = str(os.getenv(name) or "").strip()
        if direct:
            return direct
    if not resolved_names:
        return ""
    try:
        mirrored = str(safebox.first_env_backed_value(*resolved_names) or "").strip()
    except Exception:
        mirrored = ""
    if mirrored:
        return mirrored
    for name in resolved_names:
        try:
            mirrored = str(safebox.read_env_backed_value(name) or "").strip()
        except Exception:
            mirrored = ""
        if mirrored:
            return mirrored
    return ""


def _subuser_public_auth_payload(surface: dict[str, Any] | None) -> dict[str, Any] | None:
    if "auth" not in set(_surface_effective_runtime_features(surface)):
        return None
    project_url = _subuser_public_env_value(
        "SUPABASE_URL",
        "NEXT_PUBLIC_SUPABASE_URL",
        "TAKYON_SUPABASE_URL",
    )
    publishable_key = _subuser_public_env_value(
        "SUPABASE_PUBLISHABLE_KEY",
        "SUPABASE_ANON_KEY",
        "NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY",
        "NEXT_PUBLIC_SUPABASE_ANON_KEY",
    )
    configured = bool(project_url and publishable_key)
    return {
        "provider": "supabase",
        "configured": configured,
        "url": project_url,
        "publishableKey": publishable_key,
        "googleProvider": "google",
        "redirectPath": "/app",
    }


# The canonical site-relative URL a published (paid) brand logo is served at. business_generate_logo
# copies its generated PNG into the site's public/ under this name; vite copies public/ verbatim into
# dist/, so a successful logo run makes the REAL logo replace the bootstrap monogram everywhere the UI
# renders the brand mark (header + landing) and in the browser tab.
_PUBLISHED_BRAND_LOGO_FILENAME = "brand-logo.png"
_PUBLISHED_BRAND_LOGO_URL = f"/{_PUBLISHED_BRAND_LOGO_FILENAME}"


def _published_brand_logo_url(workspace_root: Path) -> str:
    """``/brand-logo.png`` if a paid logo PNG was published into the site's public/ dir, else "".
    Used to make the surface-context prefer the generated logo over the deterministic monogram."""
    try:
        if (workspace_root / "public" / _PUBLISHED_BRAND_LOGO_FILENAME).is_file():
            return _PUBLISHED_BRAND_LOGO_URL
    except OSError:
        pass
    return ""


def _read_bootstrap_hero_copy(workspace_root: "Path | None") -> dict[str, str]:
    """Idea-branded hero copy the bootstrap writes to ``product/hero.json`` from the step-1 brief,
    so the FIRST published landing is on-message before the slower full design pass. Best-effort and
    fail-soft: any read/parse problem returns {} and the landing falls back to the generic welcome."""
    business_root = _starter_business_root(Path(workspace_root) if workspace_root is not None else None)
    if business_root is None:
        return {}
    try:
        hero_path = business_root / "product" / "hero.json"
        if not hero_path.is_file():
            return {}
        data = json.loads(hero_path.read_text(encoding="utf-8") or "{}")
    except (OSError, ValueError):
        return {}
    if not isinstance(data, dict):
        return {}
    out: dict[str, str] = {}
    for key in ("eyebrow", "headline", "subhead"):
        value = str(data.get(key) or "").strip()
        if value:
            out[key] = value[:240]
    return out


def _read_shopify_catalog_products(workspace_root: "Path | None") -> list[dict[str, Any]]:
    """The business's buyable Shopify catalog (``product/shopify-catalog.json``), materialized into
    the surface context at publish time so EVERY shopify_commerce product site renders a store
    section with Buy buttons — the SAME publish-time-injection wiring as ``plans``/``hero``. The
    mirror file is written by ``business_shopify_create_product`` (buyable catalog projection),
    which already excludes drafts/variant-less products, so every entry here is public + buyable.
    Fail-soft: any missing file / parse problem returns [] and the site shows no store section — a
    non-Shopify business has no catalog file, so it is unaffected by construction.

    (Restored 2026-07-08: originally landed in 6755be74; a concurrent stale-base core.py push
    (8a0eeb2a) clobbered it while its tests/scaffold half survived — the storefront-rail suite
    pins it against regressing again.)"""
    business_root = _starter_business_root(Path(workspace_root) if workspace_root is not None else None)
    if business_root is None:
        return []
    try:
        # product/shopify-catalog.json == shopify_util.SHOPIFY_CATALOG_RELPATH.
        catalog_path = business_root / "product" / "shopify-catalog.json"
        if not catalog_path.is_file():
            return []
        data = json.loads(catalog_path.read_text(encoding="utf-8") or "{}")
    except (OSError, ValueError):
        return []
    products = data.get("products") if isinstance(data, dict) else None
    if not isinstance(products, list):
        return []
    out: list[dict[str, Any]] = []
    for product in products:
        if not isinstance(product, Mapping):
            continue
        title = str(product.get("title") or "").strip()
        permalink = str(product.get("cart_permalink") or "").strip()
        if not title or not permalink:
            continue  # only released, buyable products reach the public bake
        out.append(
            {
                "product_id": str(product.get("product_id") or ""),
                "title": title[:200],
                "price": str(product.get("price") or ""),
                "handle": str(product.get("handle") or ""),
                "cart_permalink": permalink,
                "preview_url": str(product.get("preview_url") or ""),
            }
        )
    return out


def _subuser_surface_context_payload(
    surface: dict[str, Any] | None,
    *,
    slug: str,
    plans: list[dict[str, Any]] | None = None,
    brand_logo_url: str = "",
    workspace_root: "Path | None" = None,
) -> dict[str, Any]:
    shape = _surface_subuser_app_shape(surface)
    routes = _surface_routes(surface)
    effective_runtime_features = _surface_effective_runtime_features(surface)
    hero = _read_bootstrap_hero_copy(workspace_root)
    return {
        "heroEyebrow": hero.get("eyebrow", ""),
        "heroHeadline": hero.get("headline", ""),
        "heroSubhead": hero.get("subhead", ""),
        "business": slug,
        "frontendApiMode": SUBUSER_FRONTEND_API_MODE,
        "kitPath": shape.get("kit_path") or SUBUSER_KIT_DIRNAME,
        "frontendStack": shape.get("frontend_stack") or DEFAULT_SUBUSER_FRONTEND_STACK,
        "runtimeApiBase": f"/api/takyon/apps/{slug}",
        "runtimeFeatures": effective_runtime_features,
        "railState": shape.get("rail_state") or {},
        "auth": _subuser_public_auth_payload(surface),
        "plans": _starter_plan_shape_payload(plans),
        # Buyable Shopify storefront, baked at publish for every business that has pushed products
        # (empty for non-Shopify businesses). The scaffold reads this as ``productCatalog`` and
        # renders the Store section whose Buy buttons deep-link each product's cart_permalink.
        "shopifyCatalog": _read_shopify_catalog_products(workspace_root),
        "routes": routes,
        "publishTarget": _product_publish_target(slug, (surface or {}).get("publish_target") if isinstance(surface, dict) else None),
        "publicUrl": str((surface or {}).get("public_url") or ""),
        "notes": str((surface or {}).get("notes") or ""),
        # Free deterministic brand mark so the product UI can render a monogram/accent
        # without a paid logo call. business_generate_logo (credit-gated) publishes a real logo PNG
        # into public/, and ``brandLogoUrl`` below then makes the UI prefer it over this monogram.
        "brandAccent": _brand_mark_accent(slug),
        "brandMarkSvg": _brand_mark_svg(slug),
        # "" until a paid logo is published; "/brand-logo.png" once business_generate_logo succeeds.
        "brandLogoUrl": str(brand_logo_url or ""),
    }


def _merge_subuser_app_metadata(
    metadata: dict[str, Any] | None,
    *,
    runtime_features: list[str],
    previous_runtime_features: list[str] | None = None,
    rail_state: Any = None,
    frontend_stack: Any = None,
) -> dict[str, Any]:
    merged = dict(metadata if isinstance(metadata, dict) else {})
    existing = merged.get("subuser_app") if isinstance(merged.get("subuser_app"), dict) else {}
    next_payload = dict(existing)
    # Shed deleted app-shape taxonomy from any previously-persisted metadata so
    # stored state never carries the removed fields forward.
    for stale_key in ("app_mode", "subscription_style", "api_mode"):
        next_payload.pop(stale_key, None)
    normalized_frontend_stack = _normalize_frontend_stack_choice(frontend_stack)
    if normalized_frontend_stack:
        next_payload["frontend_stack"] = normalized_frontend_stack
    else:
        existing_frontend_stack = _normalize_frontend_stack_choice(existing.get("frontend_stack"))
        if existing_frontend_stack:
            next_payload["frontend_stack"] = existing_frontend_stack
        else:
            next_payload.pop("frontend_stack", None)
    raw_rail_state = rail_state if rail_state is not None else existing.get("rail_state")
    normalized_rail_state = _normalize_subuser_rail_state(raw_rail_state, declared_rails=runtime_features)
    next_payload["rail_state"] = normalized_rail_state
    next_payload["frontend_api_mode"] = SUBUSER_FRONTEND_API_MODE
    next_payload["kit_path"] = SUBUSER_KIT_DIRNAME
    merged["subuser_app"] = next_payload
    return merged


def _runtime_rails_for_owner(surface: dict[str, Any] | None, owner_skill: str) -> list[tuple[str, dict[str, Any]]]:
    owner = str(owner_skill or "").strip().lower()
    selected = _surface_runtime_features(surface)
    rails: list[tuple[str, dict[str, Any]]] = []
    for key in selected:
        spec = PRODUCT_RUNTIME_RAILS.get(key)
        if not spec:
            continue
        if str(spec.get("owner_skill") or "").strip().lower() == owner:
            rails.append((key, spec))
    return rails


def _workspace_needs_runtime_ui_contract(workspace_raw: str) -> bool:
    normalized = workspace_raw.strip("/").lower()
    return normalized == "product/site" or normalized.startswith("product/site/")


def _canonical_product_surface_source_path(source_path: str) -> str:
    normalized = _safe_relpath(source_path or "product/site", field="source_path").as_posix()
    if _workspace_needs_runtime_ui_contract(normalized):
        return "product/site"
    return normalized


def _enforce_canonical_product_surface_source_path(
    *,
    business: str,
    existing_source_path: str,
    requested_source_path: str,
    context: str,
) -> str:
    existing_raw = str(existing_source_path or "").strip()
    requested = _canonical_product_surface_source_path(
        requested_source_path or existing_raw or "product/site"
    )
    if not existing_raw:
        return requested
    existing = _canonical_product_surface_source_path(existing_raw)
    if requested != existing:
        raise TakyonError(
            f"{context} refused for business '{business}': product surface source_path "
            f"is anchored to '{existing}' and cannot switch to '{requested}'"
        )
    return requested


def _subuser_app_kit_source_dir() -> Path:
    return Path(__file__).resolve().parent / "subuser_app_kit"


def _render_runtime_endpoint_hints(
    endpoints: list[tuple[str, str]],
    *,
    runtime_api_base: str,
) -> str:
    rendered: list[str] = []
    base = runtime_api_base.rstrip("/")
    for method, route in endpoints:
        if base:
            rendered.append(f"{method} /{route} on product hosts or {method} {base}/{route} off-host")
        else:
            rendered.append(f"{method} /{route} on product hosts or {method} <runtime_api_base>/{route} off-host")
    return ", ".join(rendered)


def _materialized_surface_for_workspace(
    workspace_root: Path,
    *,
    surface: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(surface, dict):
        return surface
    try:
        from . import app_actions as takyon_app_actions
    except Exception:
        from plugins.takyon import app_actions as takyon_app_actions
    surface_with_workflow = {
        **surface,
        "product_workflow": _surface_product_workflow_shape(surface),
    }
    file_rails: list[str] = []
    runtime_features = _surface_runtime_features(surface)
    if takyon_app_actions.site_http_action_names(workspace_root, surface_with_workflow):
        file_rails.append("actions")
    # Self-declare every build-derived rail the app's source actually calls (records, media,
    # directory, connections, generate, search) — symmetric with how `actions` is derived from
    # on-disk action files above — so the declared contract stays honest to the build.
    for rail in takyon_app_actions.referenced_runtime_rails_in_source(workspace_root):
        if rail in _BUILD_DERIVED_RAILS and rail not in file_rails:
            file_rails.append(rail)
    return {
        **surface_with_workflow,
        "runtime_features": runtime_features,
        "_workspace_file_rails": file_rails,
    }


def _materialize_subuser_app_kit(
    workspace_root: Path,
    *,
    slug: str,
    surface: dict[str, Any] | None,
    plans: list[dict[str, Any]] | None = None,
) -> None:
    target_root = workspace_root / SUBUSER_KIT_DIRNAME
    target_root.mkdir(parents=True, exist_ok=True)
    kit_source = _subuser_app_kit_source_dir()
    if kit_source.exists():
        for path in sorted(kit_source.rglob("*")):
            if not path.is_file():
                continue
            rel = path.relative_to(kit_source)
            # scaffold/ is the seed source for new vite_react_ts products, not part of
            # the runtime kit payload; node_modules/dist are local build artifacts.
            if rel.parts and rel.parts[0] == "scaffold":
                continue
            if {"node_modules", "dist", ".git"} & set(rel.parts):
                continue
            destination = target_root / rel
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, destination)
    materialized_surface = _materialized_surface_for_workspace(workspace_root, surface=surface)
    context_payload = _subuser_surface_context_payload(
        materialized_surface,
        slug=slug,
        plans=plans,
        brand_logo_url=_published_brand_logo_url(workspace_root),
        workspace_root=workspace_root,
    )
    (target_root / "surface-context.js").write_text(
        "export const surfaceContext = "
        + json.dumps(context_payload, ensure_ascii=False, indent=2, sort_keys=True)
        + ";\nexport const subuserSurfaceContext = surfaceContext;\nexport default surfaceContext;\n",
        encoding="utf-8",
    )
    _materialize_subuser_app_starter(workspace_root, slug=slug, surface=materialized_surface)
    # After the (seed-once) starter, force-refresh the scaffold-owned metadata + AppKit rails so
    # canonical SEO/auth/checkout/entitlement fixes reach existing businesses on rebuild, not just
    # new ones. Worker-owned screens are untouched.
    _rematerialize_starter_owned_files(workspace_root, slug=slug, surface=materialized_surface)
    # Tab favicon = the business logo on EVERY rebuild, not just first materialize. The scaffold-only
    # path (_materialize_subuser_app_scaffold) seeds + repoints the favicon, but it short-circuits for
    # any already-built business (the seed-once starter returns early once product source exists). So
    # without this, a business that publishes a real logo (public/brand-logo.png) AFTER bootstrap keeps
    # the seeded monogram in its browser tab forever. Re-run the deterministic favicon injector here so
    # a published logo becomes the tab favicon on the next normal build — no paid re-generation needed.
    # Idempotent: a no-op when the favicon already points at the right asset.
    _seed_brand_mark_assets(workspace_root, slug=slug)
    _inject_favicon_links(workspace_root)


def _mobile_app_scaffold_source_dir() -> Path:
    return Path(__file__).resolve().parent / "mobile_app_kit" / "scaffold"


def _workspace_is_mobile_app_dir(workspace_raw: str) -> bool:
    normalized = str(workspace_raw or "").strip().strip("/").lower()
    return normalized == "product/app" or normalized.startswith("product/app/")


def _materialize_mobile_app_workspace(
    workspace_root: Path,
    *,
    slug: str,
    business_name: str,
    description: str,
    surface: dict[str, Any] | None,
) -> bool:
    """The mobile analog of ``_materialize_subuser_app_kit`` — THE consumer of the archetype
    preset's ``scaffold`` field (readmodular §4). Seed-once: copies ``mobile_app_kit/scaffold``
    into ``product/app`` with the business tokens filled when no app.json exists yet; then ALWAYS
    force-refreshes the platform-owned ``_takyon/`` boundary (runtime client + a per-business
    surface-context with the ABSOLUTE runtimeApiBase and real Supabase auth config), mirroring the
    web kit's rematerialize rule. Returns True when the scaffold was newly seeded."""
    source = _mobile_app_scaffold_source_dir()
    if not source.is_dir():
        raise TakyonError("mobile_app scaffold missing from the runtime (mobile_app_kit/scaffold)")
    canonical_slug = _slugify(slug)
    # Free-text business fields are substituted into TSX/JSON string literals — strip every
    # character that could escape a literal (quotes, backslashes, template/JSX delimiters,
    # newlines). app.json gets its values via json.dumps assignment below, never str.replace.
    def _display_safe(raw: str, fallback: str, limit: int) -> str:
        cleaned = re.sub(r"[^\w ,.&'!?()’-]+", " ", str(raw or ""))
        cleaned = re.sub(r"\s+", " ", cleaned).strip()[:limit].strip()
        return cleaned or fallback
    display_name = _display_safe(business_name, canonical_slug, 60)
    display_description = _display_safe(description, f"{display_name} mobile app", 160)
    seeded = False
    if not (workspace_root / "app.json").is_file():
        substitutions = {
            "__TAKYON_APP_NAME__": display_name,
            "__TAKYON_SLUG__": canonical_slug,
            "__TAKYON_APP_DESCRIPTION__": display_description,
            "__TAKYON_ORG__": "coscale",
            "__EXPO_ORG__": "coscale",
        }
        # app.json is the seed-completion marker (its absence gates re-seeding), so it is written
        # LAST — a crash mid-copy re-seeds cleanly instead of wedging on a partial tree.
        app_json_source: Path | None = None
        for path in sorted(source.rglob("*")):
            if not path.is_file():
                continue
            rel = path.relative_to(source)
            if {"node_modules", ".git", "dist"} & set(rel.parts):
                continue
            if rel.as_posix() == "app.json":
                app_json_source = path
                continue
            destination = workspace_root / rel
            destination.parent.mkdir(parents=True, exist_ok=True)
            try:
                text = path.read_text(encoding="utf-8")
            except (UnicodeDecodeError, ValueError):
                shutil.copy2(path, destination)
                continue
            for token, value in substitutions.items():
                text = text.replace(token, value)
            destination.write_text(text, encoding="utf-8")
        if app_json_source is None:
            raise TakyonError("mobile_app scaffold is missing app.json")
        # JSON-safe fill: slug/org tokens have a validated charset; the free-text name/description
        # are ASSIGNED onto the parsed config so json.dumps owns the escaping. `eas init` assigns
        # the real project id at build time (store_builder); the placeholder updates/projectId
        # entries would otherwise break `expo config` on the seeded tree.
        app_text = app_json_source.read_text(encoding="utf-8")
        app_text = app_text.replace("__TAKYON_SLUG__", canonical_slug).replace("__TAKYON_ORG__", "coscale")
        app_text = app_text.replace("__TAKYON_APP_NAME__", "app").replace("__TAKYON_APP_DESCRIPTION__", "app")
        app_text = app_text.replace("__EXPO_ORG__", "coscale")
        app_cfg = json.loads(app_text)
        expo_cfg = app_cfg.get("expo") or {}
        expo_cfg["name"] = display_name
        expo_cfg["description"] = display_description
        expo_cfg.pop("updates", None)
        (expo_cfg.get("extra") or {}).get("eas", {}).pop("projectId", None)
        expo_cfg["owner"] = "coscale"
        app_cfg["expo"] = expo_cfg
        (workspace_root / "app.json").write_text(json.dumps(app_cfg, indent=2) + "\n", encoding="utf-8")
        seeded = True
    # Platform-owned boundary: force-refresh every run so client/context fixes reach existing
    # app workspaces, exactly like _rematerialize_appkit_owned_src on the web side.
    kit_dir = workspace_root / "_takyon"
    kit_dir.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source / "_takyon" / "runtime-client.ts", kit_dir / "runtime-client.ts")
    auth_payload = _subuser_public_auth_payload(surface) or {}
    context = {
        "runtimeApiBase": f"https://{canonical_slug}.{_company_base_domain()}/api/takyon/apps/{canonical_slug}",
        "runtimeFeatures": _surface_effective_runtime_features(surface),
        "railState": (_surface_subuser_app_shape(surface) or {}).get("rail_state") or {},
        "auth": {
            "url": str(auth_payload.get("url") or ""),
            "publishableKey": str(auth_payload.get("publishableKey") or ""),
            "googleProvider": str(auth_payload.get("googleProvider") or "google"),
        },
        "branding": {"accent": _brand_mark_accent(slug), "name": (business_name or canonical_slug).strip()},
    }
    (kit_dir / "surface-context.ts").write_text(
        "// PLATFORM-OWNED — materialized per business; do not edit.\n"
        'import type { SurfaceContext } from "./runtime-client";\n\n'
        "export const surfaceContext: SurfaceContext = "
        + json.dumps(context, ensure_ascii=False, indent=2)
        + ";\n",
        encoding="utf-8",
    )
    return seeded


def _surface_requires_subuser_app_starter(surface: dict[str, Any] | None) -> bool:
    return _surface_shape_requires_app_shell(
        runtime_features=_surface_runtime_features(surface),
        required_routes=_surface_routes(surface),
    )


def _humanize_business_slug(slug: str) -> str:
    parts = [part for part in re.split(r"[^a-z0-9]+", str(slug or "").strip().lower()) if part]
    if not parts:
        return "Workspace"
    return " ".join(part.capitalize() for part in parts)


def _starter_business_root(workspace_root: Path | None) -> Path | None:
    if workspace_root is None:
        return None
    root = Path(workspace_root)
    if root.name == "site" and root.parent.name == "product":
        return root.parent.parent
    return root


def _starter_strategy_sections(workspace_root: Path | None) -> tuple[str, dict[str, str]]:
    business_root = _starter_business_root(workspace_root)
    if business_root is None:
        return "", {}
    strategy_path = business_root / "research" / "strategy.md"
    try:
        body = strategy_path.read_text(encoding="utf-8")
    except OSError:
        return "", {}
    if not body.strip():
        return "", {}

    heading_re = re.compile(r"^(#{1,6})\s+(.*)$")
    title = ""
    current_section = ""
    current_lines: list[str] = []
    sections: dict[str, str] = {}

    def _flush() -> None:
        nonlocal current_section, current_lines
        if current_section:
            sections[current_section] = "\n".join(current_lines).strip()
        current_lines = []

    for raw_line in body.splitlines():
        match = heading_re.match(raw_line)
        if match:
            level = len(match.group(1))
            heading = match.group(2).strip()
            if level == 1 and not title:
                title = heading
            if level <= 2:
                _flush()
                current_section = _normalize_heading_text(heading) if level == 2 else ""
                continue
        if current_section:
            current_lines.append(raw_line)

    _flush()
    return title, sections


def _starter_strategy_first_line(value: str) -> str:
    for raw_line in str(value or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        line = re.sub(r"^[-*•>]+\s*", "", line)
        line = re.sub(r"[*_`]+", "", line).strip()
        if line:
            return line
    return ""


def _starter_strategy_title(value: str, *, slug: str) -> str:
    title = _starter_strategy_first_line(value)
    if not title:
        return _humanize_business_slug(slug)
    title = re.sub(r"\s*\([^)]*\)\s*$", "", title).strip()
    title = re.split(r"\s+[—-]\s+", title, maxsplit=1)[0].strip()
    return title or _humanize_business_slug(slug)


def _sanitize_starter_title(title: str, *, slug: str, max_len: int = 90) -> str:
    """Final hygiene for the machine-derived public <title>: never slug-embedded, never
    paragraph-length. Salvages a usable clause rather than regressing to the bare slug."""
    text = str(title or "").strip()
    slug_l = str(slug or "").strip().lower()
    if slug_l:
        # Drop a LEADING slug mention ("<slug> helps ..." -> "Helps ..."); if the slug still
        # appears mid-string, cut the title at the clause boundary before it.
        pattern = re.compile(rf"^\W*{re.escape(slug_l)}\b[\s:,-]*", re.IGNORECASE)
        text = pattern.sub("", text).strip()
        mid = re.search(rf"(?<![a-z0-9]){re.escape(slug_l)}(?![a-z0-9])", text, re.IGNORECASE)
        if mid:
            text = text[: mid.start()].rstrip(" ,;:-").strip()
    if len(text) > max_len:
        # One clause: cut at the first sentence/clause boundary past nothing, else word-cut.
        cut = re.split(r"(?<=[.!?])\s|,\s(?=so\b|and\b|which\b)", text, maxsplit=1)[0].strip()
        text = cut if len(cut) <= max_len else cut[:max_len].rsplit(" ", 1)[0].rstrip(" ,;:-")
    text = text.strip().rstrip(",;:-").strip()
    if text and text[0].islower():
        text = text[0].upper() + text[1:]
    return text or _humanize_business_slug(slug)


def _starter_title_is_generic(title: str, *, slug: str) -> bool:
    value = str(title or "").strip().lower()
    if not value:
        return True
    if value == str(slug or "").strip().lower():
        return True
    if value == _humanize_business_slug(slug).strip().lower():
        return True
    # A title that still CONTAINS the internal slug as a token is slug-derived junk, not a
    # product name — CEO strategy docs are routinely headed "<slug> Strategy (Brief)", and the
    # old exact-match check let those through as the public <title>/og:title on fresh builds
    # (observed live: "qaproof0708b Strategy", "acceptinvoice0708 strategy"). Rejecting it here
    # makes the chain fall through to the worker-authored hero headline / landing <h1> — the
    # same source that produced the good value-prop titles on droppop/magicslides.
    slug_token = re.escape(str(slug or "").strip().lower())
    if slug_token and re.search(rf"(?<![a-z0-9]){slug_token}(?![a-z0-9])", value):
        return True
    return False


def _starter_workspace_marketing_copy(workspace_root: Path | None) -> dict[str, str]:
    if workspace_root is None:
        return {}

    def _clean_literal(value: str) -> str:
        text = re.sub(r"{[^}]*}", " ", value)
        text = re.sub(r"<[^>]+>", " ", text)
        text = re.sub(r"\s+", " ", text).strip()
        return re.sub(r"[*_`]+", "", text).strip()

    copy: dict[str, str] = {}
    hero = _read_bootstrap_hero_copy(workspace_root)
    if hero.get("headline"):
        copy["title"] = str(hero["headline"]).strip()[:160]
    if hero.get("subhead"):
        copy["description"] = str(hero["subhead"]).strip()[:240]
    if copy.get("title") and copy.get("description"):
        return copy

    landing_path = Path(workspace_root) / "src" / "screens" / "landing.tsx"
    try:
        landing = landing_path.read_text(encoding="utf-8")
    except OSError:
        return copy

    for match in re.finditer(r"<h1\b[^>]*>(.*?)</h1>", landing, flags=re.DOTALL):
        title = _clean_literal(match.group(1))
        if title and "Welcome to" not in title:
            copy.setdefault("title", title[:160])
            break
    for match in re.finditer(r"<p\b[^>]*>(.*?)</p>", landing, flags=re.DOTALL):
        description = _clean_literal(match.group(1))
        if description and "Sign in with Google" not in description and len(description) >= 24:
            copy.setdefault("description", description[:240])
            break
    return copy


def _subuser_app_starter_strings(
    surface: dict[str, Any] | None,
    *,
    slug: str,
    workspace_root: Path | None = None,
) -> dict[str, Any]:
    strategy_title, strategy_sections = _starter_strategy_sections(workspace_root)
    workspace_copy = _starter_workspace_marketing_copy(workspace_root)
    title = _starter_strategy_title(
        strategy_sections.get("business name") or strategy_title,
        slug=slug,
    )
    if _starter_title_is_generic(title, slug=slug) and workspace_copy.get("title"):
        title = str(workspace_copy["title"]).strip() or _humanize_business_slug(slug)
    if _starter_title_is_generic(title, slug=slug):
        title = _starter_strategy_title(strategy_sections.get("tagline") or "", slug=slug)
    if _starter_title_is_generic(title, slug=slug):
        title = _starter_strategy_title(
            strategy_sections.get("core value proposition") or "",
            slug=slug,
        )
    # The LAST candidate above was never re-checked, so a slug-embedded value prop shipped as
    # the public <title> verbatim ("paylane0708 helps freelancers ...", 200+ chars, 2026-07-08).
    # Salvage instead of falling back to the bare slug: drop a LEADING slug mention (the CEO's
    # docs routinely open with "<slug> helps ..."), recapitalize, and bound to one title-length
    # sentence clause. Only if nothing salvageable remains does the humanized slug fallback apply.
    title = _sanitize_starter_title(title, slug=slug)
    description = str((surface or {}).get("notes") or "").strip()
    if not description:
        description = _starter_strategy_first_line(strategy_sections.get("tagline") or "")
    if not description:
        description = _starter_strategy_first_line(strategy_sections.get("core value proposition") or "")
    if not description:
        description = str(workspace_copy.get("description") or "").strip()
    # A minimal strategy (just the slug + one-line goal, no business-name/tagline/value-prop
    # section) with an unextractable hero headline leaves the title as the bare humanized slug
    # even when a real value prop DID resolve into the description (observed: sdkfix0708b shipped
    # <title>Sdkfix0708b</title> while the meta description was a real tagline). Never ship the
    # bare slug as the title when real copy exists: derive the title from the first sentence of
    # that description. Runs before the generic "Get started with ..." description fallback so we
    # only borrow genuine value-prop copy, never the boilerplate.
    if _starter_title_is_generic(title, slug=slug) and description:
        first_sentence = re.split(r"(?<=[.!?])\s", description, maxsplit=1)[0].strip()
        salvaged = _sanitize_starter_title(first_sentence or description, slug=slug)
        if not _starter_title_is_generic(salvaged, slug=slug):
            title = salvaged
    if not description:
        description = f"Get started with {title}, manage your account, and access the product online."
    return {
        "title": title,
        "description": description,
        "og_alt": f"{title} preview",
    }


def _starter_seed_replacements(
    surface: dict[str, Any] | None,
    *,
    slug: str,
    workspace_root: Path | None = None,
) -> dict[str, str]:
    copy = _subuser_app_starter_strings(surface, slug=slug, workspace_root=workspace_root)

    # Seed values land in JSX text / HTML attribute positions: keep them markup-safe.
    def _seed_safe(value: Any) -> str:
        return re.sub(r'["<>{}]', "", str(value or "")).strip()

    return {
        "__STARTER_SITE_NAME__": _seed_safe(copy.get("title")) or _humanize_business_slug(slug),
        "__STARTER_SITE_DESCRIPTION__": _seed_safe(copy.get("description")),
        # Public origin for technical-SEO artifacts (sitemap.xml, llms.txt, canonical, OG) seeded
        # into the build. Resolved from the slug + the current company base domain so a fresh
        # business ships a valid sitemap/canonical on coscale.app (never the legacy domain).
        "__STARTER_PUBLIC_ORIGIN__": f"https://{slug}.{_company_base_domain()}/",
        # GSC ownership: the platform service-account's stable verification META tag, baked into
        # index.html so EVERY build carries it from the first publish and the bootstrap verify
        # always finds it on the live edge (no build-pointer/R2 race). Fail-soft "" when the SA is
        # unavailable at seed time, in which case the GSC tool's own injection is the fallback.
        "__STARTER_GSC_VERIFICATION__": _resolve_gsc_verification_meta_tag(),
    }


