            r"@anthropic-ai/bedrock-sdk|@aws-sdk/client-bedrock-runtime|cohere-ai|"
            r"@mistralai/mistralai|together-ai|groq-sdk|replicate|@perplexity-ai/[^'\"]+|"
            r"openai-edge)['\"]|"
            r"require\(\s*['\"](?:@google/generative-ai|@google-cloud/vertexai|"
            r"@anthropic-ai/bedrock-sdk|@aws-sdk/client-bedrock-runtime|cohere-ai|"
            r"@mistralai/mistralai|together-ai|groq-sdk|replicate|@perplexity-ai/[^'\"]+|"
            r"openai-edge)['\"]\s*\)|"
