def _product_source_is_skipped(path: Path) -> bool:
    return any(part in _PRODUCT_SOURCE_SKIP_DIRS for part in path.parts)


def _is_reserved_product_runtime_route(route: str) -> bool:
    normalized = "/" + str(route or "").lstrip("/")
    return any(normalized.startswith(prefix) for prefix in _RESERVED_PRODUCT_RUNTIME_ROUTE_PREFIXES)


def _reserved_product_runtime_route_from_source_rel(source_rel: str) -> str | None:
    rel = str(source_rel or "").strip().lstrip("./")
    if rel.startswith("src/"):
        rel = rel[4:]
    parts = [part for part in rel.split("/") if part]
    if len(parts) >= 4 and parts[0] == "app" and parts[1] == "api" and parts[-1].startswith("route."):
        route = "/" + "/".join(parts[1:-1])
    elif len(parts) >= 3 and parts[0] == "pages" and parts[1] == "api":
        stem_parts = parts[1:]
        stem_parts[-1] = Path(stem_parts[-1]).stem
        route = "/" + "/".join(part for part in stem_parts if part != "index")
    else:
        return None
    return route if _is_reserved_product_runtime_route(route) else None


def _source_has_runtime_backing(text: str, *, source_rel: str = "") -> bool:
    if source_rel and _reserved_product_runtime_route_from_source_rel(source_rel):
        return False
    return any(pattern.search(text) for pattern in _RUNTIME_BACKED_PATTERNS)


def _surface_disallows_free_tier_copy(surface: dict[str, Any] | None) -> bool:
    # Every app-like, non-landing product surface is the paid monthly shape, so
    # free-tier customer copy is disallowed without operator opt-in.
    kind = _surface_contract_kind(surface)
    return bool(kind["app_like"] and not kind["landing_only"])


def _scan_for_pretend_product_state(root: Path, *, limit: int = 25) -> list[dict[str, Any]]:
    """Detect product-source code that pretends real auth/billing/integration state."""
    findings: list[dict[str, Any]] = []
    if not root.exists():
        return findings
    for path in sorted(root.rglob("*")):
        if len(findings) >= limit:
            break
        if not path.is_file() or path.suffix.lower() not in _PRODUCT_SOURCE_EXTENSIONS:
            continue
        if _product_source_is_skipped(path):
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        lines = text.splitlines()
        runtime_backed = _source_has_runtime_backing(text, source_rel=str(path.relative_to(root)))
        for number, line in enumerate(lines, start=1):
            for label, pattern in _PRETEND_PRODUCT_PATTERNS:
                if pattern.search(line):
                    findings.append(
                        {
                            "path": str(path.relative_to(root)),
                            "line": number,
                            "issue": label,
                            "snippet": line.strip()[:240],
                        }
                    )
                    break
            if "Loading..." in line and not runtime_backed:
                window = "\n".join(lines[max(0, number - 5): min(len(lines), number + 4)]).lower()
                if any(token in window for token in _ACCOUNT_LOADING_TOKENS):
                    findings.append(
                        {
                            "path": str(path.relative_to(root)),
                            "line": number,
                            "issue": "unbacked account/billing loading widget",
                            "snippet": line.strip()[:240],
                        }
                    )
            if len(findings) >= limit:
                break
    return findings


# Server-entrypoint shapes that must never ship in a product app, even smuggled
# into a build/skip directory (dist/, _takyon/, references/). A product app is a
# static client that talks only to the metered runtime gateway; any own server
# entrypoint is a place to host ungated backend AI.
_FORBIDDEN_SERVER_ENTRYPOINT_PATTERN = re.compile(
    r"""(?:
        from\s+['"](?:express|fastify|hono|koa|@hapi/hapi|next)['"]
      | require\(\s*['"](?:express|fastify|hono|koa|@hapi/hapi|next)['"]\s*\)
      | \b(?:app|server|httpServer)\s*\.\s*listen\s*\(
      | \bhttp\s*\.\s*createServer\s*\(
      | \bcreateServer\s*\(\s*\)\s*\.\s*listen\s*\(
      | \bnew\s+Hono\s*\(
      | \bnew\s+Koa\s*\(
    )""",
    re.IGNORECASE | re.VERBOSE,
)


def _scan_for_forbidden_product_backend_code(root: Path, *, limit: int = 25) -> list[dict[str, Any]]:
    """Detect product-source code that bypasses runtime/provider boundaries.

    Build-time gate (fail toward CLOSED). It is best-effort static analysis; the
    real enforcement boundary is the metered runtime gateway (/api/takyon/apps/),
    which is what actually prevents ungated paid AI spend at runtime. This catches
    the common bypasses: direct provider hosts, hardcoded provider API-key
    literals (any env-var name), direct external LLM API calls (allowlisting only
    the gateway base), provider-SDK imports, credential env reads, and smuggled
    server entrypoints — including ones hidden under build/skip directories.
    """
    findings: list[dict[str, Any]] = []
    if not root.exists():
        return findings
    for path in sorted(root.rglob("*")):
        if len(findings) >= limit:
            break
        if not path.is_file():
            continue
        suffix = path.suffix.lower()
        rel = str(path.relative_to(root))
        # node_modules holds installed DEPENDENCIES (vite, express, hono, koa, …) whose own
        # internal code legitimately matches the server-entrypoint patterns, and it is NEVER
        # part of the published artifact (the pinned Vite scaffold ships only dist/). The
        # entrypoint pass below runs even inside skip dirs to catch a backend smuggled into
        # BUILT/COPIED output (dist/, _takyon/, references/) — but node_modules is neither built
        # nor shipped, so scanning it is pure false-positive: it flagged Vite's own
        # node_modules/vite/dist/node/ dev-server code as a "forbidden server entrypoint",
        # forcing the CEO to hand-add a .takyonignore on every build. Exclude it from every pass
        # (it was never provider-scanned anyway — scan_provider requires ``not skipped``).
        if "node_modules" in path.parts:
            continue
        skipped = _product_source_is_skipped(path)

        # Server entrypoints are scanned even inside skip dirs (dist/, _takyon/,
        # references/) so a built/copied entrypoint can't smuggle a backend in.
        # For non-skipped source we still run the full provider/credential scan.
        scan_provider = (not skipped) and suffix in _PRODUCT_SOURCE_EXTENSIONS
        # Built/minified output may have a .mjs/.cjs extension; include common JS
        # shapes for the server-entrypoint pass even outside the source set.
        scan_entrypoint = suffix in _PRODUCT_SOURCE_EXTENSIONS or suffix in {".mjs", ".cjs"}
        if not scan_provider and not scan_entrypoint:
            continue

        try:
            lines = path.read_text(encoding="utf-8").splitlines()
        except (UnicodeDecodeError, OSError):
            continue

        for number, raw_line in enumerate(lines, start=1):
            if len(findings) >= limit:
                break
            # Fold simple adjacent string-concat so obfuscated host/env/path
            # literals ("api.openai" + ".com", "OPENAI" + "_API_KEY") match.
            line = _normalize_concat_string_literals(raw_line)

            # Smuggled server entrypoint — checked regardless of skip dir.
            if scan_entrypoint and _FORBIDDEN_SERVER_ENTRYPOINT_PATTERN.search(line):
                findings.append(
                    {
                        "path": rel,
                        "line": number,
                        "kind": "server_entrypoint",
                        "issue": "server entrypoint",
                        "blocker": (
                            "product source ships a server entrypoint"
                            + (" smuggled into a build/skip directory" if skipped else "")
                        ),
                        "snippet": raw_line.strip()[:240],
                    }
                )
                continue

            if not scan_provider:
                continue

            # Direct provider host (literal or loose fragment), incl. de-obfuscated.
            if _forbidden_host_in_line(line):
                findings.append(
                    {
                        "path": rel,
                        "line": number,
                        "issue": "direct provider host",
                        "blocker": "product source calls an AI provider directly",
                        "snippet": raw_line.strip()[:240],
                    }
                )
                continue

            # Hardcoded provider API-key literal, regardless of env-var name.
            if _FORBIDDEN_PROVIDER_KEY_LITERAL_PATTERN.search(line):
                findings.append(
                    {
                        "path": rel,
                        "line": number,
                        "issue": "hardcoded provider api key",
                        "blocker": "product source ships a hardcoded AI-provider API key",
                        "snippet": raw_line.strip()[:240],
                    }
                )
                continue

            # Direct external LLM API call: an HTTP call + LLM-path heuristic that
            # is NOT routed through the allowlisted metered runtime gateway.
            if (
                _FORBIDDEN_LLM_CALL_PATH_PATTERN.search(line)
                and _HTTP_CALL_PATTERN.search(line)
                and not _line_is_runtime_gateway_allowlisted(line)
            ):
                findings.append(
                    {
                        "path": rel,
                        "line": number,
                        "issue": "direct external llm call",
                        "blocker": (
                            "product source makes a direct external LLM API call instead of "
                            "routing through the metered runtime gateway"
                        ),
                        "snippet": raw_line.strip()[:240],
                    }
                )
                continue

            # Denylisted provider env reads / SDK imports.
            matched = False
            for issue, pattern, blocker in _FORBIDDEN_PRODUCT_PATTERNS:
                if pattern.search(line):
                    findings.append(
                        {
                            "path": rel,
                            "line": number,
                            "issue": issue,
                            "blocker": blocker,
                            "snippet": raw_line.strip()[:240],
                        }
                    )
                    matched = True
                    break
            if matched:
                continue
    return findings


_SCAFFOLD_PLACEHOLDER_TOKENS_PATH = Path(__file__).resolve().parent / "subuser_app_kit" / "scaffold" / "src" / "tokens.css"
# Customer-visible screens that must never ship as a blank/stubbed shell. A screen that still
# carries the blank-shell SENTINEL (``data-takyon-scaffold``) is always gated here, on every
# screen below, because the sentinel means a worker stubbed the route back to a blank placeholder.
#
# The BYTE-IDENTICAL-to-seed arm is narrower: it gates only the public landing route ``/``. The
# bundled scaffold seeds ``app-home.tsx`` and ``profile.tsx`` as REAL, functional, shippable
# app-kit screens wired through the shared runtime hooks (gated behind sign-in), exactly like
# ``support.tsx`` (real seeded FAQ/privacy/terms/articles content). So an untouched-but-real seed
# of the gated ``/app`` shell is acceptable to ship — gating it byte-identically would block the
# landing-first publish pass (2a customizes only ``/`` and serves it immediately while the seeded
# real ``/app`` shell ships behind the access gate; 2b then refines ``/app`` + ``/app/profile``).
# Only ``/`` is the public, must-be-rewritten-before-publish route, so only its byte-identical seed
# blocks publish.
_SCAFFOLD_VISIBLE_SCREEN_PATHS: tuple[str, ...] = (
    "src/screens/landing.tsx",
    "src/screens/app-home.tsx",
    "src/screens/profile.tsx",
)
# Subset of the visible screens whose untouched byte-identical seed must STILL block publish. The
# bundled seed for these is not a shippable customer-facing surface (the public landing must be
# rewritten); the seeds for app-home/profile are real and shippable so they are gated only by the
# blank-shell sentinel above, never by byte identity to their seed.
_SCAFFOLD_BYTE_IDENTICAL_GATED_SCREEN_PATHS: frozenset[str] = frozenset(
    {"src/screens/landing.tsx"}
)
_SCAFFOLD_VISIBLE_SCREEN_SENTINEL = "data-takyon-scaffold"
_APP_ACCESS_GATE_NULL_PATTERN = re.compile(
    r"""
    if\s*\(\s*!\s*
    (?:
        access|appState|viewer|viewerAccess
    )
    \s*\.\s*
    (?:
        entitled|authenticated
    )
    \s*\)
    \s*\{?\s*return\s+null\s*;?
    """,
    re.IGNORECASE | re.VERBOSE | re.DOTALL,
)


def _scaffold_placeholder_tokens_marker(root: Path) -> dict[str, Any] | None:
    """Advisory (never a blocker): the product still ships the scaffold's placeholder tokens."""
    product_tokens = root / "src" / "tokens.css"
    try:
        if not product_tokens.is_file() or not _SCAFFOLD_PLACEHOLDER_TOKENS_PATH.is_file():
            return None
        if product_tokens.read_text(encoding="utf-8") != _SCAFFOLD_PLACEHOLDER_TOKENS_PATH.read_text(encoding="utf-8"):
            return None
    except OSError:
        return None
    return {
        "path": "src/tokens.css",
        "issue": "scaffold_placeholder_tokens",
        "snippet": "tokens.css is byte-identical to the scaffold placeholder; theme it from the design brief before publish",
    }


def _scaffold_visible_shell_markers(root: Path) -> list[dict[str, Any]]:
    """Detect untouched customer-visible scaffold screens that should never ship."""
    scaffold_root = _subuser_app_scaffold_source_dir()
    markers: list[dict[str, Any]] = []
    for rel in _SCAFFOLD_VISIBLE_SCREEN_PATHS:
        product_path = root / rel
        scaffold_path = scaffold_root / rel
        try:
            if not product_path.is_file():
                continue
            product_text = product_path.read_text(encoding="utf-8")
        except OSError:
            continue
        snippet = ""
        if _SCAFFOLD_VISIBLE_SCREEN_SENTINEL in product_text:
            snippet = "screen still carries the scaffold sentinel marker and renders the blank shell"
        elif rel in _SCAFFOLD_BYTE_IDENTICAL_GATED_SCREEN_PATHS:
            # Only the public landing route blocks on an untouched byte-identical seed. The seeded
            # /app shell screens are real and shippable behind the access gate, so an untouched seed
            # of them must not block the landing-first publish pass (it is refined later in 2b).
            try:
                if scaffold_path.is_file() and product_text == scaffold_path.read_text(encoding="utf-8"):
                    snippet = "screen is byte-identical to the bundled blank scaffold"
            except OSError:
                snippet = ""
        if not snippet:
            continue
        markers.append(
            {
                "path": rel,
                "issue": "scaffold_visible_shell",
                "snippet": snippet,
            }
        )
    return markers


def _app_access_gate_null_markers(root: Path) -> list[dict[str, Any]]:
    """Detect app screens that blank the customer surface instead of showing the access gate."""
    markers: list[dict[str, Any]] = []
    for rel in ("src/screens/app-home.tsx", "src/screens/profile.tsx"):
        path = root / rel
        try:
            if not path.is_file():
                continue
            text = path.read_text(encoding="utf-8")
        except OSError:
            continue
        match = _APP_ACCESS_GATE_NULL_PATTERN.search(text)
        if not match:
            continue
        markers.append(
            {
                "path": rel,
                "issue": "app_access_gate_returns_null",
                "snippet": _truncate_text(match.group(0).strip(), 220),
            }
        )
    return markers


def _scaffold_theme_unfinished_blocker(refresh: dict[str, Any]) -> str:
    """Do-not-publish gate: a build that still ships the scaffold's placeholder theme is unfinished.

    The byte-identical ``tokens.css`` marker is detected during inventory as an advisory, and the
    takyon-product skill already calls it a do-not-publish signal. So a successful build that still
    carries it must block publish (and drive the one local-repair retry) instead of shipping an
    unthemed product. Returns the exact blocker text, or ``""`` when no placeholder marker is present.
    """
    if not isinstance(refresh, dict):
        return ""
    inventory = refresh.get("inventory") if isinstance(refresh.get("inventory"), dict) else {}
    markers = inventory.get("risk_markers") if isinstance(inventory.get("risk_markers"), list) else []
    for marker in markers:
        if isinstance(marker, dict) and str(marker.get("issue") or "").strip() == "scaffold_placeholder_tokens":
            snippet = str(marker.get("snippet") or "").strip()
            return (
                "product still ships the scaffold placeholder theme: "
                + (snippet or "src/tokens.css is byte-identical to the scaffold placeholder")
                + " — apply the design brief's colors and typography to src/tokens.css and the Tailwind theme before publish"
            )
    return ""


def _scaffold_visible_shell_unfinished_blocker(refresh: dict[str, Any]) -> str:
    """Do-not-publish gate: core customer-facing routes still ship the blank scaffold."""
    if not isinstance(refresh, dict):
        return ""
    inventory = refresh.get("inventory") if isinstance(refresh.get("inventory"), dict) else {}
    markers = inventory.get("risk_markers") if isinstance(inventory.get("risk_markers"), list) else []
    for marker in markers:
        if isinstance(marker, dict) and str(marker.get("issue") or "").strip() == "scaffold_visible_shell":
            path = str(marker.get("path") or "").strip() or "src/screens/landing.tsx"
            snippet = str(marker.get("snippet") or "").strip()
            return (
                "product still ships the blank scaffold screen at "
                f"{path}: "
                + (snippet or "rewrite the core bootstrap routes before publish")
                + " — rewrite `/`, `/faq`, `/privacy`, `/terms`, `/articles`, `/app`, and `/app/profile` into truthful customer-facing UI before publish"
            )
    return ""


def _app_access_gate_null_unfinished_blocker(refresh: dict[str, Any]) -> str:
    """Do-not-publish gate: app routes blank unauthenticated/unentitled viewers."""
    if not isinstance(refresh, dict):
        return ""
    inventory = refresh.get("inventory") if isinstance(refresh.get("inventory"), dict) else {}
    markers = inventory.get("risk_markers") if isinstance(inventory.get("risk_markers"), list) else []
    for marker in markers:
        if isinstance(marker, dict) and str(marker.get("issue") or "").strip() == "app_access_gate_returns_null":
            path = str(marker.get("path") or "").strip() or "src/screens/app-home.tsx"
            return (
                "product app route can render blank for unauthenticated or unentitled viewers at "
                f"{path}: replace the null return with a visible sign-in/subscribe gate wired to "
                "`useProductAuth()` and `resolveViewerCta()`"
            )
    return ""


def _merge_surface_refresh_blocker(refresh: dict[str, Any], blocker: str) -> dict[str, Any]:
    clean = str(blocker or "").strip()
    if not clean:
        return refresh
    existing_error = str(refresh.get("error") or "").strip()
    if not existing_error:
        merged = clean
    elif clean in existing_error:
        merged = existing_error
    else:
        merged = f"{existing_error}; also: {clean}"
    return {
        **refresh,
        "status": "blocked",
        "error": merged,
    }


_PINNED_STACK_SERVER_IMPORT_PATTERN = re.compile(
    r"""(?:from\s+['"](?:express|fastify|hono|koa)['"]|require\(\s*['"](?:express|fastify|hono|koa)['"]\s*\))"""
)
_PINNED_STACK_ROUTE_FILE_PATTERN = re.compile(r"(?:^|/)(?:src/)?app/.+/route\.(?:js|jsx|ts|tsx)$")
_PINNED_STACK_DIRECT_GENERATE_PATTERN = re.compile(
    r"""
    /api/takyon/apps/[^'"`\s)]+/generate\b
    |/generate\b
    |\.\s*generate\s*\(
    |\b(?:routeUrl|runtimeUrl)\s*\(\s*['"]generate['"]\s*\)
    """,
    re.IGNORECASE | re.VERBOSE,
)


def _scan_for_pinned_stack_server_entrypoints(root: Path, *, limit: int = 25) -> list[dict[str, Any]]:
    """The pinned Vite scaffold is static-only: any server entrypoint is a finding."""
    findings: list[dict[str, Any]] = []
    if not root.exists():
        return findings
    for path in sorted(root.rglob("*")):
        if len(findings) >= limit:
            break
        if not path.is_file() or _product_source_is_skipped(path):
            continue
        rel = str(path.relative_to(root))
        if path.name.lower().startswith("next.config."):
            findings.append({
                "path": rel, "line": 1, "kind": "server_entrypoint", "issue": "server entrypoint",
                "snippet": path.name,
                "blocker": "product source carries a Next.js config on the pinned static Vite scaffold",
            })
            continue
        if _PINNED_STACK_ROUTE_FILE_PATTERN.search(rel) or "/pages/api/" in f"/{rel}" :
            findings.append({
                "path": rel, "line": 1, "kind": "server_entrypoint", "issue": "server entrypoint",
                "snippet": rel,
                "blocker": "product source defines a server route handler on the pinned static Vite scaffold",
            })
            continue
        if path.suffix.lower() not in _PRODUCT_SOURCE_EXTENSIONS:
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        for number, line in enumerate(text.splitlines(), start=1):
            if _PINNED_STACK_SERVER_IMPORT_PATTERN.search(line):
                findings.append({
                    "path": rel, "line": number, "kind": "server_entrypoint", "issue": "server entrypoint",
                    "snippet": line.strip()[:240],
                    "blocker": "product source imports a server framework on the pinned static Vite scaffold",
                })
                break
    return findings


def _scan_for_pinned_stack_client_generate_usage(root: Path, *, limit: int = 25) -> list[dict[str, Any]]:
    """The pinned Vite scaffold should call AI through actions, not client-side generate."""
    findings: list[dict[str, Any]] = []
    if not root.exists():
        return findings
    for path in sorted(root.rglob("*")):
        if len(findings) >= limit:
            break
        if not path.is_file() or path.suffix.lower() not in _PRODUCT_SOURCE_EXTENSIONS:
            continue
        if _product_source_is_skipped(path):
            continue
        rel = str(path.relative_to(root))
        if rel.startswith("actions/") or rel.startswith("_takyon/"):
            continue
        try:
            lines = path.read_text(encoding="utf-8").splitlines()
        except UnicodeDecodeError:
            continue
        for number, line in enumerate(lines, start=1):
            if not _PINNED_STACK_DIRECT_GENERATE_PATTERN.search(line):
                continue
            findings.append({
                "path": rel,
                "line": number,
                "kind": "vite_client_generate",
                "issue": "client /generate call",
                "blocker": "product source calls the shared generate rail directly from pinned Vite client code",
                "snippet": line.strip()[:240],
            })
            break
    return findings


def _forbidden_product_source_remedy(*, issue: str = "", kind: str = "") -> str:
    normalized_issue = str(issue or "").strip().lower()
    normalized_kind = str(kind or "").strip().lower()
    if normalized_kind == "server_entrypoint":
        return (
            "pinned Vite SPA only: remove the product-side server entrypoint and put backend logic in "
            "product/site/actions/<name>.ts"
        )
    if normalized_kind == "vite_client_generate":
        return (
            "the browser must not call `/generate`; call a named action via "
            "createActionRunner/invokeAction instead"
        )
    if normalized_issue == "provider sdk import":
        return (
            "remove the SDK import and call your declared action over `ctx.base_url` + "
            "`ctx.session_token`, which brokers the generate rail server-side"
        )
    if normalized_issue in {"direct provider host", "provider credential or base-url env read"}:
        return (
            "do not call providers directly or read provider keys/base URLs from product source; use "
            "the action runtime's `ctx` and shared Takyon rails instead"
        )
    return "route runtime AI through a declared action and shared Takyon rails instead of product-side provider code"


def _forbidden_product_source_detail(finding: Mapping[str, Any]) -> str:
    issue = str(finding.get("issue") or "").strip()
    snippet = str(finding.get("snippet") or "").strip()
    details: list[str] = []
    if issue:
        details.append(f"issue: {issue}")
    if snippet:
        details.append(f"snippet: {snippet}")
    return "; ".join(details)


def _format_forbidden_product_source_blockers(
    forbidden_findings: list[dict[str, Any]],
    reserved_namespace_routes: list[dict[str, Any]],
    *,
    limit: int = 5,
) -> list[str]:
    blockers: list[str] = []
    for finding in forbidden_findings:
        if len(blockers) >= limit:
            break
        detail = _forbidden_product_source_detail(finding)
        detail_suffix = f"; {detail}" if detail else ""
        remedy = _forbidden_product_source_remedy(
            issue=str(finding.get("issue") or ""),
            kind=str(finding.get("kind") or ""),
        )
        if str(finding.get("kind") or "") == "server_entrypoint":
            blockers.append(
                f"{finding.get('blocker') or 'product source defines a server entrypoint'} at "
                f"{finding.get('path')}:{finding.get('line')}{detail_suffix}; {remedy}"
            )
            continue
        if str(finding.get("kind") or "") == "vite_client_generate":
            blockers.append(
                f"{finding.get('blocker') or 'product source calls the shared generate rail directly from client code'} at "
                f"{finding.get('path')}:{finding.get('line')}{detail_suffix}; {remedy}"
            )
            continue
        blockers.append(
            f"{finding.get('blocker') or 'product source bypasses the runtime'} at "
            f"{finding.get('path')}:{finding.get('line')}{detail_suffix}; {remedy}"
        )
    for finding in reserved_namespace_routes:
        if len(blockers) >= limit:
            break
        route = str(finding.get("route") or "").strip() or "/api/takyon/apps/..."
        blockers.append(
            "product source defines its own handler under the platform-reserved path "
            f"{route} at {finding.get('path')}; issue: reserved runtime namespace; platform rails are "
            "served by the Takyon runtime; remove the handler and call the rail from the client or a declared action"
        )
    remaining = max(0, len(forbidden_findings) + len(reserved_namespace_routes) - len(blockers))
    if remaining:
        blockers.append(f"... and {remaining} more forbidden product-source finding(s)")
    return blockers


def _route_from_source_path(rel: str) -> tuple[str, str] | None:
    parts = rel.split("/")
    if len(parts) >= 2 and parts[0] == "src" and parts[1] in {"app", "pages"}:
        parts = parts[1:]
    name = parts[-1] if parts else rel
    suffix = Path(name).suffix.lower()
    if len(parts) >= 3 and parts[0] == "app" and parts[1] == "api" and name.startswith("route."):
        route = "/" + "/".join(parts[:-1])
        return "api_route", route
    if len(parts) >= 2 and parts[0] == "pages" and parts[1] == "api":
        stem_parts = parts[2:]
        if stem_parts:
            stem_parts[-1] = Path(stem_parts[-1]).stem
        return "api_route", "/" + "/".join(["api", *[part for part in stem_parts if part != "index"]])
    if len(parts) >= 2 and parts[0] == "app" and name.startswith("page."):
        route_parts = [part for part in parts[1:-1] if not part.startswith("(")]
        return "route", "/" + "/".join(route_parts) if route_parts else "/"
    if len(parts) >= 2 and parts[0] == "pages" and suffix in {".js", ".jsx", ".ts", ".tsx"}:
        route_parts = parts[1:]
        route_parts[-1] = Path(route_parts[-1]).stem
        route_parts = [part for part in route_parts if part != "index"]
        return "route", "/" + "/".join(route_parts) if route_parts else "/"
    if suffix == ".html":
        route_parts = parts[:]
        route_parts[-1] = Path(route_parts[-1]).stem
        route_parts = [part for part in route_parts if part != "index"]
        return "route", "/" + "/".join(route_parts) if route_parts else "/"
    return None


def _bounded_product_inventory(business_root: Path, source_path: str, *, surface: dict[str, Any] | None = None) -> dict[str, Any]:
    source_rel = _safe_relpath(source_path or "product/site", field="source_path").as_posix()
    root = (business_root / source_rel).resolve()
    inventory: dict[str, Any] = {
        "status": "missing",
        "source_path": source_rel,
        "generated_at": _now(),
        "routes": [],
        "declared_routes": [],
        "api_routes": [],
        "package": {},
        "runtime_integrations": [],
        "reserved_namespace_routes": [],
        "workflow_markers": [],
        "risk_markers": [],
        "claim_snippets": [],
        "pretend_findings": [],
        "forbidden_findings": [],
        "files_scanned": 0,
        "files_skipped": 0,
        "public_url": "",
        "publish_receipt_path": "",
        "scanner_error": "",
    }
    if isinstance(surface, dict):
        inventory["public_url"] = str(surface.get("public_url") or "")
        inventory["publish_receipt_path"] = str(surface.get("publish_receipt_path") or "")
    if business_root.resolve() not in (root, *root.parents):
        inventory.update({"status": "unavailable", "scanner_error": "source path escaped business root"})
        return inventory
    if not root.exists() or not root.is_dir():
        return inventory

    routes: set[str] = set()
    declared_routes: set[str] = set()
    api_routes: set[str] = set()
    runtime_integrations: set[str] = set()
    reserved_namespace_routes: list[dict[str, Any]] = []
    workflow_markers: set[str] = set()
    risk_markers: list[dict[str, Any]] = []
    claim_snippets: list[dict[str, Any]] = []
    files_scanned = 0
    files_skipped = 0
    partial = False

    for path in sorted(root.rglob("*")):
        if not path.is_file() or _product_source_is_skipped(path):
            continue
        if files_scanned >= _PRODUCT_INVENTORY_MAX_FILES:
            partial = True
            files_skipped += 1
            continue
        rel = path.relative_to(root).as_posix()
        route = _route_from_source_path(rel)
        reserved_route_path = _reserved_product_runtime_route_from_source_rel(rel)
        reserved_runtime_route = bool(reserved_route_path)
        if route:
            kind, value = route
            if kind == "api_route":
                api_routes.add(value)
                if reserved_runtime_route and len(reserved_namespace_routes) < _PRODUCT_INVENTORY_MAX_MARKERS:
                    reserved_namespace_routes.append({"path": rel, "route": reserved_route_path})
            else:
                routes.add(value)
        if path.name == "package.json":
            try:
                package_data = json.loads(path.read_text(encoding="utf-8")[:_PRODUCT_INVENTORY_MAX_BYTES])
                scripts = package_data.get("scripts") if isinstance(package_data.get("scripts"), dict) else {}
                deps = {
                    **(package_data.get("dependencies") if isinstance(package_data.get("dependencies"), dict) else {}),
                    **(package_data.get("devDependencies") if isinstance(package_data.get("devDependencies"), dict) else {}),
                }
                inventory["package"] = {
                    "name": str(package_data.get("name") or ""),
                    "package_manager": str(package_data.get("packageManager") or ""),
                    "scripts": sorted(str(key) for key in scripts.keys())[:20],
                    "frameworks": [name for name in ("next", "react", "vite", "vue", "svelte") if name in deps],
                }
            except Exception as exc:
                risk_markers.append({"path": rel, "issue": "package_unreadable", "snippet": _truncate_text(str(exc), 160)})
            files_scanned += 1
            continue
        if path.suffix.lower() not in _PRODUCT_INVENTORY_TEXT_EXTENSIONS:
            files_skipped += 1
            continue
        try:
            if path.stat().st_size > _PRODUCT_INVENTORY_MAX_BYTES:
                files_skipped += 1
                partial = True
                continue
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            files_skipped += 1
            continue
        except Exception as exc:
            risk_markers.append({"path": rel, "issue": "file_unreadable", "snippet": _truncate_text(str(exc), 160)})
            files_skipped += 1
            continue
        files_scanned += 1
        for number, line in enumerate(text.splitlines(), start=1):
            for route_match in _PRODUCT_DECLARED_ROUTE_PATTERN.finditer(line):
                route_value = (route_match.group("html") or route_match.group("quoted") or "").strip("'\"")
                if route_value and not route_value.startswith("/api/") and route_value != "/":
                    declared_routes.add(route_value.rstrip("/") or "/")
            if not reserved_runtime_route:
                for label, pattern in _PRODUCT_RUNTIME_INTEGRATION_PATTERNS:
                    if pattern.search(line):
                        runtime_integrations.add(label)
            for label, pattern in _PRODUCT_WORKFLOW_MARKERS:
                if pattern.search(line):
                    workflow_markers.add(label)
            if len(risk_markers) < _PRODUCT_INVENTORY_MAX_MARKERS:
                for label, pattern in _PRODUCT_INVENTORY_MARKERS:
                    if pattern.search(line):
                        risk_markers.append({
                            "path": rel,
                            "line": number,
                            "issue": label,
                            "snippet": line.strip()[:220],
                        })
                        break
            if len(claim_snippets) < _PRODUCT_INVENTORY_MAX_SNIPPETS and _PRODUCT_CLAIM_SNIPPET_PATTERN.search(line):
                clean = line.strip()
                if clean:
                    claim_snippets.append({"path": rel, "line": number, "snippet": clean[:220]})

    try:
        inventory["forbidden_findings"] = _scan_for_forbidden_product_backend_code(root, limit=12)
    except Exception as exc:
        risk_markers.append({"path": source_rel, "issue": "forbidden_scan_unavailable", "snippet": _truncate_text(str(exc), 160)})
    try:
        if _surface_subuser_app_shape(surface).get("frontend_stack") == "vite_react_ts":
            inventory["forbidden_findings"] = list(inventory.get("forbidden_findings") or []) + (
                _scan_for_pinned_stack_server_entrypoints(root, limit=12)
            )
            inventory["forbidden_findings"] = list(inventory.get("forbidden_findings") or []) + (
                _scan_for_pinned_stack_client_generate_usage(root, limit=12)
            )
            placeholder_marker = _scaffold_placeholder_tokens_marker(root)
            if placeholder_marker:
                risk_markers.append(placeholder_marker)
            risk_markers.extend(_scaffold_visible_shell_markers(root))
            risk_markers.extend(_app_access_gate_null_markers(root))
    except Exception as exc:
        risk_markers.append({"path": source_rel, "issue": "stack_gate_scan_unavailable", "snippet": _truncate_text(str(exc), 160)})

    inventory.update({
        "status": "partial" if partial else "collected",
        "routes": sorted(routes),
        "declared_routes": sorted(declared_routes),
        "api_routes": sorted(api_routes),
        "runtime_integrations": sorted(runtime_integrations),
        "reserved_namespace_routes": reserved_namespace_routes,
        "workflow_markers": sorted(workflow_markers),
        "risk_markers": risk_markers,
        "claim_snippets": claim_snippets,
        "files_scanned": files_scanned,
        "files_skipped": files_skipped,
    })
    return inventory


def _product_inventory(business_root: Path, source_path: str, *, surface: dict[str, Any] | None = None) -> dict[str, Any]:
    try:
        return _bounded_product_inventory(business_root, source_path, surface=surface)
    except Exception as exc:
        source_text = str(source_path or "product/site")
        return {
            "status": "unavailable",
            "source_path": source_text,
            "generated_at": _now(),
            "routes": [],
            "declared_routes": [],
            "api_routes": [],
            "package": {},
            "runtime_integrations": [],
            "reserved_namespace_routes": [],
            "workflow_markers": [],
            "risk_markers": [],
            "claim_snippets": [],
            "pretend_findings": [],
            "forbidden_findings": [],
            "files_scanned": 0,
            "files_skipped": 0,
            "public_url": str((surface or {}).get("public_url") or "") if isinstance(surface, dict) else "",
            "publish_receipt_path": str((surface or {}).get("publish_receipt_path") or "") if isinstance(surface, dict) else "",
            "scanner_error": _truncate_text(str(exc), 500),
        }


def _read_product_surface_receipt(
    business_root: Path,
    receipt_path: str,
) -> dict[str, Any]:
    rel = str(receipt_path or "").strip()
    if not rel:
        return {}
    try:
        safe_rel = _safe_relpath(rel, field="publish_receipt_path").as_posix()
    except Exception:
        return {}
    candidate = (business_root / safe_rel).resolve()
    if business_root.resolve() not in (candidate, *candidate.parents):
        return {}
    if not candidate.is_file():
        return {}
    try:
        payload = json.loads(candidate.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return payload if isinstance(payload, dict) else {}


def _product_surface_operational_facts(
    *,
    surface: dict[str, Any] | None,
    receipt: dict[str, Any] | None,
    inventory: dict[str, Any] | None,
) -> dict[str, Any]:
    surface_dict = surface if isinstance(surface, dict) else {}
    publication = _surface_live_publication_state(
        surface_dict,
        business=str(surface_dict.get("business_slug") or "").strip(),
    )
    receipt_dict = receipt if isinstance(receipt, dict) else {}
    publish = receipt_dict.get("publish") if isinstance(receipt_dict.get("publish"), dict) else {}
    effective_inventory = (
        inventory if isinstance(inventory, dict) and inventory
        else receipt_dict.get("inventory") if isinstance(receipt_dict.get("inventory"), dict)
        else {}
    )
    package = effective_inventory.get("package") if isinstance(effective_inventory.get("package"), dict) else {}
    checks = receipt_dict.get("checks") if isinstance(receipt_dict.get("checks"), list) else []
    latest_check = checks[-1] if checks and isinstance(checks[-1], dict) else {}
    latest_problem_check = next(
        (
            item for item in reversed(checks)
            if isinstance(item, dict)
            and str(item.get("status") or "").strip().lower() not in {"passed", "success", "completed"}
        ),
        latest_check,
    )

    def _command_text(value: Any) -> str:
        if isinstance(value, list):
            parts = [str(part).strip() for part in value if str(part).strip()]
            return shlex.join(parts) if parts else ""
        return str(value or "").strip()

    frameworks = [
        str(item).strip()
        for item in (package.get("frameworks") or [])
        if str(item).strip()
    ]
    runtime_integrations = [
        str(item).strip()
        for item in (effective_inventory.get("runtime_integrations") or [])
        if str(item).strip()
    ]
    workflow_markers = [
        str(item).strip()
        for item in (effective_inventory.get("workflow_markers") or [])
        if str(item).strip()
    ]
    routes = [
        str(item).strip()
        for item in (effective_inventory.get("routes") or [])
        if str(item).strip()
    ]
    latest_check_error = str(
        latest_problem_check.get("error")
        or latest_problem_check.get("stderr")
        or latest_problem_check.get("stdout")
        or ""
    ).strip()
    latest_check_status = str(latest_problem_check.get("status") or latest_check.get("status") or "").strip()
    latest_check_command = _command_text(
        latest_problem_check.get("command") or latest_check.get("command")
    )
    latest_failed_command = ""
    if latest_check_status.lower() not in {"", "passed", "success", "completed"}:
        latest_failed_command = latest_check_command
    repairs = []
    for item in receipt_dict.get("repairs") or []:
        if isinstance(item, dict):
            message = str(item.get("message") or "").strip()
            if message:
                repairs.append(message)
    blocker = _surface_refresh_exact_blocker(receipt_dict, publish)
    if not blocker:
        blocker = (
            str(receipt_dict.get("blocker") or publish.get("blocker") or receipt_dict.get("error") or "").strip()
            or str(publication.get("publish_blocker") or "").strip()
        )
    return {
        "detected_frameworks": frameworks,
        "detected_package_manager": str(package.get("package_manager") or "").strip(),
        "inventory_status": str(effective_inventory.get("status") or "").strip(),
        "routes": routes,
        "runtime_integrations": runtime_integrations,
        "workflow_markers": workflow_markers,
        "refresh_status": str(receipt_dict.get("status") or "").strip(),
        "latest_check_status": latest_check_status,
        "latest_check_command": latest_check_command,
        "latest_check_error": _truncate_text(latest_check_error, 1000),
        "latest_failed_command": latest_failed_command,
        "publish_mode": str(publish.get("publish_mode") or publish.get("deploy_kind") or "").strip(),
        "publish_source_path": str(publish.get("publish_source_path") or "").strip(),
        "publish_root": str(publish.get("publish_root") or "").strip(),
        "publish_status": str(publication.get("publish_status") or "not_published"),
        "public_url": str(publication.get("public_url") or ""),
        "live_build_id": str(publication.get("build_id") or ""),
        "repairs": repairs[:6],
        "blocker": blocker,
    }


def _surface_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "y", "on"}
    return False


def _surface_allows_landing_only(surface: dict[str, Any] | None) -> bool:
    return False


def _surface_routes(surface: dict[str, Any] | None) -> list[str]:
    if not isinstance(surface, dict):
        return []
    values = surface.get("routes")
    routes: list[str] = []
    if isinstance(values, list):
        for item in values:
            if isinstance(item, str):
                path = item
            elif isinstance(item, dict):
                path = str(item.get("path") or "")
            else:
                path = ""
            path = path.strip()
            if path:
                routes.append(path.rstrip("/") or "/")
    return routes


def _surface_text(surface: dict[str, Any] | None) -> str:
    if not isinstance(surface, dict):
        return ""
    parts: list[str] = []
    for key in ("status", "runtime_api_base", "notes"):
        value = surface.get(key)
        if value:
            parts.append(str(value))
    for item in surface.get("routes") or []:
        if isinstance(item, str):
            parts.append(item)
        elif isinstance(item, dict):
            for key in ("path", "label", "description", "purpose", "type"):
                if item.get(key):
                    parts.append(str(item.get(key)))
    for key in ("metadata",):
        value = surface.get(key)
        if isinstance(value, dict):
            parts.extend(f"{nested_key}={nested_value}" for nested_key, nested_value in value.items())
    return "\n".join(parts)


def _surface_contract_kind(surface: dict[str, Any] | None) -> dict[str, bool]:
    text = _surface_text(surface)
    routes = _surface_routes(surface)
    route_text = "\n".join(route for route in routes if route != "/")
    has_workflow_route = any(_PRODUCT_WORKFLOW_ROUTE_PATTERN.search(route) for route in routes if route != "/")
    ai_surface = _PRODUCT_AI_SURFACE_PATTERN.search(text) is not None
    auth_surface = _PRODUCT_AUTH_SURFACE_PATTERN.search(text) is not None
    checkout_surface = _PRODUCT_CHECKOUT_SURFACE_PATTERN.search(text) is not None
    return {
        "landing_only": _surface_allows_landing_only(surface),
        "app_like": has_workflow_route
        or ai_surface
        or auth_surface
        or checkout_surface
        or _PRODUCT_WORKFLOW_ROUTE_PATTERN.search(route_text) is not None,
        "ai": ai_surface,
        "auth": auth_surface,
        "checkout": checkout_surface,
    }


def _surface_is_bootstrap_access_shell(surface: dict[str, Any] | None) -> bool:
    bootstrap_rails = _surface_bootstrap_access_shell_runtime_features(surface)
    if not bootstrap_rails:
        return False
    return {"auth", "account", "checkout"}.issubset(set(bootstrap_rails))


def _validate_product_surface_contract(
    inventory: dict[str, Any],
    surface: dict[str, Any] | None,
) -> tuple[bool, str]:
    if not isinstance(inventory, dict):
        return True, ""
    runtime_features = set(_surface_effective_runtime_features(surface))
    runtime_integrations = {
        str(item or "").strip().lower()
        for item in (inventory.get("runtime_integrations") or [])
        if str(item or "").strip()
    }
    risk_issues = {
        str(item.get("issue") or "").strip().lower()
        for item in (inventory.get("risk_markers") or [])
        if isinstance(item, dict)
    }
    claim_text = "\n".join(
        str(item.get("snippet") or "")
        for item in (inventory.get("claim_snippets") or [])
        if isinstance(item, dict)
    )
    kind = _surface_contract_kind(surface)
    checkout_is_presented = (
        kind.get("checkout")
        or "billing_or_checkout" in risk_issues
        or _PRODUCT_CHECKOUT_SURFACE_PATTERN.search(claim_text) is not None
        or re.search(r"\bsubscribe\b|\$\s*\d+|/month|/mo\b", claim_text, re.IGNORECASE) is not None
    )
    if (
        "checkout" in runtime_features
        and "checkout" not in runtime_integrations
        and checkout_is_presented
    ):
        return (
            False,
            "product source presents subscription/checkout UI but does not call the shared "
            "runtime checkout rail; wire the CTA through starterCheckout/client.checkout() or "
            "POST /api/takyon/apps/<business>/checkout instead of linking back to /app",
        )
    return True, ""


def _product_source_files(root: Path, *, limit: int = 200) -> list[str]:
    files: list[str] = []
    if not root.exists() or not root.is_dir():
        return files
    for path in sorted(root.rglob("*")):
        if len(files) >= limit:
            break
        if not path.is_file() or _product_source_is_skipped(path):
            continue
        if path.suffix.lower() in _PRODUCT_SOURCE_EXTENSIONS or path.name in _PRODUCT_PROJECT_FILENAMES:
            files.append(path.relative_to(root).as_posix())
    return files


def _detect_nested_workspace_prefix(root: Path, source_path: str) -> str | None:
    rel = _safe_relpath(source_path or ".", field="source_path")
    if rel.as_posix() in {".", ""}:
        return None
    nested = root / rel
    if nested.exists() and _product_source_files(nested, limit=1):
        return rel.as_posix()
    return None


def _repair_nested_workspace_prefix(workspace_path: Path, workspace: str) -> dict[str, Any]:
    """Move files up when a worker writes product/site inside product/site."""
    rel = _safe_relpath(workspace or ".", field="workspace")
    rel_text = rel.as_posix()
    if rel_text in {".", ""}:
        return {"repaired": False}
    nested = workspace_path / rel
    if not nested.is_dir() or not _product_source_files(nested, limit=1):
        return {"repaired": False}
    root_files = [
        item for item in _product_source_files(workspace_path, limit=20)
        if item != rel_text and not item.startswith(f"{rel_text}/")
    ]
    if root_files:
        return {
            "repaired": False,
            "blocked": True,
            "reason": "workspace root already contains source files outside duplicate prefix",
            "root_files": root_files[:10],
            "nested_source_path": f"{rel_text}/{rel_text}",
        }
    moved: list[str] = []
    for child in sorted(nested.iterdir(), key=lambda item: item.name):
        destination = workspace_path / child.name
        if destination.exists():
            return {
                "repaired": False,
                "blocked": True,
                "reason": f"destination already exists: {child.name}",
                "moved": moved,
                "nested_source_path": f"{rel_text}/{rel_text}",
            }
        shutil.move(str(child), str(destination))
        moved.append(child.name)
    cursor = nested
    while cursor != workspace_path and cursor.is_dir():
        try:
            cursor.rmdir()
        except OSError:
            break
        cursor = cursor.parent
    return {
        "repaired": True,
        "moved": moved,
        "nested_source_path": f"{rel_text}/{rel_text}",
        "source_path": rel_text,
    }


def _run_surface_command(
    command: list[str],
    *,
    cwd: Path,
    timeout_seconds: int,
    env: dict[str, str] | None = None,
) -> dict[str, Any]:
    started = _now()
    try:
        proc = subprocess.run(
            command,
            cwd=str(cwd),
            text=True,
            capture_output=True,
            timeout=timeout_seconds,
            env=env or _runtime_env(),
        )
        status = "passed" if proc.returncode == 0 else "failed"
        return {
            "command": command,
            "status": status,
            "returncode": proc.returncode,
            "started_at": started,
            "completed_at": _now(),
            "stdout": _truncate_text(proc.stdout or "", 12_000),
            "stderr": _truncate_text(proc.stderr or "", 12_000),
        }
    except subprocess.TimeoutExpired as exc:
        return {
            "command": command,
            "status": "blocked",
            "returncode": None,
            "started_at": started,
            "completed_at": _now(),
            "stdout": _truncate_text(exc.stdout or "", 12_000),
            "stderr": _truncate_text(exc.stderr or "", 12_000),
            "error": f"timed out after {timeout_seconds}s",
        }


def _node_modules_present(root: Path) -> bool:
    return (root / "node_modules").exists() and any((root / "node_modules").iterdir())


def _check_node_syntax(path: Path) -> tuple[bool, str]:
    node = _resolve_runtime_executable("node")
    if not node:
        return False, "node runtime unavailable for syntax check"
    proc = subprocess.run(
        [node, "--check", str(path)],
        text=True,
        capture_output=True,
        cwd=str(path.parent),
        env=_runtime_env(),
    )
    if proc.returncode == 0:
        return True, ""
    message = _truncate_text((proc.stderr or proc.stdout or "").strip(), 4000)
    return False, message or f"node --check exited {proc.returncode}"


def _candidate_disabled_path(path: Path) -> Path:
    candidate = path.with_name(f"{path.name}.disabled")
    if not candidate.exists():
        return candidate
    return path.with_name(f"{path.name}.disabled.{uuid.uuid4().hex[:8]}")


def _rewrite_next_config_typescript_to_supported_module(source: str) -> tuple[str, str]:
    uses_esm = bool(re.search(r"^\s*(?:import\b|export\s+default\b)", source, flags=re.MULTILINE))
    target_name = "next.config.mjs" if uses_esm else "next.config.js"
    converted = source.replace("\r\n", "\n")
    converted = re.sub(r"^\s*import\s+type\s+[^;]+;\s*\n?", "", converted, flags=re.MULTILINE)
    converted = re.sub(
        r"^\s*import\s*\{\s*type\s+NextConfig\s*\}\s*from\s*([\"']next[\"']);?\s*\n?",
        "",
        converted,
        flags=re.MULTILINE,
    )
    converted = re.sub(
        r"\b(const|let|var)\s+([A-Za-z_$][\w$]*)\s*:\s*([A-Za-z_$][\w$<>,\s\[\]\.|&?]+)\s*=",
        r"\1 \2 =",
        converted,
    )
    converted = re.sub(r"\s+satisfies\s+NextConfig\b", "", converted)
    converted = re.sub(r"\s+as\s+NextConfig\b", "", converted)
    converted = re.sub(r"\s+as\s+const\b", "", converted)
    return target_name, converted


def _normalize_next_config_typescript(root: Path) -> dict[str, Any]:
    source_path = root / "next.config.ts"
    if not source_path.exists():
        return {"repairs": [], "warnings": []}

    js_path = root / "next.config.js"
    mjs_path = root / "next.config.mjs"
    if js_path.exists() or mjs_path.exists():
        disabled_path = _candidate_disabled_path(source_path)
        shutil.move(str(source_path), str(disabled_path))
        chosen = js_path.name if js_path.exists() else mjs_path.name
        return {
            "repairs": [
                {
                    "kind": "next_config_disable",
                    "from": source_path.name,
                    "to": disabled_path.name,
                    "message": f"Disabled unsupported next.config.ts because {chosen} is the supported Next config entrypoint.",
                }
            ],
            "warnings": [],
        }

    try:
        source_text = source_path.read_text(encoding="utf-8")
    except Exception as exc:
        return {
            "repairs": [],
            "warnings": [],
            "blocked": True,
            "error": f"Next app detected, but next.config.ts could not be read for normalization: {exc}",
        }

    target_name, converted = _rewrite_next_config_typescript_to_supported_module(source_text)
    target_path = root / target_name
    temp_path = root / f".{target_name}.tmp"
    temp_path.write_text(converted, encoding="utf-8")
    ok, syntax_error = _check_node_syntax(temp_path)
    if not ok:
        try:
            temp_path.unlink()
        except OSError:
            pass
        return {
            "repairs": [],
            "warnings": [],
            "blocked": True,
            "error": (
                "Next app detected, but next.config.ts is unsupported and could not be safely normalized "
                f"to {target_name}: {syntax_error}"
            ),
        }

    temp_path.replace(target_path)
    source_path.unlink()
    return {
        "repairs": [
            {
                "kind": "next_config_normalize",
                "from": source_path.name,
                "to": target_path.name,
                "message": f"Normalized unsupported next.config.ts into supported {target_path.name}.",
            }
        ],
        "warnings": [],
    }


_SCAFFOLD_BUILD_CONFIG_FILES = (
    "package-lock.json",
    "tsconfig.json",
    "vite.config.ts",
    "postcss.config.js",
    "tailwind.config.js",
)
_SCAFFOLD_BUILD_CONFIG_CONFLICTS = (
    "vite.config.js",
    "vite.config.mjs",
    "vite.config.cjs",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
)


def _scaffold_package_json_for_workspace(root: Path) -> tuple[dict[str, Any] | None, str]:
    scaffold_package = _subuser_app_scaffold_source_dir() / "package.json"
    try:
        package_data = json.loads(scaffold_package.read_text(encoding="utf-8"))
    except Exception as exc:
        return None, f"bundled scaffold package.json is unreadable: {exc}"
    if not isinstance(package_data, dict):
        return None, "bundled scaffold package.json is not an object"

    current_package = root / "package.json"
    try:
        current = json.loads(current_package.read_text(encoding="utf-8"))
    except Exception:
        current = {}
    if not isinstance(current, dict):
        current = {}

    normalized = dict(package_data)
    for key in ("name", "version", "private"):
        value = current.get(key)
        if isinstance(value, (str, int, float, bool)) and value != "":
            normalized[key] = value
    normalized["type"] = "module"
    return normalized, ""


def _normalize_scaffold_build_config(root: Path) -> dict[str, Any]:
    """Restore scaffold-owned build config before a product refresh runs.

    Worker-owned product UI lives in ``src/screens`` / ``src/components``. The Vite/TS/package
    config is platform-owned because it carries the ``@takyon`` alias, pinned dependency closure,
    and runtime kit imports. Repairing it here lets a generated app recover from a worker that
    overwrote the scaffold config without turning the public product into a hand-patched one-off.
    """
    scaffold = _subuser_app_scaffold_source_dir()
    if not scaffold.exists():
        return {
            "repairs": [],
            "warnings": [],
            "blocked": True,
            "error": "bundled Vite scaffold is missing; cannot normalize product build config",
        }

    repairs: list[dict[str, Any]] = []
    warnings: list[str] = []

    package_data, package_error = _scaffold_package_json_for_workspace(root)
    if package_data is None:
        return {
            "repairs": [],
            "warnings": [],
            "blocked": True,
            "error": package_error,
        }
    package_text = json.dumps(package_data, ensure_ascii=False, indent=2) + "\n"
    package_path = root / "package.json"
    try:
        existing_package_text = package_path.read_text(encoding="utf-8") if package_path.is_file() else ""
    except OSError:
        existing_package_text = ""
    if existing_package_text != package_text:
        _atomic_write_text(package_path, package_text)
        repairs.append(
            {
                "kind": "scaffold_build_config_restore",
                "path": "package.json",
                "message": "Restored the pinned scaffold package scripts and dependency closure.",
            }
        )

    for rel in _SCAFFOLD_BUILD_CONFIG_FILES:
        source = scaffold / rel
        if not source.is_file():
            warnings.append(f"bundled scaffold config missing: {rel}")
            continue
        destination = root / rel
        try:
            source_bytes = source.read_bytes()
            existing_bytes = destination.read_bytes() if destination.is_file() else b""
        except OSError as exc:
            return {
                "repairs": repairs,
                "warnings": warnings,
                "blocked": True,
                "error": f"could not read scaffold build config {rel}: {exc}",
            }
        if existing_bytes == source_bytes:
            continue
        _atomic_write_bytes(destination, source_bytes)
        repairs.append(
            {
                "kind": "scaffold_build_config_restore",
                "path": rel,
                "message": f"Restored pinned scaffold build config {rel}.",
            }
        )

    for rel in _SCAFFOLD_BUILD_CONFIG_CONFLICTS:
        path = root / rel
        if not path.exists() and not path.is_symlink():
            continue
        try:
            if path.is_dir():
                shutil.rmtree(path)
            else:
                path.unlink()
        except OSError as exc:
            return {
                "repairs": repairs,
                "warnings": warnings,
                "blocked": True,
                "error": f"could not remove conflicting build config {rel}: {exc}",
            }
        repairs.append(
            {
                "kind": "scaffold_build_config_conflict_remove",
                "path": rel,
                "message": f"Removed conflicting build config {rel}; the pinned scaffold config is authoritative.",
            }
        )

    return {"repairs": repairs, "warnings": warnings}


def _normalize_supported_product_build_shape(
    root: Path,
    *,
    scripts: dict[str, Any],
    deps: dict[str, Any],
) -> dict[str, Any]:
    looks_next = (
        "next" in deps
        or any((root / name).exists() for name in ("next.config.js", "next.config.mjs", "next.config.ts"))
        or (root / ".next").is_dir()
        or "next build" in str(scripts.get("build") or "")
        or "next start" in str(scripts.get("start") or "")
    )
    if looks_next:
        return {
            "repairs": [],
            "warnings": [],
            "blocked": True,
            "error": (
                "Next/AppKit product trees are unsupported. Rebuild this workspace on the pinned "
                "Vite scaffold and publish the built dist/index.html output."
            ),
        }
    return _normalize_scaffold_build_config(root)


def _surface_refresh_exact_blocker(
    refresh: dict[str, Any],
    publish: dict[str, Any] | None = None,
) -> str:
    refresh_dict = refresh if isinstance(refresh, dict) else {}
    publish_dict = publish if isinstance(publish, dict) else {}
    checks = refresh_dict.get("checks") if isinstance(refresh_dict.get("checks"), list) else []
    latest_problem = next(
        (
            item for item in reversed(checks)
            if isinstance(item, dict)
            and str(item.get("status") or "").strip().lower() not in {"", "passed", "success", "completed"}
        ),
        {},
    )
    latest_error = str(
        latest_problem.get("error")
        or latest_problem.get("stderr")
        or latest_problem.get("stdout")
        or ""
    ).strip()
    latest_command = ""
    if isinstance(latest_problem.get("command"), list):
        parts = [str(part).strip() for part in latest_problem.get("command") if str(part).strip()]
        latest_command = shlex.join(parts) if parts else ""
    else:
        latest_command = str(latest_problem.get("command") or "").strip()
    if latest_error:
        if latest_command:
            return _truncate_text(f"{latest_command} failed: {latest_error}", 1000)
        return _truncate_text(latest_error, 1000)
    publish_blocker = str(publish_dict.get("blocker") or "").strip()
    if publish_blocker:
        return publish_blocker
    return str(refresh_dict.get("error") or "").strip()


def _worker_surface_contract_retry_instruction(
    base_instruction: str,
    *,
    why: str,
    patch_fields: list[str],
    attempt_number: int,
) -> str:
    reason = _truncate_text(str(why or "").strip() or "surface contract changed", 800)
    fields = ", ".join(patch_fields) if patch_fields else "surface contract fields"
    return "\n\n".join(
        [
            base_instruction.rstrip(),
            dedent(
                f"""
                Hermes same-run contract continuation ({attempt_number} of 3):
                - The previous worker pass proved the product surface contract had to change, and Takyon has already applied that patch.
                - Updated contract fields: {fields}
                - Reason: {reason}
                - Continue from the current workspace state instead of restarting from scratch.
                - Align the source you already built with the updated contract, then stop once contract and code agree.
                """
            ).strip(),
        ]
    )


def _claude_agent_hit_turn_cap(error_text: str) -> bool:
    clean = str(error_text or "").strip().lower()
    return "reached maximum number of turns" in clean


def _worker_turn_cap_retry_instruction(
    base_instruction: str,
    *,
    prior_max_turns: int,
    next_max_turns: int,
    attempt_number: int,
) -> str:
    return "\n\n".join(
        [
            base_instruction.rstrip(),
            dedent(
                f"""
                Hermes automatic continuation retry ({attempt_number} of 2):
                - The previous worker attempt hit the Claude SDK turn cap at {int(prior_max_turns)} turns before finishing.
                - Continue from the current workspace state instead of restarting from scratch.
                - Focus only on the smallest remaining work needed to complete the task, then stop.
                - The next attempt has a higher turn budget ({int(next_max_turns)} turns); do not spend it re-reading or redoing work that already exists.
                """
            ).strip(),
        ]
    )


def _javascript_package_manager_name(root: Path, package_data: dict[str, Any]) -> str:
    package_manager = str(package_data.get("packageManager") or "").strip().lower()
    if package_manager:
        return package_manager.split("@", 1)[0]
    if (root / "pnpm-lock.yaml").exists():
        return "pnpm"
    if (root / "yarn.lock").exists():
        return "yarn"
    if (root / "bun.lockb").exists() or (root / "bun.lock").exists():
        return "bun"
    return "npm"


def _javascript_package_manager_command(name: str) -> dict[str, Any]:
    manager = str(name or "npm").strip().lower()
    path = _resolve_runtime_executable(manager)
    if path:
        return {"available": True, "name": manager, "command": [path], "source": "path"}
    if manager in {"pnpm", "yarn"}:
        corepack = _resolve_runtime_executable("corepack")
        if corepack:
            return {"available": True, "name": manager, "command": [corepack, manager], "source": "corepack"}
    return {"available": False, "name": manager, "command": [], "source": "missing"}


def _scaffold_lockfile_hash() -> str:
    """sha256 of the bundled scaffold package-lock.json (the pinned dependency closure).

    Returns "" when the scaffold lock is missing so callers fall back to a normal install instead of
    keying a warm cache off an absent lock."""
    try:
        lock = _subuser_app_scaffold_source_dir() / "package-lock.json"
        return hashlib.sha256(lock.read_bytes()).hexdigest() if lock.is_file() else ""
    except OSError:
        return ""


def _workspace_lockfile_matches_scaffold(root: Path) -> bool:
    """True when the workspace package-lock.json is byte-identical to the pinned scaffold lock.

    Only an exact match makes `npm ci` (and the warm node_modules prebake) deterministic and safe; on
    any drift the caller degrades to a normal `npm install` so a worker-modified dependency set still
    resolves correctly."""
    scaffold_hash = _scaffold_lockfile_hash()
    if not scaffold_hash:
        return False
    workspace_lock = root / "package-lock.json"
    try:
        if not workspace_lock.is_file():
            return False
        return hashlib.sha256(workspace_lock.read_bytes()).hexdigest() == scaffold_hash
    except OSError:
        return False


def _javascript_install_command(manager: dict[str, Any], *, root: Path | None = None) -> list[str]:
    base = list(manager.get("command") or [])
    name = str(manager.get("name") or "npm")
    if name == "npm":
        # Deterministic, cache-friendly install when the copied lockfile is the pinned scaffold lock:
        # `npm ci` installs exactly the lock closure from the (now shared) tarball cache. Degrade to
        # `npm install` on lockfile drift (a worker changed deps) so the new closure still resolves.
        if root is not None and _workspace_lockfile_matches_scaffold(root):
            return [*base, "ci", "--prefer-offline", "--no-audit", "--no-fund", "--ignore-scripts"]
        return [*base, "install", "--ignore-scripts"]
    if name == "pnpm":
        return [*base, "install", "--ignore-scripts"]
    if name == "yarn":
        return [*base, "install", "--ignore-scripts"]
    if name == "bun":
        return [*base, "install", "--ignore-scripts"]
    return [*base, "install"]


def _shared_npm_cache_dir() -> Path:
    """Process-arch-keyed npm tarball cache shared across ALL businesses.

    The npm cache holds content-addressed package tarballs + their integrity hashes; it is safe to
    share across businesses and never carries business state. Keying it per-business source-root
    digest (the old behaviour) guaranteed a COLD cache for every new business, so every bootstrap
    re-downloaded the same pinned scaffold deps from the registry. Key by runtime/arch only so the
    SECOND business onward installs from a warm on-disk cache. Kept under TAKYON_HOME so each profile
    still gets its own copy."""
    takyon_home = Path(os.getenv("TAKYON_HOME") or get_takyon_home()).expanduser()
    arch_key = f"{platform.system()}-{platform.machine()}".lower().replace("/", "-")
    shared = takyon_home / "tmp" / "surface-js-cache" / arch_key / "npm-cache"
    shared.mkdir(parents=True, exist_ok=True)
    return shared


def _warm_node_modules_prebake_dir() -> Path | None:
    """Arch + scaffold-lockfile-hash keyed prebaked node_modules shared across businesses.

    A lockfile-hash key guarantees the prebake matches the exact pinned dependency closure; an arch
    key keeps native binaries (esbuild, etc.) correct for the running host. Returns None when the
    scaffold lock is missing (nothing safe to key on)."""
    lock_hash = _scaffold_lockfile_hash()
    if not lock_hash:
        return None
    takyon_home = Path(os.getenv("TAKYON_HOME") or get_takyon_home()).expanduser()
    arch_key = f"{platform.system()}-{platform.machine()}".lower().replace("/", "-")
    return takyon_home / "tmp" / "surface-js-cache" / arch_key / "node-modules" / lock_hash[:16]


def _warm_node_modules_ready(prebake: Path) -> bool:
    """A prebake is usable only when node_modules exists AND carries the build binaries we need."""
    nm = prebake / "node_modules"
    if not (nm.exists() and any(nm.iterdir())):
        return False
    return (nm / ".bin" / "vite").exists() and (nm / ".bin" / "tsc").exists()


def _sweep_warm_prebake_partials(parent: Path, *, keep: str, max_age_seconds: float = 1800.0) -> None:
    """Remove orphaned ``.<name>.partial-*`` staging dirs left behind by force-killed prebake builds.

    Staging dirs are private scratch — never seeded into a business, never read by a consumer; only
    the atomically-published real spot is. A force-killed ``npm ci`` can therefore leave a partial
    tree here with zero correctness impact (its junk is simply ignored), but sweeping reclaims the
    disk. Guarded by age so an in-flight concurrent build's own staging is never deleted out from
    under it."""
    try:
        now = time.time()
        for child in parent.iterdir():
            name = child.name
            if name == keep or not name.startswith(".") or ".partial-" not in name:
                continue
            try:
                if now - child.stat().st_mtime < max_age_seconds:
                    continue
            except OSError:
                continue
            shutil.rmtree(child, ignore_errors=True)
    except OSError:
        pass


def _ensure_warm_node_modules_prebake() -> Path | None:
    """Build (once per arch+lockhash) a prebaked node_modules from the pinned scaffold lock.

    Deterministic `npm ci` from the scaffold's package-lock.json into an arch+lockhash-keyed dir,
    using the shared tarball cache so the FIRST build warms the cache and every later business copies
    from this tree instead of resolving+downloading again. Returns the prebake dir on success, else
    None (callers degrade to a normal install).

    Crash-safe by construction — no lock, no marker. `npm ci` runs into a private temp sibling on the
    same filesystem, and only a fully-installed, verified tree is published into the real arch+lockhash
    spot with a single atomic ``os.replace``. The real spot is therefore ALWAYS absent-or-complete: a
    force-killed worker (the ``stop-sigterm timed out. Killing.`` case) can only ever leave an orphan
    ``.partial-*`` sibling — ignored, and swept on the next run — never a stranded "reserved" marker
    that would permanently revert every later build to a cold install, and never a half-installed tree
    that could be mistaken for complete and seeded into a business. A killed build leaves the real spot
    untouched, so the next build simply retries."""
    prebake = _warm_node_modules_prebake_dir()
    if prebake is None:
        return None
    if _warm_node_modules_ready(prebake):
        return prebake
    scaffold = _subuser_app_scaffold_source_dir()
    scaffold_lock = scaffold / "package-lock.json"
    scaffold_pkg = scaffold / "package.json"
    if not (scaffold_lock.is_file() and scaffold_pkg.is_file()):
        return None
    npm = _resolve_runtime_executable("npm")
    if not npm:
        return None
    parent = prebake.parent
    try:
        parent.mkdir(parents=True, exist_ok=True)
    except OSError:
        return None
    _sweep_warm_prebake_partials(parent, keep=prebake.name)
    staging: Path | None = None
    try:
        # Private staging sibling on the SAME filesystem as the real spot, so the publish below is a
        # true atomic rename (not a cross-device copy). mkdtemp's unique name means concurrent builds
        # never collide and a crashed build can't poison a shared path.
        staging = Path(tempfile.mkdtemp(prefix=f".{prebake.name}.partial-", dir=str(parent)))
        # Seed package.json + lock into the staging dir, then `npm ci` the exact closure. The shared
        # (arch-keyed) npm tarball cache from _javascript_install_env keeps this offline-fast after the
        # registry has been hit once. --ignore-scripts matches the scaffold install path (esbuild 0.21
        # ships platform binaries as optionalDependencies, no postinstall).
        shutil.copy2(scaffold_pkg, staging / "package.json")
        shutil.copy2(scaffold_lock, staging / "package-lock.json")
        env = _javascript_install_env(staging)
        proc = subprocess.run(
            [npm, "ci", "--prefer-offline", "--no-audit", "--no-fund", "--ignore-scripts"],
            cwd=str(staging),
            text=True,
            capture_output=True,
            timeout=600,
            env=env,
        )
        if proc.returncode != 0 or not _warm_node_modules_ready(staging):
            return None
        # Publish. Try the atomic rename FIRST. Into an ABSENT spot this is fully race-free
        # (first-writer-wins): if a concurrent build already created the spot, our os.replace fails and
        # we reuse theirs below — we never delete a freshly-published copy, and there is no rmtree
        # window. Only a genuine NON-ready leftover (a pre-fix stranded marker / half-tree) can block
        # us; clear THAT by moving it aside with an atomic rename rather than an in-place rmtree, so the
        # spot is occupied at every instant except a single rename's width, then land ours.
        try:
            os.replace(str(staging), str(prebake))
            staging = None  # consumed by the rename
            return prebake
        except OSError:
            pass
        if _warm_node_modules_ready(prebake):
            return prebake  # a concurrent build published a complete tree — reuse it, never delete it
        aside = prebake.parent / f".{prebake.name}.partial-stale-{os.getpid()}"
        try:
            os.replace(str(prebake), str(aside))  # atomic move-aside of the non-ready leftover
        except OSError:
            aside = None  # another build already cleared/replaced the spot in the meantime
        try:
            os.replace(str(staging), str(prebake))
            staging = None
            return prebake
        except OSError:
            # Lost a publish race after clearing: accept a ready spot, else fail soft to a cold install.
            return prebake if _warm_node_modules_ready(prebake) else None
        finally:
            if aside is not None:
                shutil.rmtree(aside, ignore_errors=True)
    except Exception:
        return None
    finally:
        if staging is not None:
            shutil.rmtree(staging, ignore_errors=True)


def _copy_node_modules_tree(src: Path, dst: Path) -> bool:
    """Copy a prebaked node_modules tree into a workspace, preferring hardlinks for speed/space.

    Hardlinks make the per-business seed near-instant and share inodes with the prebake; falls back
    to a full copy when the destination is on a different filesystem (cross-device link error).
    Preserve npm's .bin symlinks: following them turns .bin/vite into a regular file whose relative
    imports resolve from node_modules/.bin instead of node_modules/vite/bin."""
    try:
        if dst.exists():
            return True
        try:
            shutil.copytree(src, dst, copy_function=os.link, dirs_exist_ok=False, symlinks=True)
            return True
        except (OSError, shutil.Error):
            # Cross-device or partial-hardlink failure: clean up and do a plain copy.
            if dst.exists():
                shutil.rmtree(dst, ignore_errors=True)
            shutil.copytree(src, dst, dirs_exist_ok=False, symlinks=True)
            return True
    except Exception:
        if dst.exists():
            shutil.rmtree(dst, ignore_errors=True)
        return False


def _repair_node_modules_bin_links(root: Path) -> list[str]:
    """Repair npm .bin entries that were accidentally materialized as regular files.

    A prior warm-copy bug followed symlinks, so node_modules/.bin/vite became a hardlinked copy of
    node_modules/vite/bin/vite.js. Vite's own bin imports ../dist/node/cli.js relative to its file
    location, so the regular-file copy tries node_modules/dist/node/cli.js and every build fails.
    """
    nm = root / "node_modules"
    bin_dir = nm / ".bin"
    if not bin_dir.is_dir():
        return []
    repairs: list[str] = []
    expected = {
        "vite": Path("vite/bin/vite.js"),
        "tsc": Path("typescript/bin/tsc"),
        "tsserver": Path("typescript/bin/tsserver"),
    }
    for name, target_rel in expected.items():
        target = nm / target_rel
        link = bin_dir / name
        if not target.is_file():
            continue
        desired = Path("..") / target_rel
        if link.is_symlink():
            try:
                if Path(os.readlink(link)) == desired:
                    continue
            except OSError:
                pass
        try:
            if link.exists() or link.is_symlink():
                link.unlink()
            link.symlink_to(desired)
            repairs.append(f"relinked node_modules/.bin/{name}")
        except OSError:
            continue
    return repairs


def _warm_node_modules_safe_for_docker_consumer() -> bool:
    """True only when a host-built node_modules is binary-compatible with the docker worker container.

    The prebake is built with the HOST's npm, so node_modules carries host-arch native binaries
    (esbuild, etc.). The docker worker runs a Linux container; seeding a foreign-arch tree into the
    bind-mounted workspace would hard-fail the container's vite build. On a Linux host (the production
    VPS) host==container arch, so the seed is safe and the worker reuses it directly. On non-Linux
    hosts (dev), skip the workspace seed and let the container do its own warm `npm ci` against the
    shared (arch-neutral) npm tarball cache instead."""
    return platform.system().lower() == "linux"


def _seed_warm_node_modules(workspace_root: Path, *, for_docker_consumer: bool = False) -> bool:
    """Drop a prebaked node_modules into a fresh workspace when its lock is the pinned scaffold lock.

    Gated on an EXACT scaffold-lockfile-hash match so we never seed a mismatched dependency set; on
    any drift the caller's normal install runs instead. When ``for_docker_consumer`` is set, also
    require host/container arch compatibility so we never hand the Linux worker a foreign-arch tree.
    node_modules is excluded from canonical storage + the durability read-back hash set
    (storage._SYNC_EXCLUDED_SEGMENTS, _WORKSPACE_DURABILITY_EXCLUDED_PARTS), so this seed stays purely
    local and never ships to the remote mirror. Returns True when node_modules is present afterwards."""
    try:
        if _node_modules_present(workspace_root):
            return True
        if for_docker_consumer and not _warm_node_modules_safe_for_docker_consumer():
            return False
        if not _workspace_lockfile_matches_scaffold(workspace_root):
            return False
        prebake = _ensure_warm_node_modules_prebake()
        if prebake is None:
            return False
        return _copy_node_modules_tree(prebake / "node_modules", workspace_root / "node_modules")
    except Exception:
        return False


def _javascript_surface_runtime_env(root: Path) -> dict[str, str]:
    source_root = root.resolve()
    takyon_home = Path(os.getenv("TAKYON_HOME") or get_takyon_home()).expanduser()
    token = str(source_root)
    digest = hashlib.sha256(token.encode("utf-8")).hexdigest()[:16]
    runtime_root = takyon_home / "tmp" / "surface-js" / digest
    home_dir = runtime_root / "home"
    cache_dir = runtime_root / "cache"
    # npm tarball cache is shared across businesses (arch-keyed), NOT per-business: a per-business
    # cache is always cold on a fresh create. HOME / XDG_CACHE_HOME / COREPACK_HOME stay per-business
    # because they hold transient/runtime state, not the reusable content-addressed package cache.
    npm_cache_dir = _shared_npm_cache_dir()
    corepack_home = runtime_root / "corepack"
    for path in (home_dir, cache_dir, corepack_home):
        path.mkdir(parents=True, exist_ok=True)
    return _runtime_env(
        {
            "HOME": str(home_dir),
            "XDG_CACHE_HOME": str(cache_dir),
            "NPM_CONFIG_CACHE": str(npm_cache_dir),
            "npm_config_cache": str(npm_cache_dir),
            "COREPACK_HOME": str(corepack_home),
        }
    )


def _javascript_install_env(root: Path) -> dict[str, str]:
    env = _javascript_surface_runtime_env(root)
    env["NODE_ENV"] = "development"
    env["NPM_CONFIG_PRODUCTION"] = "false"
    env.pop("npm_config_production", None)
    return env


def _javascript_run_script_command(manager: dict[str, Any], script: str, *, root: Path) -> list[str] | None:
    base = list(manager.get("command") or [])
    name = str(manager.get("name") or "npm")
    if base:
        if name == "yarn":
            return [*base, script]
        return [*base, "run", script]
    node = _resolve_runtime_executable("node")
    if node and _node_modules_present(root):
        return [node, "--run", script]
    return None


def _static_surface_can_skip_package_manager(root: Path, scripts: dict[str, Any]) -> bool:
    if not (root / "index.html").exists():
        return False
    if any((root / name).exists() for name in ("next.config.js", "next.config.mjs", "next.config.ts", "vite.config.js", "vite.config.ts", "tsconfig.json")):
        return False
    static_suffixes = {".html", ".css", ".js", ".json", ".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg", ".ico", ".txt", ".md"}
    for path in root.rglob("*"):
        if not path.is_file() or _product_source_is_skipped(path):
            continue
        if path.suffix.lower() not in static_suffixes:
            return False
    build = str(scripts.get("build") or "").strip()
    if not build:
        return True
    return bool(re.match(r"^(?::|true|echo\b|printf\b|exit\s+0\b)", build))


def _product_publish_output_requirements(source_root: Path) -> str:
    return "dist/index.html from the pinned Vite build"


def _product_publish_readiness_blocker(source_root: Path) -> str:
    static_publish_source, _static_publish_label = _product_static_publish_source(source_root)
    if static_publish_source is not None:
        return ""
    detail = "refresh/build finished, but dist/index.html is missing from the pinned Vite output"
    return (
        "refresh/build finished, but no publishable output exists; "
        f"{detail}; {_product_publish_output_requirements(source_root)}"
    )


def _surface_refresh_has_forbidden_source_blockers(surface_refresh: dict[str, Any] | None) -> bool:
    if not isinstance(surface_refresh, dict):
        return False
    blockers = surface_refresh.get("blockers")
    return isinstance(blockers, list) and bool(blockers)


def _blocked_message(text: Any) -> str:
    message = str(text or "").strip()
    if not message:
        return "BLOCKED: exact blocker unavailable"
    if message.startswith("BLOCKED:"):
        return message
    return f"BLOCKED: {message}"


def _refresh_product_surface_path(
    business_root: Path,
    source_path: str,
    *,
    surface: dict[str, Any] | None = None,
    plans: list[dict[str, Any]] | None = None,
    install: bool = True,
    timeout_seconds: int = 180,
) -> dict[str, Any]:
    source_rel = _safe_relpath(source_path or "product/site", field="source_path").as_posix()
    root = (business_root / source_rel).resolve()
    result: dict[str, Any] = {
        "source_path": source_rel,
        "absolute_path": str(root),
        "generated_at": _now(),
        "status": "unverified",
        "checks": [],
        "repairs": [],
        "warnings": [],
        "inventory": _product_inventory(business_root, source_rel, surface=surface),
        "capabilities": _runtime_capabilities(("node", "npm", "npx", "corepack", "pnpm", "yarn", "bun", "python", "pip", "uv")),
    }
    if business_root.resolve() not in (root, *root.parents):
        result.update({"status": "failed", "error": "source path escaped business root"})
        return result
    if not root.exists() or not root.is_dir():
        result.update({"status": "missing", "error": "source path does not exist"})
        return result

    files = _product_source_files(root)
    result["source_file_count"] = len(files)
    result["sample_files"] = files[:25]
    nested = _detect_nested_workspace_prefix(root, source_rel)
    if nested:
        result.update({
            "status": "failed",
            "error": f"source appears nested under duplicate workspace prefix: {nested}",
            "nested_source_path": f"{source_rel}/{nested}",
        })
        return result
    if not files:
        result.update({"status": "missing", "error": "source path contains no recognized product source files"})
        return result

    package_json = root / "package.json"
    if not package_json.exists():
        result.update({
            "status": "blocked",
            "error": (
                "product app must use the pinned Vite scaffold with a package.json, a build script, "
                "and publishable dist/index.html output"
            ),
        })
        return result

    try:
        package_data = json.loads(package_json.read_text(encoding="utf-8"))
    except Exception as exc:
        result.update({"status": "failed", "error": f"package.json is not valid JSON: {exc}"})
        return result
    scripts = package_data.get("scripts") if isinstance(package_data.get("scripts"), dict) else {}
    dependencies = package_data.get("dependencies") if isinstance(package_data.get("dependencies"), dict) else {}
    dev_dependencies = package_data.get("devDependencies") if isinstance(package_data.get("devDependencies"), dict) else {}
    deps = {**dependencies, **dev_dependencies}
    looks_next = (
        "next" in deps
        or any((root / name).exists() for name in ("next.config.js", "next.config.mjs", "next.config.ts"))
        or (root / ".next").is_dir()
    )
    if looks_next:
        result.update({
            "status": "blocked",
            "error": (
                "Next/AppKit product trees are unsupported. Rebuild this workspace on the pinned "
                "Vite scaffold and publish dist/index.html."
            ),
        })
        return result
    normalization = _normalize_supported_product_build_shape(
        root,
        scripts=scripts,
        deps=deps,
    )
    result["repairs"] = list(normalization.get("repairs") or [])
    result["warnings"].extend(str(item).strip() for item in (normalization.get("warnings") or []) if str(item).strip())
    if normalization.get("blocked"):
        result.update({
            "status": "blocked",
            "error": str(normalization.get("error") or "unsupported build shape requires manual repair"),
        })
        return result
    try:
        package_data = json.loads(package_json.read_text(encoding="utf-8"))
    except Exception as exc:
        result.update({"status": "failed", "error": f"package.json is not valid JSON after normalization: {exc}"})
        return result
    scripts = package_data.get("scripts") if isinstance(package_data.get("scripts"), dict) else {}
    dependencies = package_data.get("dependencies") if isinstance(package_data.get("dependencies"), dict) else {}
    dev_dependencies = package_data.get("devDependencies") if isinstance(package_data.get("devDependencies"), dict) else {}
    deps = {**dependencies, **dev_dependencies}
    is_vite = "vite" in deps or any((root / name).exists() for name in ("vite.config.js", "vite.config.ts"))
    if not is_vite:
        result.update({
            "status": "blocked",
            "error": (
                "unsupported product build shape; expected the pinned Vite scaffold with a Vite "
                "build that writes dist/index.html"
            ),
        })
        return result
    if _static_surface_can_skip_package_manager(root, scripts):
        result.update({
            "status": "blocked",
            "error": "raw static product sites are unsupported; use the pinned Vite scaffold and publish dist/index.html",
        })
        return result
    package_manager_name = _javascript_package_manager_name(root, package_data)
    package_manager = _javascript_package_manager_command(package_manager_name)
    result["package_manager"] = {key: package_manager.get(key) for key in ("name", "available", "source")}
    if install and not package_manager.get("available"):
        ensure = _ensure_javascript_runtime(package_manager=True)
        result["checks"].append({
            "command": ["takyon", "ensure-runtime", "javascript-package-manager"],
            "status": "passed" if ensure.get("success") else "blocked",
            "result": ensure,
        })
        package_manager = _javascript_package_manager_command(package_manager_name)
        result["package_manager"] = {key: package_manager.get(key) for key in ("name", "available", "source")}
        result["capabilities"] = _runtime_capabilities(("node", "npm", "npx", "corepack", "pnpm", "yarn", "bun", "python", "pip", "uv"))
    if not package_manager.get("available") and not _node_modules_present(root):
        result.update({
            "status": "blocked",
            "error": "javascript package manager is unavailable for dependency installation",
            "missing_capabilities": [package_manager_name],
            "remediation": "Install or enable the declared package manager, or allow Takyon runtime installs so it can provision a local JavaScript runtime/package manager.",
        })
        return result
    inventory = _product_inventory(business_root, source_rel, surface=surface)
    result["inventory"] = inventory
    forbidden_findings = inventory.get("forbidden_findings") if isinstance(inventory.get("forbidden_findings"), list) else []
    reserved_namespace_routes = inventory.get("reserved_namespace_routes") if isinstance(inventory.get("reserved_namespace_routes"), list) else []
    blockers = _format_forbidden_product_source_blockers(forbidden_findings, reserved_namespace_routes)
    if blockers:
        result.update(
            {
                "status": "blocked",
                "error": "product source violates runtime authority boundaries:\n- " + "\n- ".join(blockers),
                "blockers": blockers,
            }
        )
        return result
    if _workspace_needs_runtime_ui_contract(source_rel):
        try:
            # The kit is statically imported into the pinned Vite bundle, so refresh must
            # rewrite it from the current surface truth before the build runs.
            _materialize_subuser_app_kit(
                root,
                slug=business_root.name,
                surface=surface,
                plans=plans,
            )
        except Exception as exc:
            result.update({"status": "failed", "error": f"failed to materialize runtime kit: {exc}"})
            return result
    # A freshly-materialized readback/cache workspace is deps-free by design (node_modules is
    # never synced into canonical storage), so install MUST run there even when a caller passes
    # install=False — otherwise the build false-fails later with a misleading "vite: not found".
    # (The package-manager-unavailable + node_modules-absent case is already fail-closed above.)
    if install or not _node_modules_present(root):
        # Warm start: when the workspace lock is the pinned scaffold lock, drop in the prebaked
        # node_modules (hardlinked from the arch+lockhash-keyed prebake). If the seed lands a complete,
        # lock-matching tree we can SKIP the install entirely — the prebake was already `npm ci`'d from
        # this exact lock and verified to carry vite+tsc, so it IS the lock closure. This is the big
        # win: the dominant cost (cold resolve+download+extract) disappears for every business after
        # the first. node_modules never enters canonical storage (storage._SYNC_EXCLUDED_SEGMENTS) so
        # this stays purely local. NB: a warm seed must be dropped BEFORE choosing the install command,
        # because `npm ci` would otherwise wipe node_modules and reinstall, defeating the warm start.
        warm_seeded = False
        if not _node_modules_present(root):
            warm_seeded = _seed_warm_node_modules(root)
        warm_complete = (
            warm_seeded
            and _node_modules_present(root)
            and _workspace_lockfile_matches_scaffold(root)
        )
        if warm_complete:
            result["warnings"].append(
                "dependency install skipped: prebaked node_modules matches the pinned scaffold lock"
            )
        elif package_manager.get("available"):
            install_check = _run_surface_command(
                _javascript_install_command(package_manager, root=root),
                cwd=root,
                timeout_seconds=timeout_seconds,
                env=_javascript_install_env(root),
            )
            result["checks"].append(install_check)
            if install_check["status"] != "passed":
                detail = ((install_check.get("stdout") or "") + "\n" + (install_check.get("stderr") or "")).strip()
                result.update({"status": "failed", "error": "dependency install failed" + (f":\n{detail[:4000]}" if detail else "")})
                return result
        else:
            result["warnings"].append("dependency install skipped because no package manager is available; using existing node_modules")
    bin_link_repairs = _repair_node_modules_bin_links(root)
    if bin_link_repairs:
        result["repairs"].extend(bin_link_repairs)
    if "build" not in scripts:
        result.update({
            "status": "blocked",
            "error": "package.json is missing the required build script for the pinned Vite scaffold",
        })
        return result
    build_command = _javascript_run_script_command(package_manager, "build", root=root)
    if not build_command:
        result.update({
            "status": "blocked",
            "error": "no available runtime command for package build script",
            "missing_capabilities": [package_manager_name, "node"],
        })
        return result
    build_check = _run_surface_command(
        build_command,
        cwd=root,
        timeout_seconds=timeout_seconds,
        env=_javascript_surface_runtime_env(root),
    )
    result["checks"].append(build_check)
    if build_check["status"] != "passed":
        detail = ((build_check.get("stdout") or "") + "\n" + (build_check.get("stderr") or "")).strip()
        result.update({"status": "failed", "error": "product build failed" + (f":\n{detail[:4000]}" if detail else "")})
        return result
    if "typecheck" in scripts:
        typecheck_command = _javascript_run_script_command(package_manager, "typecheck", root=root)
        if not typecheck_command:
            result.update({
                "status": "blocked",
                "error": "no available runtime command for package typecheck script",
                "missing_capabilities": [package_manager_name, "node"],
            })
            return result
        typecheck = _run_surface_command(
            typecheck_command,
            cwd=root,
            timeout_seconds=timeout_seconds,
            env=_javascript_surface_runtime_env(root),
        )
        result["checks"].append(typecheck)
        if typecheck["status"] != "passed":
            detail = ((typecheck.get("stdout") or "") + "\n" + (typecheck.get("stderr") or "")).strip()
            result.update({"status": "failed", "error": "product typecheck failed" + (f":\n{detail[:4000]}" if detail else "")})
            return result
    publish_blocker = _product_publish_readiness_blocker(root)
    if publish_blocker:
        result.update({"status": "blocked", "error": publish_blocker})
        return result
    result.update({"status": "passed", "kind": "node_build"})
    return result


def _normalize_billing_interval(value: Any) -> str:
    raw = str(value or "month").strip().lower().replace("-", "_")
    # Monthly-only (plan §2.7): the interval axis is gone; only month spellings normalize.
    return "month" if raw in {"", "month", "monthly", "mo", "per_month"} else raw


def _normalize_included_ai_budget_microusd(
    value: Any,
    *,
    price_cents: Any,
    billing_interval: Any,
    tier: Any,
    default: int = 0,
) -> int:
    # ONE cap, always applied, FAIL-LOUD (plan §2.7): the canonical copy lives in
    # app_entitlements; the old second copy here silently clamped — a plan that spends more
    # than it charges must be refused with the figures, never silently adjusted.
    from .app_entitlements import _monthly_plan_price_cap_microusd

    budget = int(float(default if value in {None, ""} else value))
    if budget < 0:
        raise TakyonError("included_ai_budget_microusd must be non-negative")
    cap = _monthly_plan_price_cap_microusd(price_cents)
    if budget > cap:
        raise TakyonError(
            f"included_ai_budget_microusd ({budget}) exceeds the plan's monthly price cap "
            f"({cap} microUSD = 100% of price_cents={int(float(price_cents or 0))}). Lower "
            "the budget or raise the price; the budget is no longer silently clamped."
        )
    return budget


_BRAIN_COMPLETION_MARKERS = (
    re.compile(r"\b(?:complete|completed|done|built|published|deployed|wired)\b", re.IGNORECASE),
    re.compile(r"✅"),
)
_BRAIN_COMPLETION_EVIDENCE_TERMS = (
    ("source files", ("source file", "source files", "source_path", "source path")),
    ("runtime/tool endpoint used", ("runtime/tool endpoint", "runtime endpoint", "tool endpoint", "endpoint used", "tool used", "runtime used")),
    ("audit/test record", ("audit record", "audit", "receipt", "test record", "test_record", "job id", "agent record")),
    ("remaining blocker", ("remaining blocker", "blocker", "blocked", "not wired")),
)

_TAKYON_PATH_EXACT_ALIASES = {
    "brain/index.md": "research/index.md",
    "brain/business-model.md": "research/strategy.md",
    "brain/pulse.md": "metrics/summary.md",
    "brain/wake_journal.md": "metrics/wake-history.md",
    "app/index.md": "product/surface.md",
    "app/surface.md": "product/surface.md",
    "sales/surface.md": "distribution/surface.md",
    "conversations/index.md": "metrics/conversations/index.md",
    "conversations/corpus/messages.jsonl": "metrics/conversations/corpus/messages.jsonl",
    "conversations/corpus/events.jsonl": "metrics/conversations/corpus/events.jsonl",
}
_TAKYON_PATH_PREFIX_ALIASES = (
    ("brain/", "research/"),
    ("app/", "product/"),
    ("conversations/", "metrics/conversations/"),
    ("receipts/", "metrics/receipts/"),
    ("sales/", "distribution/"),
    ("campaigns/", "distribution/campaigns/"),
    ("outreach/", "distribution/outreach/"),
)


def _canonical_business_relpath(rel: str) -> str:
    normalized = _safe_relpath(rel, field="business path").as_posix()
    exact = _TAKYON_PATH_EXACT_ALIASES.get(normalized)
    if exact:
        return exact
    for old_prefix, new_prefix in _TAKYON_PATH_PREFIX_ALIASES:
        if normalized.startswith(old_prefix):
            return new_prefix + normalized[len(old_prefix):]
    return normalized


def _canonical_business_output_relpath(rel: str, *, field: str = "business path") -> str:
    normalized = _canonical_business_relpath(rel)
    if normalized in {"", "."}:
        raise TakyonError(
            f"{field} must stay under one of "
            + ", ".join(f"{root}/" for root in TAKYON_BUSINESS_ROOTS)
        )
    parts = Path(normalized).parts
    if not parts or parts[0] not in TAKYON_BUSINESS_ROOTS:
        raise TakyonError(
            f"{field} must stay under one of "
            + ", ".join(f"{root}/" for root in TAKYON_BUSINESS_ROOTS)
        )
    return normalized


def _validate_brain_index_completion_gate(rel: str, content: str) -> None:
    if rel != "research/index.md":
        return
    if not any(pattern.search(content) for pattern in _BRAIN_COMPLETION_MARKERS):
        return
    lowered = content.lower()
    missing = [
        label
        for label, needles in _BRAIN_COMPLETION_EVIDENCE_TERMS
        if not any(needle in lowered for needle in needles)
    ]
    if missing:
        raise TakyonError(
            "research/index.md cannot claim complete/built/done work without a feature evidence ledger. "
            "For each feature list source files, runtime/tool endpoint used, audit/test record, "
            f"and remaining blocker. Missing: {', '.join(missing)}"
        )


def _clamp_int(value: Any, *, default: int, minimum: int, maximum: int) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        parsed = default
    return max(minimum, min(parsed, maximum))


def _clamp_float(value: Any, *, default: float, minimum: float, maximum: float) -> float:
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        parsed = default
    return max(minimum, min(parsed, maximum))


def _env_positive_float(name: str, fallback: float) -> float:
    raw = os.environ.get(name)
    if raw is None or not raw.strip():
        return fallback
    try:
        parsed = float(raw)
    except (TypeError, ValueError):
        return fallback
    return parsed if parsed > 0 else fallback


def _truncate_text(value: str, limit: int = 20_000) -> str:
    text = str(value or "")
    return text if len(text) <= limit else text[:limit] + "\n[truncated]"


def _hash_token(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def _random_token() -> str:
    import secrets

    return secrets.token_urlsafe(32)


def _normalize_email(value: str) -> str:
    email = str(value or "").strip().lower()
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email):
        raise TakyonError("valid email is required")
    return email


def _is_service_email(value: Any) -> bool:
    try:
        from . import app_actions as takyon_app_actions
    except Exception:
        from plugins.takyon import app_actions as takyon_app_actions

    return takyon_app_actions.is_service_email(value)


def _app_user_is_service_identity(user: Mapping[str, Any] | None) -> bool:
    if not isinstance(user, Mapping):
        return False
    return _is_service_email(user.get("email"))


def _normalize_domain_name(value: str, *, field: str = "domain") -> str:
    raw = str(value or "").strip().lower().rstrip(".")
    if not raw:
        raise TakyonError(f"{field} is required")
    parsed = urllib.parse.urlparse(raw if "://" in raw else f"//{raw}")
    domain = (parsed.netloc or parsed.path).split("/", 1)[0].strip().rstrip(".")
    if ":" in domain:
        domain = domain.split(":", 1)[0]
    if not _DOMAIN_RE.match(domain):
        raise TakyonError(f"{field} is not a valid DNS name: {value!r}")
    return domain


def _company_base_domain(value: Any = None) -> str:
    load_takyon_env()
    configured = (
        str(value or "").strip()
        or os.getenv("PUBLIC_COMPANY_BASE_DOMAIN", "").strip()
        or os.getenv("TAKYON_COMPANY_BASE_DOMAIN", "").strip()
        or _DEFAULT_COMPANY_BASE_DOMAIN
    )
    return _normalize_domain_name(configured, field="base_domain")


def _business_domain_candidates(slug: str, *, base_domain: Any = None, explicit: Any = None) -> list[str]:
    business = _slugify(slug)
    base = _company_base_domain(base_domain)
    candidates = [f"{business}.{base}"]
    for item in _as_list(explicit):
        raw = str(item or "").strip()
        if not raw:
            continue
        domain = _normalize_domain_name(raw if "." in raw else f"{raw}.{base}", field="subdomain")
        suffix = f".{base}"
        if domain == base or not domain.endswith(suffix):
            raise TakyonError(f"business subdomain must be under {base}: {domain}")
        if domain != f"{business}.{base}" and not domain.endswith(f".{business}.{base}"):
            raise TakyonError(
                f"refusing to delete {domain}; explicit subdomains must belong to business:{business}"
            )
        if domain not in candidates:
            candidates.append(domain)
    return candidates


def _product_publish_target(slug: str, explicit: Any = None) -> str:
    raw = str(explicit or "").strip()
    if not raw:
        return f"https://{_business_domain_candidates(slug)[0]}/"
    if "://" not in raw:
        raw = f"https://{raw}"
    parsed = urllib.parse.urlparse(raw)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise TakyonError(f"publish_target must be an http(s) URL or domain: {explicit!r}")
    host = _normalize_domain_name(parsed.netloc, field="publish_target")
    path = parsed.path or "/"
    if not path.startswith("/"):
        path = f"/{path}"
    return urllib.parse.urlunparse((parsed.scheme, host, path, "", "", ""))


# Legacy company base domains a pre-rebrand business may have persisted in its surface contract.
# A persisted "<slug>.fourmanifold.com" must read back as the CURRENT base domain so the dashboard
# never "quantum"-flips between the stale persisted host and the computed current host on refresh.
_LEGACY_COMPANY_BASE_DOMAINS = frozenset({"fourmanifold.com"})


def _rebase_to_company_domain(url: str) -> str:
    """Rewrite a legacy company base domain (e.g. fourmanifold.com) in `url` to the current company
    base domain (coscale.app), preserving the <slug> label, scheme, and path. Returns `url`
    unchanged when it carries no legacy base domain. This is the recompute-on-read chokepoint: it
    makes a stale persisted publish_target/public_url resolve to the current host on every read, so
    a refresh is stable regardless of what the column still holds."""
    raw = str(url or "").strip()
    if not raw:
        return raw
    try:
        parsed = urllib.parse.urlparse(raw if "://" in raw else f"https://{raw}")
    except Exception:
        return raw
    netloc = (parsed.netloc or "").strip()
    if not netloc:
        return raw
    hostname = netloc.split("@")[-1].split(":")[0].lower()
    current = str(_company_base_domain() or "").strip().lower()
    if not current:
        return raw
    for legacy in _LEGACY_COMPANY_BASE_DOMAINS:
        if legacy == current:
            continue
        if hostname == legacy or hostname.endswith("." + legacy):
            new_hostname = hostname[: len(hostname) - len(legacy)] + current
            return urllib.parse.urlunparse(
                (parsed.scheme or "https", new_hostname, parsed.path or "/", "", "", "")
            )
    return raw


