def _creative_credit_reservation_outcome(store: "TakyonStore", business: str, reservation_key: str) -> dict[str, Any]:
    """Resolve a creative-credit reservation key's prior ledger outcome (read-only).

    Returns {"state": "none" | "in_flight" | "committed" | "released", "metadata": {...}} — the
    metadata is the terminal (commit/release) entry's, which for mobile_release carries the settled
    build_id. This is what makes publish idempotency REAL: the SQL reserve gate replays a known key
    without holding anything, so callers must branch on the prior outcome instead of re-running."""
    try:
        with store._connect() as conn:
            rows = conn.execute(
                "select kind, metadata from business_creative_credit_entries "
                "where business_slug = ? and reservation_key = ? order by id",
                (business, reservation_key),
            ).fetchall()
    except Exception:
        rows = []
    state = "none"
    metadata: dict[str, Any] = {}
    kinds = []
    for row in rows or []:
        kind = str(row["kind"] if isinstance(row, Mapping) else row[0] or "").strip()
        kinds.append(kind)
        raw_meta = row["metadata"] if isinstance(row, Mapping) else row[1]
        if kind in ("commit", "release") and isinstance(raw_meta, Mapping):
            metadata = dict(raw_meta)
    if "commit" in kinds:
        state = "committed"
    elif "release" in kinds:
        state = "released"
    elif "reserve" in kinds:
        state = "in_flight"
    return {"state": state, "metadata": metadata}


def handle_business_publish_mobile_release(args: dict, **_: Any) -> str:
    """Build + ship a mobile_app release via EAS (readmodular §2.4/§2.5). Gates (fail-closed, in
    order): refuse on autonomous wake (spendful); required idempotency_key (a retried publish must
    never double-charge); business must be archetype mobile_app; mobile_app must be SELECTABLE
    (archetype registry gate); the app source at product/app must exist; the greenlight
    pre-submission compliance gate must pass (preview→internal lane, production→production lane) —
    ALL before any credit reserve, so a refused publish charges nothing. Only then runs the
    settle-at-trigger money flow (store_build.run_build): reserve creative credits → invoke EAS →
    settle at successful trigger / release on failure. The invoker is the real local builder
    (store_builder.local_eas_invoker, the live-proven recipe) when its explicit-path custody
    resolves, else the fail-closed default (eas_builder_unconfigured). Secrets reach only the
    builder's child process — never this plane's environ, never /v1/env."""
    # Operator ruling 2026-07-08: no wake refusal here. The operator plane is god-mode — bootstrap
    # and scheduled wakes may both publish builds (the spend is bounded by the credit rail and the
    # ≤3-attempt repair loop in the takyon-mobile-app skill). App Store SUBMISSION (the outward,
    # account-blast-radius step) is a separate lane that keeps its operator_approvals receipt.
    store = _store()
    try:
        business = _resolved_business_slug(args, required=True)
        lane = str(args.get("lane") or "preview").strip().lower()
        if lane not in ("preview", "production"):
            raise TakyonError("lane must be 'preview' (TestFlight-internal) or 'production' (store)")
        idempotency_key = str(args.get("idempotency_key") or "").strip()
        if not idempotency_key:
            raise TakyonError(
                "idempotency_key is required for a mobile release (a retried publish must re-attach, "
                "never double-charge)"
            )
        arch = _archetype_leaf()
        with store._connect() as conn:
            row = store._ensure_business(conn, business)
        archetype = str((row or {}).get("archetype") or "web_saas")
        if arch.normalize_archetype(archetype, allow_empty=True) != arch.MOBILE_APP:
            raise TakyonError(
                f"business_publish_mobile_release is for mobile_app businesses; '{business}' is "
                f"'{archetype}'."
            )
        # Fail closed until the mobile_app pipeline is E2E-proven (readmodular §5 rollout).
        arch.assert_selectable(arch.MOBILE_APP)
        # A real EAS build runs for minutes — defer to the worker plane when enabled (the money flow
        # below runs inside the worker's inline re-invocation, once). Returns None ⇒ run inline here.
        # Preview-only enablement (TAKYON_ARCHETYPE_PREVIEW) is process-local, so a deferred re-run
        # on a worker without the env would refuse itself — the preview lane always runs inline.
        preview_only = not arch.BUSINESS_ARCHETYPES[arch.MOBILE_APP].enabled
        deferred = (
            None if preview_only else _defer_mobile_release_to_worker({**args, "business": business, "lane": lane})
        )
        if deferred is not None:
            return deferred
        # The app source is the publish subject — refuse before any spend if it isn't there.
        app_source = store._business_root(business) / "product" / "app"
        if not (app_source / "app.json").is_file():
            raise TakyonError(
                "mobile_app_source_missing: product/app has no app.json. Build the app first "
                "(business_claude_agent_task with workspace 'product/app' seeds and iterates it)."
            )
        # Greenlight pre-submission compliance gate (readmodular §3) — BEFORE reserve: a failing
        # scan must cost nothing. preview ships to TestFlight-internal (internal lane thresholds);
        # production is the store lane (critical==0 AND high==0).
        try:
            from . import store_compliance as _greenlight
        except ImportError:  # pragma: no cover - alternate load path
            from plugins.takyon import store_compliance as _greenlight
        gate = _greenlight.run_preflight_gate(
            str(app_source),
            lane=_greenlight.LANE_PRODUCTION if lane == "production" else _greenlight.LANE_INTERNAL,
        )
        if not gate.get("passed"):
            return tool_error(
                f"greenlight_preflight_failed: {gate.get('detail') or 'compliance scan failed'}",
                success=False,
                compliance=gate,
            )
        sb = _store_build_leaf()
        # The real builder must be configured BEFORE any money moves — an unconfigured builder is a
        # pure gate refusal (genuinely nothing reserved), never a reserve-then-release round-trip
        # that would poison the idempotency key's ledger history.
        try:
            from . import store_builder as _builder
        except ImportError:  # pragma: no cover - alternate load path
            from plugins.takyon import store_builder as _builder
        builder_lane = _builder.builder_mode()
        if not builder_lane:
            return tool_error(
                "eas_builder_unconfigured: no store-builder lane on this plane — neither local "
                "custody (TAKYON_STORE_BUILDER_SECRETS_DIR) nor the host-independent safebox lane "
                "(node/npm/npx/git on PATH + a configured remote safebox). No credits were reserved.",
                success=False,
            )
        if builder_lane == "local":
            builder_creds = _builder.resolve_local_store_credentials()
        else:
            # Host-independent lane: the safebox does the ASC provisioning server-side and returns
            # the ephemeral signing bundle (fail-closed StoreBuilderUnconfigured before any reserve).
            try:
                app_cfg_for_caps = json.loads((app_source / "app.json").read_text(encoding="utf-8"))
            except (OSError, ValueError) as exc:
                raise TakyonError(f"mobile_app_source_invalid: app.json unreadable ({exc})") from exc
            builder_creds = _builder.resolve_safebox_store_credentials(
                business, capabilities=_builder.capabilities_from_app_config(app_cfg_for_caps)
            )
        invoke_eas = _builder.local_eas_invoker(
            business_slug=business, lane=lane, source_dir=str(app_source), creds=builder_creds
        )
        # Exact provider cost per the credit rule (usage_pricing is the SSOT) — unpriced = REFUSED,
        # before reserve (an EAS action can never spend unpriced).
        from agent.usage_pricing import get_pricing_entry as _gpe

        eas_cost_entry = _gpe("build_ios", provider="eas")
        if eas_cost_entry is None or not getattr(eas_cost_entry, "request_cost", None):
            raise TakyonError(
                "eas_build_unpriced: ('eas','build_ios') has no request_cost in usage_pricing — "
                "refusing an unpriced spend"
            )
        provider_cost_usd = float(eas_cost_entry.request_cost)
        credits = _creative_credit_total_cost("mobile_release")
        if credits < 1:
            raise TakyonError(
                f"mobile_release credit cost must be >= 1 (got {credits}); a zero-cost release "
                "would bypass the reservation ledger"
            )
        rk = f"mobile-release:{business}:{lane}:{idempotency_key}"
        # Idempotency is REAL, not just a stable key: the credit ledger replays a reserve for a
        # known key WITHOUT holding anything, so re-running run_build on a used key would trigger a
        # real paid build that settles as a no-op (free/unmetered). Resolve the key's prior outcome
        # first: committed → re-attach and return the prior receipt; released/in-flight → refuse
        # and demand a fresh key.
        prior = _creative_credit_reservation_outcome(store, business, rk)
        if prior.get("state") == "committed":
            prior_meta = prior.get("metadata") or {}
            return tool_result(
                {
                    "success": True,
                    "business": business,
                    "lane": lane,
                    "build_id": str(prior_meta.get("build_id") or ""),
                    "replayed": True,
                    "note": "idempotency_key already settled — returning the prior receipt; no new build was triggered.",
                }
            )
        if prior.get("state") in ("released", "in_flight"):
            raise TakyonError(
                f"idempotency_key already used (reservation {prior['state']}). The ledger will not "
                "re-reserve a replayed key — retry the publish with a NEW idempotency_key."
            )
        result = sb.run_build(
            business_slug=business,
            lane=lane,
            credits=credits,
            reservation_key=rk,
            reserve=lambda b, c, k: _reserve_creative_credits(
                b, action="mobile_release", reservation_key=k, metadata={"lane": lane}
            ),
            # Our invoker never reports actual_credits, so the full reservation settles; if a future
            # invoker DOES report a different actual, it lands visibly in the ledger metadata rather
            # than silently voiding the refund contract.
            settle=lambda k, actual, meta: _commit_creative_credits(
                k,
                action="mobile_release",
                metadata={**meta, "provider": "eas", "provider_model": "build_ios",
                          "provider_cost_usd": provider_cost_usd,
                          **({"actual_credits_reported": int(actual)} if actual is not None and int(actual) != int(credits) else {})},
            ),
            release=lambda k, meta: _release_creative_credits(
                k, action="mobile_release", metadata=meta
            ),
            invoke_eas=invoke_eas,
        )
        return tool_result(
            {
                "success": True,
                "business": business,
                "lane": lane,
                "build_id": result.build_id,
                "logs_url": getattr(result, "logs_url", ""),
                "builder_lane": builder_lane,
                "detail": result.detail,
                "compliance": {"passed": True, "lane": gate.get("lane")},
                "note": "Build triggered and credits settled (spend happens at the Expo trigger). "
                "Check status with business_read_store_status {build_id}; a FAILED build's fix "
                "loop is the takyon-mobile-app skill's build-failure triage (max 3 attempts, "
                "fresh idempotency_key each). Store submission is a separate step.",
            }
        )
    except Exception as exc:
        return tool_error(str(exc), success=False)


def handle_business_read_store_status(args: dict, **_: Any) -> str:
    """CEO evidence surface for a mobile_app business's App Store standing (readmodular §2.5). Today
    it surfaces the Apple developer-ACCOUNT health via the safebox account-health route — the key
    never leaves the safebox, and a non-'ok' state (esp. agreement_blocked) tells the CEO store
    submissions are frozen account-wide before it attempts one. Per-app review/version status lands
    with the submit lane. Read-only; fail-open on the probe (state='unreachable' rather than error)."""
    store = _store()
    try:
        business = _resolved_business_slug(args, required=True)
        archetype = "web_saas"
        with store._connect() as conn:
            row = store._ensure_business(conn, business)
            archetype = str((row or {}).get("archetype") or "web_saas")
        account_health: dict[str, Any]
        try:
            try:
                from . import safebox as _sb
            except ImportError:  # pragma: no cover - alternate load path
                from plugins.takyon import safebox as _sb
            account_health = _sb.store_asc_account_health()
        except Exception as exc:
            # Never hard-fail a read: a probe/transport error surfaces as a state, not a tool error.
            account_health = {"state": "unreachable", "detail": str(exc)[:200], "status_code": None}
        # Optional per-build status read ($0, never touches the reservation): the repair loop's
        # evidence surface. status: finished | errored | in-progress/new/…; errored builds carry
        # the provider error message, and the expo.dev logs page is in the publish receipt.
        build_status: dict[str, Any] | None = None
        requested_build_id = str(args.get("build_id") or "").strip()
        if requested_build_id:
            try:
                try:
                    from . import store_builder as _builder
                except ImportError:  # pragma: no cover - alternate load path
                    from plugins.takyon import store_builder as _builder
                poll_lane = _builder.builder_mode()
                if poll_lane == "local":
                    poll_creds = _builder.resolve_local_store_credentials()
                elif poll_lane == "safebox":
                    poll_creds = _builder.resolve_safebox_store_credentials(business)
                else:
                    raise TakyonError("eas_builder_unconfigured: no builder lane on this plane")
                build_status = _builder.poll_build(requested_build_id, poll_creds)
            except Exception as exc:
                build_status = {"status": "unknown", "artifact_url": "", "error": str(exc)[:200]}
        return tool_result(
            {
                "success": True,
                "business": business,
                "archetype": archetype,
                "account_health": account_health,
                **({"build": {"build_id": requested_build_id, **(build_status or {})}} if requested_build_id else {}),
                "note": "Apple developer-account health; per-app review/version status lands with the submit lane.",
            }
        )
    except Exception as exc:
        return tool_error(str(exc), success=False)


def handle_business_check_runtime_capabilities(args: dict, **_: Any) -> str:
    try:
        if _blocks_session_bound_authority_op():
            raise TakyonError("runtime capability provisioning is available only on the authority tool surface")
        requested = [
            str(item).strip()
            for item in _as_list(args.get("capabilities") or args.get("commands"))
            if str(item).strip()
        ]
        ecosystems = [
            str(item).strip().lower()
            for item in _as_list(args.get("ecosystems") or args.get("ecosystem") or args.get("ensure"))
            if str(item).strip()
        ]
        if not requested:
            requested = ["node", "npm", "npx", "corepack", "pnpm", "yarn", "bun", "python", "pip", "uv", "git", "rg", "deno"]

        ensure_results: list[dict[str, Any]] = []
        for ecosystem in ecosystems:
            if ecosystem in {"javascript", "js", "node"}:
                ensure_results.append({"ecosystem": ecosystem, **_ensure_javascript_runtime(package_manager=False)})
            elif ecosystem in {"javascript-package-manager", "package-manager", "package_manager", "node-package-manager"}:
                ensure_results.append({"ecosystem": ecosystem, **_ensure_javascript_runtime(package_manager=True)})
            elif ecosystem in {"repo-node-dependencies", "node-dependencies", "claude-agent-sdk"}:
                ensure_results.append({
                    "ecosystem": ecosystem,
                    **_ensure_repo_node_dependencies(("@anthropic-ai/claude-agent-sdk",)),
                })
            elif ecosystem in {"python", "py"}:
                ensure_results.append({
                    "ecosystem": ecosystem,
                    "success": bool(_resolve_runtime_executable("python")),
                    "installed": False,
                    "capabilities": _runtime_capabilities(("python", "pip", "uv")),
                    "error": None if _resolve_runtime_executable("python") else "python runtime is unavailable",
                })
            elif ecosystem in {"actions", "app-actions", "app_actions"}:
                # Self-heal a missing Deno (the actions-rail runtime) the same way the
                # javascript ecosystem self-heals node — so this host stops needing a
                # manual `brew install deno` to build+publish a product with actions.
                deno_ensure = _ensure_deno_runtime()
                capabilities = _runtime_capabilities(("deno", "systemd-run"))
                require_systemd_scope = _normalized_host_role() == "operator"
                deno_ready = bool(capabilities.get("deno", {}).get("available"))
                sandbox_ready = bool(capabilities.get("systemd-run", {}).get("available"))
                success = deno_ready and (sandbox_ready if require_systemd_scope else True)
                error = None
                if not deno_ready:
                    error = "deno runtime is unavailable"
                elif require_systemd_scope and not sandbox_ready:
                    error = "operator host requires a working user-scoped systemd-run sandbox for product actions"
                ensure_results.append({
                    "ecosystem": ecosystem,
                    "success": success,
                    "installed": bool(deno_ensure.get("installed")),
                    "ensure": deno_ensure,
                    "capabilities": capabilities,
                    "error": error,
                })
            else:
                ensure_results.append({
                    "ecosystem": ecosystem,
                    "success": False,
                    "installed": False,
                    "error": "unknown ecosystem; inspect explicit capabilities instead",
                })

        capabilities = _runtime_capabilities(requested)
        missing = [name for name, info in capabilities.items() if not info.get("available")]
        return tool_result({
            "success": True,
            "capabilities": capabilities,
            "missing_capabilities": missing,
            "ensure": ensure_results,
            "runtime_installs_allowed": _allow_runtime_installs(),
            "note": (
                "Capability results are evidence for the CEO. Missing runtimes or package managers "
                "should be repaired, provisioned, or recorded as exact blockers; they are not product strategy."
            ),
        })
    except Exception as exc:
        return tool_error(str(exc), success=False)


