def _resolved_business_output_path_for_action(store: "TakyonStore", business: str, raw_path: str, *, action: str) -> tuple[str, Path]:
    requested_path = str(raw_path or "")
    if action == "memory.write" and requested_path and not requested_path.startswith("research/"):
        requested_path = f"research/{requested_path}"
    file_path = store._resolve_business_file(
        business,
        requested_path,
        require_output_root=True,
        field="artifact path",
    )
    rel = str(file_path.relative_to(store._business_root(business, sync=False)))
    return rel, file_path


def _verified_business_file_mutation_response(
    *,
    args: dict,
    operation: dict[str, Any],
    expected_content: str,
    store: "TakyonStore" | None = None,
) -> str:
    try:
        business = _business_slug(
            {
                "business": operation.get("business") or args.get("business"),
                "business_slug": args.get("business_slug"),
            },
            required=True,
        )
        active_store = store or _store()
        result = _commit_tool_data(args, operation, store=active_store)
        rel = str(result.get("path") or "")
        if not rel:
            rel, _ = _resolved_business_output_path_for_action(
                active_store,
                business,
                str(operation.get("path") or ""),
                action=str(operation.get("action") or ""),
            )
        _, file_path = _resolved_business_output_path_for_action(
            active_store,
            business,
            rel,
            action=str(operation.get("action") or ""),
        )
        actual_content = file_path.read_text(encoding="utf-8", errors="replace")
        verification = {
            "path": rel,
            "verified": actual_content == expected_content,
            "expected_sha256": hashlib.sha256(expected_content.encode("utf-8")).hexdigest(),
            "actual_sha256": hashlib.sha256(actual_content.encode("utf-8")).hexdigest(),
        }
        if verification["verified"]:
            return tool_result({**result, "success": True, "verification": verification})
        return tool_error(
            f"postcondition verification failed for {rel}",
            success=False,
            business=business,
            path=rel,
            verification=verification,
            result=result,
        )
    except Exception as exc:
        return tool_error(str(exc), success=False)


def _refuse_starter_owned_product_write(rel: str) -> None:
    """Fail closed on durable edits that can never persist: scaffold-owned product files.

    Every file in _STARTER_OWNED_REFRESH_FILES under the product/site runtime-UI surface is
    force-rewritten from the bundled scaffold on every kit materialize — before each product
    worker run, inside each publish build, and inside this very commit's own surface-projection
    refresh — so a durable write here silently self-reverts within its commit, no-ops the
    revision, and then fails its sha postcondition byte-identically on every retry (observed
    live as an unwinnable repair loop that exhausted two full CEO turns). Refusing up front
    converts that silent lie into a routable error naming the viable repair. Handler-level on
    purpose: internal platform writers of these files (e.g. the Search Console index.html
    injection) still go through the store's apply path unimpeded."""
    normalized = str(rel or "").strip().strip("/")
    prefix = "product/site/"
    if not normalized.startswith(prefix):
        return
    if normalized[len(prefix):] in _STARTER_OWNED_REFRESH_FILES:
        raise TakyonError(
            f"{normalized} is scaffold-owned and force-rewritten from the bundled scaffold on every "
            "product build/kit materialize — edits to it can never persist. Make the minimal repair in "
            "worker-owned source instead: fix the importing screen (src/screens/*, src/components/*) or "
            "add the helper to a NEW worker-owned module under src/lib/ with a different filename."
        )


def handle_business_write_file(args: dict, **_: Any) -> str:
    _refuse_product_file_edit_on_autonomous_wake(args.get("path"))
    business = _resolved_business_slug(args, required=True)
    store = _store()
    mode = str(args.get("mode") or "replace").strip().lower()
    content = str(args.get("content") or "")
    rel, file_path = _resolved_business_output_path_for_action(
        store,
        business,
        str(args.get("path") or ""),
        action="artifact.write",
    )
    _refuse_starter_owned_product_write(rel)
    previous_content = (
        file_path.read_text(encoding="utf-8", errors="replace")
        if file_path.exists()
        else ""
    )
    expected_content = previous_content + content if mode == "append" and file_path.exists() else content
    operation = {
        "action": "artifact.write",
        "business": args.get("business"),
        "path": args.get("path"),
        "content": content,
        "mode": mode or "replace",
        "requires_api": args.get("requires_api") or [],
        "requires_env": args.get("requires_env") or [],
    }
    return _verified_business_file_mutation_response(
        args=args,
        operation=operation,
        expected_content=expected_content,
        store=store,
    )


def handle_business_patch_file(args: dict, **_: Any) -> str:
    _refuse_product_file_edit_on_autonomous_wake(args.get("path"))
    business = _resolved_business_slug(args, required=True)
    store = _store()
    rel, file_path = _resolved_business_output_path_for_action(
        store,
        business,
        str(args.get("path") or ""),
        action="artifact.patch",
    )
    _refuse_starter_owned_product_write(rel)
    if not file_path.exists():
        raise TakyonError(f"cannot patch missing file: {args.get('path')}")
    old = str(args.get("old") or "")
    if not old:
        raise TakyonError("artifact.patch requires non-empty old text")
    previous_content = file_path.read_text(encoding="utf-8", errors="replace")
    if old not in previous_content:
        raise TakyonError("artifact.patch old text not found")
    new = str(args.get("new") or "")
    expected_content = previous_content.replace(old, new, 1)
    operation = {
        "action": "artifact.patch",
        "business": args.get("business"),
        "path": args.get("path"),
        "old": old,
        "new": new,
    }
    return _verified_business_file_mutation_response(
        args=args,
        operation=operation,
        expected_content=expected_content,
        store=store,
    )


