def handle_business_publish_test_outreach(args: dict, **_: Any) -> str:
    store = _store()
    business = _resolved_business_slug(args, required=True)
    body = _normalize_outreach_body(args.get("body") or args.get("content"))
    if not body:
        raise TakyonError("body is required")
    with store._connect() as conn:
        canonical_product_url = _canonical_product_url(store, conn, business)
    body, canonical_replacements = _canonicalize_business_product_links(
        body,
        business=business,
        canonical_url=canonical_product_url,
    )
    metadata = args.get("metadata") if isinstance(args.get("metadata"), dict) else {}
    metadata = {
        **metadata,
        "canonical_product_url": canonical_product_url,
    }
    if canonical_replacements:
        metadata["canonicalized_product_links"] = canonical_replacements
    operation = {
        "action": "outreach.local_publish",
        "business": business,
        "channel": args.get("channel") or args.get("provider"),
        "provider": args.get("provider"),
        "target": args.get("target") or args.get("recipient"),
        "recipient": args.get("recipient"),
        "subject": args.get("subject") or args.get("title"),
        "body": body,
        "destination_url": args.get("destination_url") or args.get("intended_destination_url"),
        "destination_label": args.get("destination_label"),
        "thread_external_id": args.get("thread_external_id"),
        "metadata": metadata,
    }
    return _commit_tool(args, operation)


_X_IMAGE_MEDIA_SUFFIXES = frozenset({".png", ".jpg", ".jpeg", ".gif", ".webp"})
_X_VIDEO_MEDIA_SUFFIXES = frozenset({".mp4"})


def _validated_x_media_paths(store: "TakyonStore", business: str, raw_media_paths: Any) -> list[str]:
    validated: list[str] = []
    image_count = 0
    video_count = 0
    for raw in _as_list(raw_media_paths):
        rel = _safe_relpath(str(raw or ""), field="media_paths").as_posix()
        abs_path = store._resolve_business_file(business, rel)
        if not abs_path.is_file():
            raise TakyonError(f"media file not found: {rel}")
        suffix = abs_path.suffix.lower()
        if suffix in _X_IMAGE_MEDIA_SUFFIXES:
            image_count += 1
        elif suffix in _X_VIDEO_MEDIA_SUFFIXES:
            video_count += 1
        else:
            raise TakyonError(
                f"unsupported X media file type for {rel}; only png, jpg, jpeg, gif, webp, and mp4 are supported"
            )
        validated.append(rel)
    if image_count and video_count:
        raise TakyonError("X media attachments cannot mix images and video")
    if image_count > 4:
        raise TakyonError("X media attachments support at most 4 images")
    if video_count > 1:
        raise TakyonError("X media attachments support at most 1 video")
    return validated


def handle_business_x_publish_outreach(args: dict, **_: Any) -> str:
    try:
        x_args = dict(args)
        channel = str(x_args.get("channel") or "").strip()
        provider = str(x_args.get("provider") or "").strip()
        if channel and not _is_x_provider_name(channel):
            raise TakyonError("business_x_publish_outreach only supports the X channel")
        if provider and not _is_x_provider_name(provider):
            raise TakyonError("business_x_publish_outreach only supports the X provider")
        x_args["channel"] = "x"
        x_args["provider"] = "x"
        return _handle_live_business_x_publish_outreach(x_args)
    except Exception as exc:
        return tool_error(str(exc), success=False)


def _handle_live_business_x_publish_outreach(args: dict) -> str:
    try:
        store = _store()
        business = _resolved_business_slug(args, required=True)
        # Launch-post dedupe: a ceo_bootstrap turn publishes EXACTLY ONE launch X post. A
        # re-enqueued bootstrap (retry after a crash, or a spill to the fallback worker) would
        # otherwise post a SECOND launch tweet (walkloop double-post, 2026-07-09). If a successful X
        # post receipt already exists for this business, the launch moment has passed — skip
        # re-posting and return the existing post. Steady-state wakes (ceo_wake) and explicit chat
        # posts carry no bootstrap marker, so they are unaffected and post freely.
        if _active_operator_task_kind() == "ceo_bootstrap":
            _existing_x = _x_outreach_receipt_candidates(store, business)
            if _existing_x:
                _top = _existing_x[0]
                return tool_result(
                    {
                        "success": True,
                        "action": "business_x_publish_outreach",
                        "business": business,
                        "deduped": True,
                        "post_id": _top.get("post_id"),
                        "post_url": _top.get("post_url"),
                        "receipt_path": _top.get("receipt_rel"),
                        "note": (
                            "A launch X post already exists for this business; skipped re-posting on "
                            "this bootstrap re-run (one launch post per business)."
                        ),
                    }
                )
        body = _normalize_outreach_body(args.get("body") or args.get("content"))
        if not body:
            raise TakyonError("body is required")
        media_paths = _validated_x_media_paths(store, business, args.get("media_paths"))
        with store._connect() as conn:
            business_row = store._ensure_business(conn, business)
            business_mode = _effective_business_mode(business_row.get("mode"))
            canonical_product_url = _canonical_product_url(store, conn, business)
            canonical_product_url = _canonical_product_url(store, conn, business)

        body, canonical_replacements = _canonicalize_business_product_links(
            body,
            business=business,
            canonical_url=canonical_product_url,
        )
        metadata = args.get("metadata") if isinstance(args.get("metadata"), dict) else {}
        metadata = {
            **metadata,
            "canonical_product_url": canonical_product_url,
        }
        if canonical_replacements:
            metadata["canonicalized_product_links"] = canonical_replacements
        if media_paths:
            metadata["media_paths"] = list(media_paths)

        channel = str(args.get("channel") or args.get("provider") or "outreach").strip()
        provider = str(args.get("provider") or channel).strip()
        target = args.get("target") or args.get("recipient")
        is_x_outreach = _is_x_provider_name(provider) or _is_x_provider_name(channel)
        destination_url = _outreach_destination_url(
            channel=channel,
            provider=provider,
            target=target,
            destination_url=args.get("destination_url") or args.get("intended_destination_url"),
            metadata=metadata,
        )
        destination_label = str(args.get("destination_label") or metadata.get("destination_label") or "").strip()
        if is_x_outreach and not destination_url:
            destination_url = _normalize_destination_url(canonical_product_url)
        if is_x_outreach and destination_url:
            destination_url = _channel_tracked_link(
                destination_url,
                source="x",
                medium="social",
                campaign_key=business,
            )
        canonical_args = dict(args)
        canonical_args["business"] = business
        canonical_args["body"] = body
        canonical_args["channel"] = channel
        canonical_args["provider"] = provider
        canonical_args["destination_url"] = destination_url
        canonical_args["destination_label"] = destination_label
        canonical_args["metadata"] = metadata
        canonical_args["media_paths"] = list(media_paths)
        if business_mode == "test":
            return handle_business_publish_test_outreach(canonical_args)
        if not is_x_outreach:
            raise TakyonError(
                "business_x_publish_outreach only supports X; use takyon-x for X posts, "
                "business_reddit_ad_launch for Reddit ads, or a dedicated channel-owned rail for other live providers"
            )
        requires_api = [
            str(item).strip()
            for item in _as_list(args.get("requires_api"))
            if str(item).strip()
        ]
        requires_env = [
            str(item).strip()
            for item in _as_list(args.get("requires_env"))
            if str(item).strip()
        ]
        if provider:
            requires_api.append(provider)
        if not requires_api and not requires_env:
            raise TakyonError("live outreach publish requires provider, requires_api, or requires_env")

        payload = {
            "channel": channel,
            "provider": provider,
            "target": target,
            "recipient": args.get("recipient"),
            "subject": args.get("subject") or args.get("title"),
            "body": body,
            "destination_url": destination_url,
            "destination_label": destination_label,
            "thread_external_id": args.get("thread_external_id"),
            "metadata": metadata,
            "media_paths": list(media_paths),
            "requested_external_side_effect": "publish_outreach",
        }
        if is_x_outreach:
            credit_gate = _creative_credit_preflight_gate(
                business,
                action="x_publish_outreach",
                budget_bucket="x",
                metadata=metadata,
            )
            if not credit_gate.get("success"):
                return tool_result(
                    {
                        "success": False,
                        "blocked": True,
                        "action": "business_x_publish_outreach",
                        "business": business,
                        "channel": channel,
                        "provider": provider,
                        "status": credit_gate.get("status"),
                        "requested_credits": credit_gate.get("requested_credits"),
                        "available_credits": credit_gate.get("available_credits"),
                        "balance_credits": credit_gate.get("balance_credits"),
                        "reserved_credits": credit_gate.get("reserved_credits"),
                        "budget_bucket": credit_gate.get("budget_bucket"),
                        "channel_budget": credit_gate.get("channel_budget"),
                        "error": credit_gate.get("error") or "x publish blocked on creative credits",
                        "note": (
                            "Live X publication was not enqueued because the business creative-credit "
                            "gate cannot cover the fixed X post cost yet."
                        ),
                    }
                )
        operation = {
            "action": "job.enqueue",
            "business": business,
            "scope": args.get("scope") or f"business:{business}",
            "kind": "x.publish_outreach",
            "status": args.get("status") or "pending",
            "payload": payload,
            "requires_api": sorted(set(requires_api)),
            "requires_env": sorted(set(requires_env)),
        }
        operation["worker_queue"] = True
        operation["worker_max_attempts"] = 1
        # 120s wait, NOT 45s: a live X publish measures ~47-48s end-to-end (credit reserve +
        # segment posts + link reply + commit), so a 45s wait timed out moments before success on
        # EVERY call and returned the "re-call to re-attach" note — and a caller that re-drafted
        # with a fresh idempotency_key instead of replaying published a near-duplicate post per
        # retry (observed: four duplicate launch posts per bootstrap). The wait must comfortably
        # exceed the tool's own p99 so the first call returns the real receipt.
        return _run_worker_backed_business_job_and_wait(
            canonical_args,
            operation,
            tool_name="business_x_publish_outreach",
            wait_seconds=120.0,
            scope=operation["scope"],
        )
    except Exception as exc:
        return tool_error(str(exc), success=False)


def _x_outreach_receipt_candidates(store: "TakyonStore", business: str) -> list[dict[str, Any]]:
    receipts_dir = store._resolve_business_file(business, "metrics/receipts/outreach")
    business_root = store._business_root(business)
    if not receipts_dir.exists() or not receipts_dir.is_dir():
        return []
    candidates: list[tuple[float, dict[str, Any]]] = []
    for path in receipts_dir.glob("*.json"):
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(payload, dict):
            continue
        provider = str(payload.get("provider") or "").strip().lower()
        channel = str(payload.get("channel") or "").strip().lower()
        post_id = str(payload.get("post_id") or "").strip()
        if not post_id or not (_is_x_provider_name(provider) or _is_x_provider_name(channel)):
            continue
        try:
            rel = path.relative_to(business_root).as_posix()
        except Exception:
            continue
        try:
            sort_key = path.stat().st_mtime
        except OSError:
            sort_key = 0.0
        candidates.append(
            (
                sort_key,
                {
                    "receipt_rel": rel,
                    "receipt_abs": path,
                    "receipt": payload,
                    "post_id": post_id,
                    "post_url": str(payload.get("post_url") or "").strip(),
                    "published_at": str(payload.get("published_at") or "").strip(),
                },
            )
        )
    candidates.sort(key=lambda item: item[0], reverse=True)
    return [item[1] for item in candidates]


def _x_load_outreach_receipt(store: "TakyonStore", business: str, args: Mapping[str, Any]) -> dict[str, Any]:
    receipt_raw = str(args.get("receipt_path") or "").strip()
    requested_post_id = str(args.get("post_id") or "").strip()
    candidates = _x_outreach_receipt_candidates(store, business)
    if receipt_raw:
        receipt_rel = _safe_relpath(receipt_raw, field="receipt_path").as_posix()
        if not receipt_rel.startswith("metrics/receipts/outreach/"):
            raise TakyonError("receipt_path must point to metrics/receipts/outreach/<...>.json")
        for item in candidates:
            if item["receipt_rel"] == receipt_rel:
                return item
        raise TakyonError(f"X outreach receipt not found at {receipt_rel}")
    if requested_post_id:
        for item in candidates:
            if item["post_id"] == requested_post_id:
                return item
        raise TakyonError(f"no X outreach receipt found for post_id {requested_post_id}")
    if candidates:
        return candidates[0]
    raise TakyonError("no X outreach receipt exists for this business yet")


def _x_metrics_summary_rel() -> str:
    return "metrics/x/summary.json"


def _x_write_summary(store: "TakyonStore", business: str) -> tuple[str, dict[str, Any]]:
    posts_dir = store._resolve_business_file(business, "metrics/x/posts")
    snapshots: list[dict[str, Any]] = []
    if posts_dir.exists() and posts_dir.is_dir():
        for path in sorted(posts_dir.glob("*.json")):
            try:
                payload = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                continue
            if isinstance(payload, dict):
                snapshots.append(payload)
    summary = _x_aggregate_post_snapshots(snapshots)
    summary_rel = _x_metrics_summary_rel()
    _atomic_write_text(
        store._resolve_business_file(business, summary_rel),
        json.dumps(summary, ensure_ascii=False, indent=2) + "\n",
    )
    return summary_rel, summary


def handle_business_x_metrics_sync(args: dict, **_: Any) -> str:
    try:
        store = _store()
        business = _resolved_business_slug(args, required=True)
        idempotency_key = str(args.get("idempotency_key") or "").strip()
        if not idempotency_key:
            raise TakyonError("idempotency_key is required")

        receipt_match = _x_load_outreach_receipt(store, business, args)
        receipt = receipt_match["receipt"]
        post_id = str(receipt_match["post_id"] or "").strip()
        if not post_id:
            raise TakyonError("resolved X outreach receipt does not contain a post_id")

        metrics_dir_rel = "metrics/x"
        sync_key = _file_slug(f"{post_id}-{idempotency_key}", "x-metrics")
        sync_rel = f"{metrics_dir_rel}/syncs/{sync_key}.json"
        sync_abs = store._resolve_business_file(business, sync_rel)
        prior = _read_existing_receipt(sync_abs, idempotency_key)
        if prior is not None:
            return tool_result(
                {
                    "success": bool(prior.get("success", True)),
                    "action": "business_x_metrics_sync",
                    "business": business,
                    "idempotent": True,
                    "post_id": post_id,
                    "receipt": sync_rel,
                    "metrics_path": f"{metrics_dir_rel}/insights.jsonl",
                    "post_metrics_path": f"{metrics_dir_rel}/posts/{post_id}.json",
                    "summary_path": _x_metrics_summary_rel(),
                    "status": prior.get("status"),
                    "value": prior,
                }
            )

        tweet = _x_metrics_lookup(post_id, published_at=receipt_match.get("published_at"))
        synced_at = _now()
        post_rel = f"{metrics_dir_rel}/posts/{post_id}.json"
        snapshot = {
            "business": business,
            "post_id": post_id,
            "post_url": str(receipt_match.get("post_url") or receipt.get("post_url") or "").strip(),
            "published_at": str(receipt_match.get("published_at") or receipt.get("published_at") or "").strip(),
            "source_receipt": str(receipt_match.get("receipt_rel") or "").strip(),
            "synced_at": synced_at,
            "tweet": tweet,
            "public_metrics": dict(tweet.get("public_metrics") or {}) if isinstance(tweet.get("public_metrics"), Mapping) else {},
            "non_public_metrics": dict(tweet.get("non_public_metrics") or {}) if isinstance(tweet.get("non_public_metrics"), Mapping) else {},
            "organic_metrics": dict(tweet.get("organic_metrics") or {}) if isinstance(tweet.get("organic_metrics"), Mapping) else {},
        }
        sync_receipt = {
            "idempotency_key": idempotency_key,
            "business": business,
            "post_id": post_id,
            "post_url": snapshot["post_url"],
            "source_receipt": snapshot["source_receipt"],
            "published_at": snapshot["published_at"],
            "synced_at": synced_at,
            "success": True,
            "status": "synced",
            "tweet": tweet,
            "public_metrics": snapshot["public_metrics"],
            "non_public_metrics": snapshot["non_public_metrics"],
            "organic_metrics": snapshot["organic_metrics"],
        }
        _atomic_write_text(
            store._resolve_business_file(business, post_rel),
            json.dumps(snapshot, ensure_ascii=False, indent=2) + "\n",
        )
        _atomic_write_text(sync_abs, json.dumps(sync_receipt, ensure_ascii=False, indent=2) + "\n")
        _append_jsonl(
            store._resolve_business_file(business, f"{metrics_dir_rel}/insights.jsonl"),
            {**sync_receipt, "receipt": sync_rel, "post_metrics_path": post_rel},
        )
        summary_rel, summary = _x_write_summary(store, business)
        store.commit(
            scope=f"business:{business}/metrics:x/{post_id}",
            operations=[
                {
                    "action": "event.record",
                    "business": business,
                    "event_type": "x.metrics_sync",
                    "payload": {
                        **sync_receipt,
                        "metrics_dir": metrics_dir_rel,
                        "receipt": sync_rel,
                        "post_metrics_path": post_rel,
                        "summary_path": summary_rel,
                    },
                }
            ],
            idempotency_key=idempotency_key,
            reason=args.get("reason") or "record x metrics sync",
            actor=args.get("actor") or "agent",
        )
        return tool_result(
            {
                "success": True,
                "action": "business_x_metrics_sync",
                "business": business,
                "status": "synced",
                "post_id": post_id,
                "post_url": snapshot["post_url"],
                "receipt": sync_rel,
                "metrics_path": f"{metrics_dir_rel}/insights.jsonl",
                "post_metrics_path": post_rel,
                "summary_path": summary_rel,
                "totals": summary.get("totals") if isinstance(summary, dict) else {},
                "value": sync_receipt,
            }
        )
    except Exception as exc:
        return tool_error(str(exc), success=False)


def _composio_result_items_and_meta(payload: Any) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    current = payload
    for _ in range(4):
        if isinstance(current, Mapping):
            data = current.get("data")
            if isinstance(data, list):
                return [dict(item) for item in data if isinstance(item, Mapping)], (
                    dict(current.get("meta")) if isinstance(current.get("meta"), Mapping) else {}
                )
            items = current.get("items")
            if isinstance(items, list):
                return [dict(item) for item in items if isinstance(item, Mapping)], (
                    dict(current.get("meta")) if isinstance(current.get("meta"), Mapping) else {}
                )
            if data is not None and data is not current:
                current = data
                continue
        break
    if isinstance(current, list):
        return [dict(item) for item in current if isinstance(item, Mapping)], {}
    if isinstance(current, Mapping):
        items = current.get("items")
        if isinstance(items, list):
            return [dict(item) for item in items if isinstance(item, Mapping)], (
                dict(current.get("meta")) if isinstance(current.get("meta"), Mapping) else {}
            )
    return [], {}


def handle_business_x_search(args: dict, **_: Any) -> str:
    try:
        store = _store()
        business = _resolved_business_slug(args, required=True)
        query = str(args.get("query") or "").strip()
        if not query:
            raise TakyonError("query is required")
        idempotency_key = str(args.get("idempotency_key") or "").strip()
        if not idempotency_key:
            raise TakyonError("idempotency_key is required")
        max_results = _clamp_int(args.get("max_results"), default=10, minimum=10, maximum=100)
        since_id = str(args.get("since_id") or "").strip()
        snapshot_key = _file_slug(idempotency_key, "x-search")
        snapshot_rel = f"metrics/x/search/{snapshot_key}.json"
        snapshot_abs = store._resolve_business_file(business, snapshot_rel)
        prior = _read_existing_receipt(snapshot_abs, idempotency_key)
        if prior is not None:
            return tool_result(
                {
                    "success": bool(prior.get("success", True)),
                    "action": "business_x_search",
                    "business": business,
                    "idempotent": True,
                    "query": query,
                    "snapshot_path": snapshot_rel,
                    "status": prior.get("status") or "synced",
                    "tweets": prior.get("tweets") or [],
                    "meta": prior.get("meta") or {},
                    "value": prior,
                }
            )

        search_arguments: dict[str, Any] = {
            "query": query,
            # [composio-schema] Confirm TWITTER_RECENT_SEARCH uses max_results.
            "max_results": max_results,
            "tweet_fields": ["created_at", "public_metrics", "author_id"],
        }
        if since_id:
            # [composio-schema] Confirm TWITTER_RECENT_SEARCH uses since_id.
            search_arguments["since_id"] = since_id
        payload = composio_distribution.twitter_execute_tool(
            "TWITTER_RECENT_SEARCH",
            arguments=search_arguments,
            timeout=60.0,
        )
        tweets, meta = _composio_result_items_and_meta(payload)
        snapshot = {
            "idempotency_key": idempotency_key,
            "success": True,
            "status": "synced",
            "business": business,
            "query": query,
            "requested_max_results": max_results,
            "since_id": since_id or None,
            "result_count": len(tweets),
            "newest_id": str(meta.get("newest_id") or "").strip(),
            "oldest_id": str(meta.get("oldest_id") or "").strip(),
            "meta": meta,
            "tweets": tweets,
            "synced_at": _now(),
        }
        _atomic_write_text(snapshot_abs, json.dumps(snapshot, ensure_ascii=False, indent=2) + "\n")
        store.commit(
            scope=f"business:{business}/metrics:x/search",
            operations=[
                {
                    "action": "event.record",
                    "business": business,
                    "event_type": "x.search",
                    "payload": {
                        "query": query,
                        "requested_max_results": max_results,
                        "result_count": len(tweets),
                        "snapshot_path": snapshot_rel,
                    },
                }
            ],
            idempotency_key=idempotency_key,
            reason=args.get("reason") or "record x search snapshot",
            actor=args.get("actor") or "agent",
        )
        return tool_result(
            {
                "success": True,
                "action": "business_x_search",
                "business": business,
                "status": "synced",
                "query": query,
                "snapshot_path": snapshot_rel,
                "result_count": len(tweets),
                "newest_id": snapshot["newest_id"],
                "oldest_id": snapshot["oldest_id"],
                "tweets": tweets,
                "meta": meta,
                "value": snapshot,
            }
        )
    except Exception as exc:
        return tool_error(str(exc), success=False)


def _creative_credit_backend():
    try:
        from . import safebox as credits_backend
    except Exception:
        from plugins.takyon import safebox as credits_backend
    return credits_backend


def _business_ad_spend_backend():
    try:
        from . import business_ad_spend as spend_backend
    except Exception:
        from plugins.takyon import business_ad_spend as spend_backend
    return spend_backend


def _assert_ad_set_budget_authorized(
    *,
    channel: str,
    business: str,
    slug: str,
    target_id: str,
    daily_budget_cents: int,
    safety_cap_cents: int = 0,
) -> None:
    """Gateway-reachable budget gate (closes the launch-only cap bypass).

    The runtime ad-control gateway (`creative_gateway.py` meta-control / reddit-control
    `set_budget`) is reachable independently of the credit-checked business tool, so the cap must
    also be enforced HERE — at the layer that actually mutates live spend. Requires the funded
    ad-spend policy for (business, channel, slug) to exist, the target object to be the one that
    policy launched (closes the cross-business IDOR), and the daily budget to fit the per-channel
    safety cap + the reserved-credit cap. Reuses the same `enforce_daily_budget` the tool uses, so
    there is one cap implementation. Raises `TakyonError` on any violation (fail-closed).
    """
    backend = _business_ad_spend_backend()
    business = str(business or "").strip()
    slug = str(slug or "").strip()
    if not business or not slug:
        raise TakyonError("business and slug are required to change a live ad budget")
    try:
        policy = _load_ad_spend_policy(business, channel=channel, slug=slug)
    except backend.BusinessAdSpendPolicyNotFound:
        raise TakyonError(f"no funded {channel} campaign for business={business!r} slug={slug!r}")
    known = {str(policy.provider_group_id or ""), str(policy.provider_campaign_id or "")}
    known.discard("")
    if known and str(target_id or "") and str(target_id) not in known:
        raise TakyonError("target object does not belong to this business's funded campaign")
    try:
        backend.enforce_daily_budget(
            policy,
            daily_budget_cents=int(daily_budget_cents),
            now=datetime.now(timezone.utc),
            safety_cap_cents=int(safety_cap_cents),
        )
    except backend.AdSpendCapExceeded as exc:
        raise TakyonError(str(exc))


def _operator_creative_gate_disabled() -> bool:
    """Operator god-mode creative-credit bypass — **ON BY DEFAULT** (operator ruling 2026-07-09;
    client half — the authoritative half is ``safebox_app._operator_creative_gate_disabled``). The
    operator plane's client-side credit refusals (balance pre-check, channel-budget check,
    local-ledger insufficient) stop refusing; local shortfalls are auto-granted as ledgered
    bypass-tagged top-ups (local-authority planes only), and remote refusal is handled by the
    safebox authority under the same default. Metering is unchanged — every action still reserves
    and settles with real cost metadata. Set ``TAKYON_OPERATOR_CREATIVE_GATE_DISABLED=0`` to restore
    hard gating. Subusers are untouched: this helper only runs inside operator-plane ``business_*``
    tools."""
    return str(os.getenv("TAKYON_OPERATOR_CREATIVE_GATE_DISABLED", "1")).strip().lower() not in {
        "0", "false", "no", "off",
    }


def _creative_credit_unit_cost(action: str) -> int:
    env_name = _CREATIVE_CREDIT_COST_ENVS.get(action, "")
    raw = os.getenv(env_name or "")
    try:
        value = int(raw) if raw not in (None, "") else _CREATIVE_CREDIT_COST_DEFAULTS[action]
    except (TypeError, ValueError, KeyError):
        value = _CREATIVE_CREDIT_COST_DEFAULTS.get(action, 0)
    return max(0, value)


def _creative_credit_total_cost(action: str, *, units: int = 1) -> int:
    return _creative_credit_unit_cost(action) * max(1, int(units or 1))


def _creative_credit_action_audience(action: Any) -> str:
    return _CREATIVE_CREDIT_ACTION_AUDIENCES.get(str(action or "").strip(), "")


def _creative_credit_uses_safebox_gate(action: Any) -> bool:
    if not _creative_credit_action_audience(action):
        return False
    try:
        return bool(safebox._use_remote_authority())
    except Exception:
        return False


def _business_owner_user_id_for_creative(
    store: "TakyonStore",
    conn: sqlite3.Connection,
    business: str,
) -> str:
    row = store._ensure_business(conn, business)
    owner_user_id = str(row.get("owner_user_id") or "").strip()
    if not owner_user_id:
        raise TakyonError(f"business:{business} has no owner_user_id; refusing creative credit gate")
    return owner_user_id


def _creative_credit_balances_and_budget_snapshot(
    store: "TakyonStore",
    business: str,
) -> tuple[Any, dict[str, Any]]:
    credits_backend = _creative_credit_backend()
    with store._connect() as conn:
        balances = credits_backend.get_business_credit_balances(conn, business)
        budget_snapshot = _creative_credit_budget_snapshot_from_conn(
            store,
            conn,
            business,
            balances=balances,
        )
    return balances, budget_snapshot


# Brand-logo provider/model — DERIVED from the CreativeProviderSpec registry so the
# receipt stamps the SAME model the safebox actually renders. Previously this hardcoded
# 'gemini-2.5-flash-image' while creative_gateway._GEMINI_IMAGE_MODEL rendered
# 'gemini-3.1-flash-image' (plan §6b item 2's live truthfulness bug: the receipt was
# factually wrong; prices coincided so it was silent, and it would mis-cost on the next
# price change). Binding both to the spec makes receipt-model == priced-model ==
# rendered-model by construction. ``pricing_key`` is (usage_pricing vendor='google',
# model); ``provider`` on the receipt is the same vendor name for the priced cost.
from .creative_provider_registry import _GEMINI_LOGO_IMAGE as _LOGO_SPEC

_LOGO_IMAGE_PROVIDER = _LOGO_SPEC.pricing_provider  # 'google' (usage_pricing vendor)
_LOGO_IMAGE_MODEL = _LOGO_SPEC.model  # 'gemini-3.1-flash-image' (== the rendered model)


def _logo_provider_cost_usd() -> float:
    """Exact per-image provider cost for the brand-logo model.

    Resolved from the canonical pricing table (agent.usage_pricing) via the creative
    provider spec's ``pricing_key`` — the ONE price SSOT. An unpriced model is refused
    so the receipt can never claim a fabricated cost and no unpriced paid model is ever
    callable (GOAL_RULES §4 / CLAUDE.md billing rules).
    """
    from .creative_provider_registry import (
        CreativeProviderUnpriced,
        resolve_priced_model_cost_usd,
    )

    try:
        return resolve_priced_model_cost_usd(_LOGO_SPEC)
    except CreativeProviderUnpriced as exc:
        raise TakyonError(str(exc)) from exc


# A UGC video ad is two provider calls: one reference still (gpt-image-2) and the
# rendered video (Kling v3 Pro image-to-video, billed per second). Both prices live
# in the canonical table (agent.usage_pricing) — never a second table in the skill.
_UGC_IMAGE_PROVIDER = "openai"
_UGC_IMAGE_MODEL = "gpt-image-2"
_UGC_VIDEO_PROVIDER = "fal"
_UGC_VIDEO_MODEL = "kling-video/v3/pro/image-to-video"


def _ugc_provider_cost_usd(seconds: Any) -> float:
    """Exact provider cost for a UGC video ad: one reference still (gpt-image-2)
    plus the rendered video seconds (Kling v3 Pro, per-second).

    Resolved from the canonical pricing table (agent.usage_pricing); an unpriced
    model is refused so the receipt can never claim a fabricated cost — the single
    source of truth for UGC provider cost, no second hardcoded table in the skill
    (GOAL_RULES §4 / CLAUDE.md exact-cost rule).
    """
    from agent import usage_pricing

    img = usage_pricing._OFFICIAL_DOCS_PRICING.get((_UGC_IMAGE_PROVIDER, _UGC_IMAGE_MODEL))
    vid = usage_pricing._OFFICIAL_DOCS_PRICING.get((_UGC_VIDEO_PROVIDER, _UGC_VIDEO_MODEL))
    img_cost = getattr(img, "request_cost", None) if img is not None else None
    vid_per_second = getattr(vid, "request_cost", None) if vid is not None else None
    if img_cost is None or vid_per_second is None:
        raise TakyonError(
            "ugc video ad provider models are not priced in usage_pricing "
            f"({_UGC_IMAGE_PROVIDER}/{_UGC_IMAGE_MODEL}, {_UGC_VIDEO_PROVIDER}/{_UGC_VIDEO_MODEL}); "
            "receipt refused (no unpriced provider spend)"
        )
    try:
        secs = float(seconds or 0.0)
    except (TypeError, ValueError):
        secs = 0.0
    if secs < 0:
        secs = 0.0
    return round(float(img_cost) + secs * float(vid_per_second), 6)


