# Wake pulse surfaces active ad campaigns so the CEO sees paid bets whose delivery insights
# have gone stale. Ad spend/insights only enter Takyon on an explicit
# business_<channel>_ad_insights_sync (never automatically), so a live campaign that hasn't
# been synced within this window is flagged needs_sync. Overridable per-deployment.
def _ad_insights_stale_seconds() -> int:
    raw = os.environ.get("TAKYON_AD_INSIGHTS_STALE_SECONDS")
    try:
        value = int(raw) if raw not in (None, "") else 43200  # 12h
    except (TypeError, ValueError):
        value = 43200
    return max(60, value)


# Non-terminal ad-spend policy statuses ("completed" is settled/terminal).
_PULSE_AD_CAMPAIGN_STATUSES = ("reserved", "created_paused", "active", "paused")
# Statuses where delivery is (or was) live, so stale insights are worth re-syncing.
_PULSE_AD_LIVE_STATUSES = frozenset({"active", "paused"})


def _humanize_age_seconds(seconds: float) -> str:
    seconds = int(max(0, seconds))
    days, rem = divmod(seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes = rem // 60
    if days:
        return f"{days}d {hours}h ago"
    if hours:
        return f"{hours}h {minutes}m ago"
    if minutes:
        return f"{minutes}m ago"
    return "just now"


# App Store account-health cache: probing Apple on every pulse would hammer the ASC API, so the
# result is memoized process-wide for ~6h (readmodular §4.1). Time is passed in (Date.now is banned
# in some contexts; here we use monotonic-ish wall time via the caller's now_dt epoch).
_APPSTORE_HEALTH_CACHE: dict[str, Any] = {"checked_epoch": 0, "receipt": None}
_APPSTORE_HEALTH_TTL_SECONDS = 6 * 3600


def _platform_account_health(archetype: str, now_epoch: float) -> dict[str, Any] | None:
    """Best-effort Apple developer-account health for the wake pulse — ONLY for mobile_app businesses
    (Apple-specific). Calls the safebox account-health route (the key never leaves the safebox),
    memoized ~6h so pulse never hammers Apple. Never raises: returns None on any error / non-mobile
    archetype / unconfigured, so the pulse is unaffected ("never break the wake"). A non-'ok' state
    (esp. agreement_blocked) is the CEO's signal that store submissions are frozen account-wide."""
    try:
        if _archetype_leaf().normalize_archetype(archetype, allow_empty=True) != _archetype_leaf().MOBILE_APP:
            return None
    except Exception:
        return None
    cached = _APPSTORE_HEALTH_CACHE.get("receipt")
    if cached is not None and (now_epoch - float(_APPSTORE_HEALTH_CACHE.get("checked_epoch") or 0)) < _APPSTORE_HEALTH_TTL_SECONDS:
        return cached
    try:
        try:
            from . import safebox as _sb
        except ImportError:  # pragma: no cover - alternate load path
            from plugins.takyon import safebox as _sb
        receipt = _sb.store_asc_account_health()
    except Exception:
        return cached  # keep the last good reading rather than flapping; None if never succeeded
    if isinstance(receipt, dict) and receipt.get("state"):
        _APPSTORE_HEALTH_CACHE["receipt"] = receipt
        _APPSTORE_HEALTH_CACHE["checked_epoch"] = now_epoch
        return receipt
    return cached


def _pulse_active_ad_campaigns(slug: str, now_dt: datetime) -> list[dict[str, Any]]:
    """Best-effort: surface a business's non-terminal ad campaigns + insights staleness for the
    wake pulse, so the CEO can re-sync a live campaign before judging it. Never raises — returns
    [] on any error (e.g. the ad-spend policy table is Postgres-only, absent under SQLite)."""
    try:
        policies = _list_ad_spend_policies(slug, statuses=_PULSE_AD_CAMPAIGN_STATUSES)
    except Exception:
        return []
    stale_seconds = _ad_insights_stale_seconds()
    out: list[dict[str, Any]] = []
    for policy in policies or []:
        try:
            metadata = policy.metadata if isinstance(policy.metadata, dict) else {}
            synced_raw = metadata.get("insights_synced_at")
            synced_dt = _parse_iso_datetime(synced_raw) if synced_raw else None
            if synced_dt is not None:
                age_seconds = (now_dt - synced_dt).total_seconds()
                synced_ago = _humanize_age_seconds(age_seconds)
            else:
                age_seconds = None
                synced_ago = "never synced"
            is_live = str(policy.status or "") in _PULSE_AD_LIVE_STATUSES
            needs_sync = is_live and (age_seconds is None or age_seconds > stale_seconds)
            spend_cents = int(policy.last_synced_spend_cents or 0)
            out.append({
                "channel": policy.channel,
                "slug": policy.slug,
                "status": policy.status,
                "provider_campaign_id": policy.provider_campaign_id,
                "daily_budget_usd": round(int(policy.daily_budget_cents or 0) / 100, 2),
                "total_budget_usd": round(int(policy.total_budget_cents or 0) / 100, 2),
                # None (not 0) when the policy has no reconciled spend yet, so the CEO is not
                # misled into reading "$0 spent" for a campaign that simply hasn't synced.
                "last_synced_spend_usd": round(spend_cents / 100, 2) if spend_cents > 0 else None,
                "insights_synced_at": synced_dt.isoformat() if synced_dt is not None else None,
                "insights_synced_ago": synced_ago,
                "needs_sync": needs_sync,
            })
        except Exception:
            continue
    return out


def _wake_ad_refresh_enabled() -> bool:
    """Kill-switch for the pre-wake ad refresh. Default on; set TAKYON_WAKE_AD_REFRESH=0 to disable
    (auto-firing insights syncs) per-deployment without a redeploy."""
    raw = os.environ.get("TAKYON_WAKE_AD_REFRESH")
    return str(raw or "").strip().lower() not in {"0", "false", "no", "off"}


def _format_episode_metrics(snapshot: Any) -> str:
    """One compact ` [at record: …]` suffix for a wake-memory bet line, from the episode's
    metrics_snapshot. Empty string when the snapshot is absent/empty — old episodes render as
    before."""
    if not isinstance(snapshot, dict):
        return ""
    bits: list[str] = []
    for key, label in (("users", "users"), ("revenue_cents", "revenue_c"), ("usage_events", "usage")):
        if snapshot.get(key) is not None:
            bits.append(f"{label}={snapshot[key]}")
    for camp in (snapshot.get("campaigns") or [])[:2]:
        if isinstance(camp, dict):
            frag = f"{camp.get('slug')}: spend_c={camp.get('spend_cents')}"
            if camp.get("impressions") is not None:
                frag += f" impr={camp['impressions']}"
            if camp.get("clicks") is not None:
                frag += f" clicks={camp['clicks']}"
            bits.append(frag)
    x_stats = snapshot.get("x")
    if isinstance(x_stats, dict) and x_stats:
        bits.append("x " + " ".join(f"{k}={v}" for k, v in list(x_stats.items())[:3]))
    return f" [at record: {', '.join(bits)}]" if bits else ""


def _episode_metrics_snapshot(store: "TakyonStore", conn: Any, slug: str, channel: Any) -> dict[str, Any]:
    """Quantitative context captured AT EPISODE RECORD TIME (RL rail R1 support).

    Every episode carries at least one hard number so bets, lessons, and future settles are judged
    against measured state instead of narrative: lifetime product counters always (users, revenue,
    usage events), plus the episode channel's live-campaign delivery stats (spend from the policy
    registry; impressions/clicks from the latest insights-sync receipt) for reddit/meta, and the
    aggregated X metrics summary totals for channel=x. Best-effort by design: every source is wrapped so a missing
    table (SQLite dev store has no ad-spend policies), missing file, or provider gap degrades to
    fewer keys — never an exception, never a blocked episode."""
    snap: dict[str, Any] = {"captured_at": _now()}
    try:
        row = conn.execute(
            "SELECT COUNT(*) AS n FROM app_users WHERE business_slug = ?", (slug,)
        ).fetchone()
        snap["users"] = int(_row_value_int(row, "n"))
        # NET revenue, mirroring the canonical reader (app_payments.get_revenue_summary /
        # core pulse): reversal rows (refunds/chargebacks) are stored with a POSITIVE
        # amount_paid_cents but revenue_type='reversal' — they must subtract, or a refund
        # inside an episode's window would measure as a false positive revenue delta.
        row = conn.execute(
            "SELECT COALESCE(SUM(CASE WHEN revenue_type = 'reversal' THEN -amount_paid_cents "
            "ELSE amount_paid_cents END), 0) AS c FROM app_revenue_events WHERE business_slug = ?",
            (slug,),
        ).fetchone()
        snap["revenue_cents"] = int(_row_value_int(row, "c"))
        row = conn.execute(
            "SELECT COUNT(*) AS n FROM app_usage_events WHERE business_slug = ?", (slug,)
        ).fetchone()
        snap["usage_events"] = int(_row_value_int(row, "n"))
    except Exception:
        pass
    # Checkout + conversation counters: the judgeable numbers for pricing/checkout bets and for
    # outreach/support/conversation bets. Same always-on, never-raising posture as the product
    # counters above (each in its own guard so one missing table costs only its own keys).
    try:
        row = conn.execute(
            "SELECT COUNT(*) AS n FROM app_checkout_intents WHERE business_slug = ?", (slug,)
        ).fetchone()
        snap["checkout_intents"] = int(_row_value_int(row, "n"))
    except Exception:
        pass
    try:
        row = conn.execute(
            """
            SELECT SUM(CASE WHEN direction = 'inbound' THEN 1 ELSE 0 END) AS inbound,
                   SUM(CASE WHEN direction = 'inbound' AND status = 'needs_response' THEN 1 ELSE 0 END) AS unresolved
            FROM conversation_messages WHERE business_slug = ?
            """,
            (slug,),
        ).fetchone()
        snap["inbound_messages"] = int(_row_value_int(row, "inbound"))
        snap["unresolved_inbound"] = int(_row_value_int(row, "unresolved"))
    except Exception:
        pass
    bucket = _normalize_creative_credit_bucket(channel) if channel else ""
    if bucket in ("reddit", "meta"):
        try:
            backend = _business_ad_spend_backend()
            campaigns: list[dict[str, Any]] = []
            # Measurement needs a status set that is STABLE across a campaign's lifecycle:
            # if the "after" snapshot listed only live statuses, a campaign completing (or
            # settling at its cap) between an episode's open and its observation would vanish
            # from the after side and mint phantom NEGATIVE delivery deltas. So include the
            # full lifecycle (reserved/created_paused contribute zeros; completed keeps its
            # final reconciled numbers), unlike the pulse which deliberately shows live-only.
            _snapshot_statuses = list(_PULSE_AD_CAMPAIGN_STATUSES) + ["completed"]
            for policy in backend.list_policies(conn, slug, statuses=_snapshot_statuses):
                if str(policy.channel or "") != bucket:
                    continue
                entry: dict[str, Any] = {
                    "slug": policy.slug,
                    "status": policy.status,
                    "spend_cents": int(policy.last_synced_spend_cents or 0),
                    "total_budget_cents": int(policy.total_budget_cents or 0),
                }
                try:
                    syncs_dir = store._resolve_business_file(
                        slug, f"metrics/{bucket}-ads/{policy.slug}/syncs", sync=False
                    )
                    latest = max(
                        (p for p in syncs_dir.glob("*.json")), key=lambda p: p.stat().st_mtime
                    )
                    totals = (json.loads(latest.read_text(encoding="utf-8")) or {}).get("totals") or {}
                    # purchase_value_usd / purchase_count are the Meta-pixel attributed
                    # revenue the insights sync aggregates onto the receipt (action_values);
                    # absent on channels without purchase attribution (e.g. reddit today).
                    for key in ("impressions", "clicks", "spend_usd",
                                "purchase_value_usd", "purchase_count"):
                        if totals.get(key) is not None:
                            entry[key] = totals[key]
                except Exception:
                    pass
                campaigns.append(entry)
            if campaigns:
                snap["campaigns"] = campaigns
        except Exception:
            pass
    elif bucket == "x":
        try:
            # Business-level X totals live in metrics/x/summary.json (_x_write_summary), NOT in
            # the per-post sync receipts (those carry only per-post public/organic metric maps
            # and no "totals" key — reading them here silently yielded nothing). The summary's
            # totals keep the raw X API metric names, so map them to the snapshot vocabulary.
            summary_abs = store._resolve_business_file(slug, _x_metrics_summary_rel(), sync=False)
            summary = json.loads(summary_abs.read_text(encoding="utf-8")) or {}
            totals = summary.get("totals") if isinstance(summary.get("totals"), dict) else {}
            public = totals.get("public_metrics") if isinstance(totals.get("public_metrics"), dict) else {}
            x_stats: dict[str, int] = {}
            for src, dst in (("impression_count", "impressions"), ("like_count", "likes"),
                             ("reply_count", "replies")):
                if public.get(src) is not None:
                    x_stats[dst] = int(public.get(src) or 0)
            if public.get("retweet_count") is not None or public.get("quote_count") is not None:
                x_stats["reposts"] = int(public.get("retweet_count") or 0) + int(public.get("quote_count") or 0)
            for section in ("non_public_metrics", "organic_metrics"):
                sec = totals.get(section) if isinstance(totals.get(section), dict) else {}
                if sec.get("url_link_clicks") is not None:
                    x_stats["clicks"] = int(sec.get("url_link_clicks") or 0)
                    break
            if x_stats:
                snap["x"] = x_stats
        except Exception:
            pass
    if str(channel or "").strip().lower() in (
        "product", "site", "website", "app", "seo", "content", "landing", "launch",
    ):
        # Site/product/content bets are judged on traffic: best-effort web-analytics snapshot
        # (the helper caches per window and returns {"configured": False} when analytics is off,
        # so this degrades to nothing rather than a provider hit per episode).
        try:
            analytics = _business_analytics_summary(slug)
            if analytics.get("ok"):
                stats = analytics.get("stats") if isinstance(analytics.get("stats"), dict) else {}
                web: dict[str, Any] = {}
                for key in ("pageviews", "visitors", "uniques", "visits"):
                    value = stats.get(key)
                    if isinstance(value, dict):
                        value = value.get("value")
                    if value is not None:
                        web[key] = int(value)
                if web:
                    web["window_days"] = analytics.get("window_days")
                    snap["web"] = web
        except Exception:
            pass
    return snap


def _row_value_int(row: Any, key: str) -> int:
    if row is None:
        return 0
    try:
        return int(row[key] or 0)
    except Exception:
        try:
            return int(row[0] or 0)
        except Exception:
            return 0


def _refresh_stale_live_ad_campaigns(slug: str) -> dict[str, Any]:
    """Pre-wake best-effort refresh: for each LIVE (active/paused) + STALE ad campaign of this
    business, pull fresh delivery insights via the EXISTING (gated) channel insights-sync tool, so
    the pulse the CEO reads this wake is already current instead of relying on the agent to
    remember. Never raises — a failed or skipped refresh must never break the wake. Dispatches per
    channel (reddit + meta both register in the ad-spend policy registry as of the 2026-07-04
    parity fix). Reuses the shared staleness threshold; disable with TAKYON_WAKE_AD_REFRESH=0."""
    summary: dict[str, Any] = {"checked": 0, "refreshed": 0, "skipped": 0, "errors": 0, "campaigns": []}
    if not _wake_ad_refresh_enabled():
        summary["disabled"] = True
        return summary
    try:
        policies = _list_ad_spend_policies(slug, statuses=list(_PULSE_AD_LIVE_STATUSES))
    except Exception:
        return summary
    stale_seconds = _ad_insights_stale_seconds()
    now_dt = datetime.now(timezone.utc)
    hour_bucket = now_dt.strftime("%Y%m%dT%H")  # fresh key each wake; dedups retries within the hour
    for policy in policies or []:
        channel = str(policy.channel or "")
        if channel not in ("reddit", "meta"):
            summary["skipped"] += 1
            continue
        summary["checked"] += 1
        try:
            metadata = policy.metadata if isinstance(policy.metadata, dict) else {}
            synced_raw = metadata.get("insights_synced_at")
            synced_dt = _parse_iso_datetime(synced_raw) if synced_raw else None
            if synced_dt is not None and (now_dt - synced_dt).total_seconds() <= stale_seconds:
                summary["skipped"] += 1
                continue  # fresh enough — no refresh needed
            campaign_slug = policy.slug
            sync_args = {
                "business": slug,
                "slug": campaign_slug,
                "level": "campaign",
                "idempotency_key": f"wake-refresh:{campaign_slug}:campaign:{hour_bucket}",
            }
            if channel == "meta":
                # Lazy import: meta_ads_v2 imports core, so core must not import it at module load.
                try:
                    from . import meta_ads_v2
                except ImportError:  # pragma: no cover - alternate load path
                    from plugins.takyon import meta_ads_v2
                if policy.provider_campaign_id:
                    sync_args["object_id"] = str(policy.provider_campaign_id)
                raw = meta_ads_v2.handle_business_meta_ad_insights_sync(sync_args)
            else:
                raw = handle_business_reddit_ad_insights_sync(sync_args)
            ok = False
            try:
                ok = bool(json.loads(raw).get("success"))
            except Exception:
                ok = False
            if ok:
                summary["refreshed"] += 1
                summary["campaigns"].append(campaign_slug)
            else:
                summary["errors"] += 1
        except Exception:
            summary["errors"] += 1
            continue
    return summary


def _upsert_ad_spend_policy(
    business: str,
    *,
    channel: str,
    slug: str,
    reservation_key: str,
    reserved_credits: int,
    daily_budget_cents: int,
    total_budget_cents: int,
    start_at: datetime,
    end_at: datetime,
    provider_account_id: str | None = None,
    provider_campaign_id: str | None = None,
    provider_group_id: str | None = None,
    provider_ad_id: str | None = None,
    provider_post_id: str | None = None,
    status: str = "reserved",
    last_synced_spend_cents: int = 0,
    settled_credits: int = 0,
    metadata: Mapping[str, Any] | None = None,
):
    backend = _business_ad_spend_backend()
    store = _store()
    with store._connect() as conn:
        return backend.upsert_policy(
            conn,
            business_slug=business,
            channel=channel,
            slug=slug,
            reservation_key=reservation_key,
            reserved_credits=reserved_credits,
            daily_budget_cents=daily_budget_cents,
            total_budget_cents=total_budget_cents,
            start_at=start_at,
            end_at=end_at,
            provider_account_id=provider_account_id,
            provider_campaign_id=provider_campaign_id,
            provider_group_id=provider_group_id,
            provider_ad_id=provider_ad_id,
            provider_post_id=provider_post_id,
            status=status,
            last_synced_spend_cents=last_synced_spend_cents,
            settled_credits=settled_credits,
            metadata=dict(metadata or {}),
        )


