def handle_business_schedule_ceo_wakeup(args: dict, **_: Any) -> str:
    operation = {
        "action": "cron.ensure_ceo_wakeup",
        "business": args.get("business"),
        "schedule": args.get("schedule") or "every 6h",
    }
    return _commit_tool(args, operation)


def handle_business_gc(args: dict, **_: Any) -> str:
    _refuse_on_autonomous_wake("garbage collection")
    operation = {
        "action": "maintenance.gc",
        "older_than_days": args.get("older_than_days") or 90,
        "max_delete": args.get("max_delete") or 1000,
        "confirm": bool(args.get("confirm")),
    }
    return _commit_tool(args, operation, scope=args.get("scope") or "global")


def _business_version(value: Any) -> int:
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _detect_legacy_product_site(root: Path) -> str:
    for rel in ("product/site", "site"):
        candidate = root / rel
        if candidate.exists() and candidate.is_dir() and _product_source_files(candidate, limit=1):
            return rel
    return ""


def _legacy_distribution_mappings(root: Path) -> list[dict[str, str]]:
    distribution = root / "distribution"
    if not distribution.exists() or not distribution.is_dir():
        return []
    mappings: list[dict[str, str]] = []
    for child in sorted(distribution.rglob("*.md"), key=lambda path: path.as_posix())[:100]:
        if not child.is_file():
            continue
        rel = str(child.relative_to(root))
        name = child.name.lower()
        parts = {part.lower() for part in child.parts}
        if {"creative", "creatives"}.intersection(parts) or any(token in name for token in ("ad", "ugc", "video", "creative")):
            mapped_as = "local_creative_brief"
        elif "posts" in parts or any(token in name for token in ("post", "outreach", "launch")):
            mapped_as = "local_post"
        else:
            mapped_as = "distribution_note"
        mappings.append({"path": rel, "mapped_as": mapped_as})
    return mappings


def _legacy_asset_paths(root: Path) -> list[str]:
    suffixes = {".gif", ".jpg", ".jpeg", ".mov", ".mp4", ".png", ".webm"}
    skip_dirs = {".git", ".next", "node_modules", "venv", ".venv"}
    assets: list[str] = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [name for name in dirnames if name not in skip_dirs and not name.startswith(".cache")]
        for filename in sorted(filenames):
            if len(assets) >= 100:
                return assets
            child = Path(dirpath) / filename
            if child.suffix.lower() not in suffixes:
                continue
            if not child.is_file():
                continue
            try:
                rel = str(child.relative_to(root))
            except ValueError:
                continue
            if rel.startswith("metrics/receipts/"):
                continue
            assets.append(rel)
    return assets


def _plan_business_upgrade(conn: sqlite3.Connection, store: TakyonStore, business: dict[str, Any]) -> dict[str, Any]:
    slug = str(business.get("slug") or "")
    root = store._business_root(slug)
    metadata = business.get("metadata") if isinstance(business.get("metadata"), dict) else {}
    schema_version = _business_version(metadata.get("takyon_schema_version"))
    capability_version = _business_version(metadata.get("takyon_capability_version"))
    product_site = _detect_legacy_product_site(root)
    surface_row = conn.execute("SELECT business_slug FROM app_surface_contracts WHERE business_slug = ?", (slug,)).fetchone()
    distribution_mappings = _legacy_distribution_mappings(root)
    existing_assets = _legacy_asset_paths(root)
    receipt_exists = (root / BUSINESS_UPGRADE_RECEIPT).exists()

    actions: list[str] = []
    if schema_version < CURRENT_BUSINESS_SCHEMA_VERSION or capability_version < CURRENT_BUSINESS_CAPABILITY_VERSION:
        actions.append("set_business_versions")
    if distribution_mappings and not receipt_exists:
        actions.append("map_legacy_distribution_files")
    if existing_assets and not receipt_exists:
        actions.append("index_existing_local_assets")
    if actions and not receipt_exists:
        actions.append("write_upgrade_receipt")

    seen: set[str] = set()
    deduped_actions = [action for action in actions if not (action in seen or seen.add(action))]
    return {
        "business": slug,
        "current_schema_version": schema_version,
        "target_schema_version": CURRENT_BUSINESS_SCHEMA_VERSION,
        "current_capability_version": capability_version,
        "target_capability_version": CURRENT_BUSINESS_CAPABILITY_VERSION,
        "status": "needs_upgrade" if deduped_actions else "current",
        "actions": deduped_actions,
        "detected": {
            "product_site": product_site,
            "distribution_mappings": distribution_mappings,
            "existing_local_assets": existing_assets,
            "upgrade_receipt": BUSINESS_UPGRADE_RECEIPT if receipt_exists else "",
        },
    }


def _apply_business_upgrade(conn: sqlite3.Connection, store: TakyonStore, plan: dict[str, Any]) -> dict[str, Any]:
    slug = str(plan["business"])
    actions = list(plan.get("actions") or [])
    if not actions:
        return {**plan, "changed": False}

    root = store._business_root(slug)
    business = store._ensure_business(conn, slug)
    metadata = business.get("metadata") if isinstance(business.get("metadata"), dict) else {}
    now = _now()
    receipt_rel = BUSINESS_UPGRADE_RECEIPT
    metadata = {
        **metadata,
        "takyon_schema_version": CURRENT_BUSINESS_SCHEMA_VERSION,
        "takyon_capability_version": CURRENT_BUSINESS_CAPABILITY_VERSION,
        "takyon_last_upgrade": {
            "name": "takyon-business-upgrade-v1",
            "receipt": receipt_rel,
            "updated_at": now,
        },
    }
    conn.execute(
        "UPDATE businesses SET metadata_json = ?, updated_at = ? WHERE slug = ?",
        (_json_dumps(metadata), now, slug),
    )

    product_site = str((plan.get("detected") or {}).get("product_site") or "")
    receipt = {
        "schema": "takyon.business_upgrade.v1",
        "business": slug,
        "schema_version": CURRENT_BUSINESS_SCHEMA_VERSION,
        "capability_version": CURRENT_BUSINESS_CAPABILITY_VERSION,
        "actions": actions,
        "detected": plan.get("detected") or {},
        "invented_assets": False,
        "fake_receipts": False,
        "created_at": now,
    }
    _atomic_write_text(root / receipt_rel, _json_dumps(receipt) + "\n")
    store._record_event(
        conn,
        scope=f"business:{slug}",
        business_slug=slug,
        event_type="business.upgrade",
        payload={"receipt": receipt_rel, "actions": actions, "schema_version": CURRENT_BUSINESS_SCHEMA_VERSION, "capability_version": CURRENT_BUSINESS_CAPABILITY_VERSION},
    )
    return {**plan, "changed": True, "receipt": receipt_rel}


def upgrade_businesses(
    *,
    store: TakyonStore | None = None,
    businesses: Iterable[str] | None = None,
    dry_run: bool = True,
) -> dict[str, Any]:
    store = store or _store()
    requested = [_slugify(str(item)) for item in (businesses or []) if str(item).strip()]
    with store._connect() as conn:
        if requested:
            placeholders = ",".join("?" for _ in requested)
            rows = conn.execute(f"SELECT * FROM businesses WHERE slug IN ({placeholders}) ORDER BY updated_at DESC", requested).fetchall()
        else:
            rows = conn.execute("SELECT * FROM businesses ORDER BY updated_at DESC").fetchall()
        found = {str(row["slug"]) for row in rows}
        missing = [slug for slug in requested if slug not in found]
        if missing:
            raise TakyonError(f"business not found: {', '.join(missing)}")
        plans = [_plan_business_upgrade(conn, store, store._row_to_dict(row) or {}) for row in rows]
        if not dry_run:
            with conn:
                plans = [_apply_business_upgrade(conn, store, plan) for plan in plans]
    return {
        "success": True,
        "action": "business_upgrade_businesses",
        "dry_run": bool(dry_run),
        "schema_version": CURRENT_BUSINESS_SCHEMA_VERSION,
        "capability_version": CURRENT_BUSINESS_CAPABILITY_VERSION,
        "businesses": plans,
    }


def handle_business_upgrade_businesses(args: dict, **_: Any) -> str:
    try:
        dry_run = not bool(args.get("apply") or args.get("confirm"))
        if not dry_run:
            _refuse_on_autonomous_wake("business upgrades")
        businesses = args.get("businesses") or args.get("business")
        if isinstance(businesses, str):
            businesses = [businesses] if businesses.strip() else []
        result = upgrade_businesses(businesses=businesses or [], dry_run=dry_run)
        return tool_result(result)
    except Exception as exc:
        return tool_error(str(exc), success=False)


# ── worker-plane execution for long operator tasks ────────────────────────────────────────────────
# One execution path with an explicit deployment guardrail (CLAUDE.md > Operating Model): when the
# deployment declares a live worker service (TAKYON_OPERATOR_TASKS_VIA_WORKER=1 in the dashboard
# unit), long operator tool runs are enqueued onto the Postgres worker plane and the tool ATTACHES
# to the run instead of owning it. The work-request row (business_work_requests) is the canonical
# run object: the enqueue commit creates it, the worker handler (worker.py) flips it
# running -> completed/blocked/failed and stores the full tool result in its payload, and this
# dispatcher polls it. If the caller dies (dashboard PTY refresh/disconnect), the run continues and
# the result still lands in the run row, agent_runs, and events. A replay of the SAME tool call
# (same args + idempotency_key) re-attaches to the SAME run via commit idempotency.
# Deferral is skipped only inside the worker process itself (TAKYON_WORKER_PROCESS=1 — the
# surrounding job is already durable, and waiting on a sub-job could starve the drain threads).
# Business-scoped dashboard sessions still carry a session workspace root, but that workspace is
# the canonical business mirror for the current slug; worker deferral must preserve that path
# instead of misclassifying it as an unsafe local override and surfacing a fake platform blocker.

_WORK_REQUEST_TERMINAL_STATUSES = frozenset({"completed", "blocked", "failed", "cancelled"})
_WORKER_DEFERRAL_POLL_SECONDS = 3.0
# How long the caller waits for the worker to PICK UP (start) a deferred job before it stops
# blocking. This is NOT "the worker is dead" — under the single-concurrency worker, a new build job
# legitimately queues behind an in-flight build (~150-250s) plus light jobs (openmeter/ceo_wake), so a
# 30s pickup window made the CEO wrongly treat a perfectly-queued landing build as a hard blocker and
# ABORT the whole bootstrap (observed: fridge-to-fork landing never published — "did not start before
# the pickup deadline" ×3 while the build sat queued behind another build). Give a queued build time to
# start behind one in-flight build; and when the window still expires, the not-picked-up branch now
# returns a DETACHED/re-attachable result (not a hard error) so the bootstrap keeps going and the CEO
# re-attaches to the running job rather than declaring the landing failed.
_WORKER_PICKUP_TIMEOUT_SECONDS = 240.0


def _format_process_exit_detail(returncode: Any, *, process_label: str = "process") -> str:
    label = str(process_label or "process").strip() or "process"
    try:
        code = int(returncode)
    except Exception:
        return f"{label} exited before completion"
    if code < 0:
        signal_number = abs(code)
        try:
            signal_name = signal.Signals(signal_number).name
        except Exception:
            signal_name = f"signal {signal_number}"
        return f"{label} was interrupted by {signal_name} before completion"
    return f"{label} exited with code {code}"


def _summarize_operator_work_item(item: Mapping[str, Any] | None) -> dict[str, Any]:
    row = item if isinstance(item, Mapping) else {}
    payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
    if not payload and "payload_json" in row:
        payload = _json_loads(row.get("payload_json"), {})
        payload = payload if isinstance(payload, dict) else {}
    result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
    surface_refresh = result.get("surface_refresh") if isinstance(result.get("surface_refresh"), dict) else {}
    kind = str(row.get("kind") or payload.get("kind") or "").strip().lower()
    process_label = "Claude worker" if "claude" in kind else "worker process"
    worker_returncode = result.get("worker_returncode")
    process_exit_detail = ""
    try:
        if int(worker_returncode) < 0:
            process_exit_detail = _format_process_exit_detail(worker_returncode, process_label=process_label)
    except Exception:
        process_exit_detail = ""

    error_text = str(result.get("error") or "").strip()
    if process_exit_detail and error_text in {
        "",
        f"node exited {worker_returncode}",
        f"process exited {worker_returncode}",
    }:
        error_text = process_exit_detail

    detail = (
        str(payload.get("detail") or "").strip()
        or str(row.get("detail") or "").strip()
        or str(result.get("blocker") or "").strip()
        or str(surface_refresh.get("blocker") or "").strip()
        or error_text
        or str(result.get("worker_stderr") or "").strip()
        or str(result.get("raw_stdout") or "").strip()
        or str(result.get("summary") or "").strip()
        or str(payload.get("summary") or "").strip()
    )

    row_status = str(row.get("status") or "").strip()
    payload_status = str(payload.get("status") or "").strip()
    result_status = str(result.get("status") or "").strip()
    refresh_status = str(surface_refresh.get("status") or "").strip()

    def _looks_failed(value: str) -> bool:
        return bool(re.search(r"blocked|fail|error|cancel", str(value or ""), re.I))

    if any(_looks_failed(value) for value in (row_status, payload_status, result_status, refresh_status)):
        status = next(
            (
                value
                for value in (row_status, payload_status, result_status, refresh_status)
                if _looks_failed(value)
            ),
            "failed",
        )
    elif result.get("blocked") or surface_refresh.get("blocker"):
        status = "blocked"
    elif result.get("success") is False:
        status = "failed"
    else:
        status = row_status or payload_status or result_status or refresh_status or "idle"

    return {
        "payload": payload,
        "result": result,
        "status": status,
        "detail": detail,
        "error": error_text,
    }


def _operator_tasks_via_worker_enabled() -> bool:
    return _env_truthy("TAKYON_OPERATOR_TASKS_VIA_WORKER") and not _env_truthy("TAKYON_WORKER_PROCESS")


def _worker_plane_available() -> bool:
    """Whether a Postgres worker plane exists that an EXPLICIT ``wait_ms`` claude-agent call may
    target. Deliberately broader than :func:`_operator_tasks_via_worker_enabled`: it includes the
    worker process itself, because a CEO turn running INSIDE the worker (the VPS bootstrap lane)
    is exactly the caller that needs fire-and-continue — the enqueue is claimed by the worker's
    dedicated operator-task drain thread, not the thread the CEO turn occupies. The blanket
    never-defer-inside-worker guard stays for implicit (legacy) calls."""
    if _db_backend() != "postgres":
        return False
    return _env_truthy("TAKYON_OPERATOR_TASKS_VIA_WORKER") or _env_truthy("TAKYON_WORKER_PROCESS")


def _read_work_request_run(store: "TakyonStore", run_id: str) -> tuple[str, dict[str, Any]]:
    """Read the canonical run row (status + payload) for one work-request id."""
    with store._connect() as conn:
        row = conn.execute(
            f"SELECT status, payload_json FROM {store._work_requests_table()} WHERE id = ?",
            (run_id,),
        ).fetchone()
    if row is None:
        return "", {}
    try:
        payload = json.loads(str(row["payload_json"] or "") or "{}")
    except json.JSONDecodeError:
        payload = {}
    return str(row["status"] or ""), payload if isinstance(payload, dict) else {}


def _read_worker_job_run(store: "TakyonStore", worker_job_id: str) -> tuple[str, dict[str, Any]]:
    """Read the mirrored worker-plane job row when the work-request row is stale."""
    job_id = str(worker_job_id or "").strip()
    if not job_id:
        return "", {}
    try:
        try:
            from . import jobs as worker_jobs
        except ImportError:  # pragma: no cover - alternate load path when run as a top-level package
            from plugins.takyon import jobs as worker_jobs
        with store._connect() as conn:
            with store._leaf_conn(conn) as raw:
                job = worker_jobs.get_job(raw, job_id)
    except Exception:
        return "", {}
    if job is None:
        return "", {}
    return str(job.status or ""), {
        "kind": str(job.kind or ""),
        "payload": dict(job.payload or {}) if isinstance(job.payload, dict) else {},
        "result": dict(job.result or {}) if isinstance(job.result, dict) else {},
        "error": dict(job.error or {}) if isinstance(job.error, dict) else {},
    }


def _distribution_provider_blocked_text(text: str) -> bool:
    raw = str(text or "").strip()
    if not raw:
        return False
    patterns = (
        r"\bcreditsdepleted\b",
        r"does not have any credits to fulfill this request",
        r"/2/problems/credits\b",
        r"\bno active composio\b",
        r"\bconnected account\b",
    )
    return any(re.search(pattern, raw, re.I) for pattern in patterns)


def _terminal_work_request_result_from_worker_job(
    worker_status: str,
    worker_payload: Mapping[str, Any] | None,
) -> tuple[str, dict[str, Any]] | None:
    normalized_worker_status = str(worker_status or "").strip().lower()
    if normalized_worker_status not in _WORK_REQUEST_TERMINAL_STATUSES:
        return None
    payload = worker_payload if isinstance(worker_payload, Mapping) else {}
    result = dict(payload.get("result") or {}) if isinstance(payload.get("result"), Mapping) else {}
    error_payload = payload.get("error") if isinstance(payload.get("error"), Mapping) else {}
    error_text = str(
        result.get("error")
        or error_payload.get("error")
        or error_payload.get("reason")
        or ""
    ).strip()
    result_status = str(result.get("status") or "").strip().lower()
    final_status = result_status if result_status in _WORK_REQUEST_TERMINAL_STATUSES else normalized_worker_status
    if final_status == "completed":
        if result.get("blocked"):
            final_status = "blocked"
        elif result.get("success") is False:
            final_status = "failed"
    if final_status == "failed" and _distribution_provider_blocked_text(error_text):
        final_status = "blocked"
    repaired_result = dict(result)
    repaired_result.setdefault("status", final_status)
    if final_status == "completed":
        repaired_result.setdefault("success", True)
    else:
        repaired_result.setdefault("success", False)
    if final_status == "blocked":
        repaired_result.setdefault("blocked", True)
    if error_text:
        repaired_result.setdefault("error", error_text)
    return final_status, repaired_result


def _repair_stale_work_request_from_worker_job(
    store: "TakyonStore",
    *,
    run_id: str,
    worker_job_id: str,
    business: str,
    kind: str,
    worker_status: str,
    worker_payload: Mapping[str, Any] | None,
) -> tuple[str, dict[str, Any]] | None:
    repaired = _terminal_work_request_result_from_worker_job(worker_status, worker_payload)
    if repaired is None:
        return None
    final_status, final_result = repaired
    error_text = str(final_result.get("error") or "").strip()
    try:
        with store._connect() as conn:
            row = conn.execute(
                f"SELECT scope, kind, payload_json FROM {store._work_requests_table()} WHERE id = ?",
                (run_id,),
            ).fetchone()
            if row is not None:
                payload = _json_loads(row.get("payload_json"), {})
                payload = payload if isinstance(payload, dict) else {}
                payload["worker_job_id"] = worker_job_id
                payload["result"] = final_result
                if error_text:
                    payload["worker_error"] = error_text
                conn.execute(
                    f"UPDATE {store._work_requests_table()} SET status = ?, payload_json = ?, updated_at = ? WHERE id = ?",
                    (final_status, _json_dumps(payload), _now(), run_id),
                )
                if kind not in _WORKER_EXECUTED_JOB_KINDS:
                    store._rewrite_distribution_files(conn, business)
                store._record_event(
                    conn,
                    scope=str(row.get("scope") or f"business:{business}"),
                    business_slug=business,
                    event_type="job.enqueue.status",
                    payload={
                        "job_id": run_id,
                        "kind": str(row.get("kind") or kind),
                        "status": final_status,
                        "worker_job_id": worker_job_id,
                    },
                )
    except Exception as exc:
        logging.getLogger("takyon.worker_attach").warning(
            "failed to repair stale work request %s from terminal worker job %s: %s",
            run_id,
            worker_job_id,
            exc,
        )
    return final_status, final_result


def _terminal_worker_retry_fields(
    tool_name: str,
    run_id: str,
    status: str,
    *,
    side_effect: bool,
) -> dict[str, Any]:
    """Machine + prose routing for a worker run that finished WITHOUT success.

    The same-key re-call contract is attach-or-replay by design: once the run is terminal,
    re-calling with the SAME idempotency_key replays the stored result verbatim and never
    re-runs (observed live: a CEO looped the identical stale-base replay to budget
    exhaustion because nothing said so). These fields make the terminal state explicit and
    name the one real affordance — a NEW idempotency_key — with side-effect-safe wording on
    lanes that execute external actions."""
    if side_effect:
        note = (
            f"run {run_id} already finished as {status}; re-calling with the SAME idempotency_key "
            "replays this stored result and will never re-run. A retry requires a NEW "
            "idempotency_key and WILL re-execute the side effect (e.g. a live post), so first "
            "confirm the action did not already happen."
        )
    else:
        note = (
            f"run {run_id} already finished as {status}; re-calling with the SAME idempotency_key "
            "replays this stored result and will never re-run. To retry after fixing the cause, "
            "re-call with a NEW idempotency_key — a fresh run re-materializes the workspace at the "
            "current head revision."
        )
    return {"terminal": True, "retry_guidance": note}


def _run_operator_task_on_worker(
    *,
    store: "TakyonStore",
    business: str,
    kind: str,
    tool_name: str,
    deferred_args: dict[str, Any],
    commit_idempotency_key: str,
    wait_seconds: float,
    reason: str,
    actor: str,
) -> str:
    """Enqueue one worker-executed tool run and attach to it: poll the run row until terminal (return
    the recorded tool result verbatim) or until this caller's wait budget expires (return a detached
    'running' handle; the run keeps executing on the worker)."""
    commit = store.commit(
        scope=f"business:{business}",
        operations=[
            {
                "action": "job.enqueue",
                "business": business,
                "kind": kind,
                "worker_queue": True,
                "payload": {"tool": tool_name, "args": deferred_args},
            }
        ],
        idempotency_key=commit_idempotency_key,
        reason=reason,
        actor=actor,
    )
    op_result = (commit.get("results") or [{}])[0] if isinstance(commit, dict) else {}
    run_id = str(op_result.get("job") or "").strip()
    worker_job_id = str(op_result.get("worker_job") or "").strip()
    if not run_id or not worker_job_id:
        raise TakyonError(f"worker-plane enqueue did not return a run handle for {tool_name}")
    if float(wait_seconds) <= 0:
        # Fire-and-continue: perform exactly ONE status read below (which returns the stored
        # result when the replayed run is already terminal — the idempotent re-fire case), and
        # otherwise return an immediately-detached, re-attachable handle without sleeping.
        deadline = time.monotonic()
        pickup_deadline = deadline
    else:
        deadline = time.monotonic() + max(30.0, float(wait_seconds))
        pickup_deadline = time.monotonic() + min(
            max(5.0, _WORKER_PICKUP_TIMEOUT_SECONDS),
            max(5.0, float(wait_seconds)),
        )
    picked_up = False
    while True:
        status, payload = _read_work_request_run(store, run_id)
        normalized_status = str(status or "").strip().lower()
        if normalized_status == "running":
            picked_up = True
        worker_status, worker_payload = _read_worker_job_run(store, worker_job_id)
        normalized_worker_status = str(worker_status or "").strip().lower()
        if normalized_worker_status and normalized_worker_status != "queued":
            picked_up = True
        if normalized_status in _WORK_REQUEST_TERMINAL_STATUSES:
            result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
            result.setdefault("run_id", run_id)
            result.setdefault("worker_job", worker_job_id)
            if result.get("success"):
                return tool_result(result)
            error_text = str(
                result.get("error") or f"{tool_name} {normalized_status or status} on the worker plane"
            )
            extra = {k: v for k, v in result.items() if k != "error"}
            extra.update(
                _terminal_worker_retry_fields(
                    tool_name, run_id, normalized_status or str(status), side_effect=False
                )
            )
            return tool_error(error_text, **extra)
        repaired = _repair_stale_work_request_from_worker_job(
            store,
            run_id=run_id,
            worker_job_id=worker_job_id,
            business=business,
            kind=kind,
            worker_status=worker_status,
            worker_payload=worker_payload,
        )
        if repaired is not None:
            repaired_status, repaired_result = repaired
            repaired_result = dict(repaired_result)
            repaired_result.setdefault("run_id", run_id)
            repaired_result.setdefault("worker_job", worker_job_id)
            if repaired_result.get("success"):
                return tool_result(repaired_result)
            error_text = str(
                repaired_result.get("error")
                or f"{tool_name} {repaired_status or worker_status} on the worker plane"
            )
            extra = {k: v for k, v in repaired_result.items() if k != "error"}
            extra.update(
                _terminal_worker_retry_fields(
                    tool_name, run_id, str(repaired_status or worker_status), side_effect=False
                )
            )
            return tool_error(error_text, **extra)
        now = time.monotonic()
        if not picked_up and now >= pickup_deadline:
            # The worker has not STARTED this job yet — it is queued behind an in-flight build on the
            # single-concurrency worker. That is NOT a failure, so return a DETACHED/re-attachable
            # result (not a hard tool_error): a bootstrap landing build merely waiting its turn must
            # not be recorded as a blocker that aborts the whole bootstrap. The caller re-calls with
            # the same idempotency_key to re-attach and collect the published result.
            return tool_result(
                {
                    "success": False,
                    "status": normalized_status or "queued",
                    "detached": True,
                    "run_id": run_id,
                    "worker_job": worker_job_id,
                    "business": business,
                    "kind": kind,
                    "note": (
                        f"{tool_name} is queued on the worker plane (waiting behind an in-flight "
                        "build) and survives this session. Re-call the tool with the SAME arguments "
                        f"and idempotency_key to re-attach and collect the result for run {run_id}."
                    ),
                }
            )
        if now >= deadline:
            return tool_result(
                {
                    "success": False,
                    "status": normalized_status or "running",
                    "detached": True,
                    "run_id": run_id,
                    "worker_job": worker_job_id,
                    "business": business,
                    "kind": kind,
                    "note": (
                        f"{tool_name} is still executing on the worker plane and survives this "
                        "session. Re-call the tool with the SAME arguments and idempotency_key to "
                        "re-attach and collect the result, or inspect the business jobs/events for "
                        f"run {run_id}."
                    ),
                }
            )
        time.sleep(_WORKER_DEFERRAL_POLL_SECONDS)


def _run_worker_backed_business_job_and_wait(
    args: dict,
    operation: dict[str, Any],
    *,
    tool_name: str,
    wait_seconds: float = 45.0,
    scope: str | None = None,
    store: "TakyonStore" | None = None,
    principal: dict[str, Any] | None = None,
) -> str:
    """Enqueue one worker-backed business job and attach to its canonical work-request row."""
    active_store = store or _store()
    try:
        commit = _commit_tool_data(args, operation, scope=scope, store=active_store, principal=principal)
        op_result = (commit.get("results") or [{}])[0] if isinstance(commit, dict) else {}
        run_id = str(op_result.get("job") or "").strip()
        worker_job_id = str(op_result.get("worker_job") or "").strip()
        if not run_id or not worker_job_id:
            raise TakyonError(f"worker-plane enqueue did not return a run handle for {tool_name}")
        business = _business_slug(
            {
                "business": operation.get("business") or args.get("business"),
                "business_slug": args.get("business_slug"),
            },
            required=True,
        )
        deadline = time.monotonic() + max(30.0, float(wait_seconds))
        pickup_deadline = time.monotonic() + min(
            max(5.0, _WORKER_PICKUP_TIMEOUT_SECONDS),
            max(5.0, float(wait_seconds)),
        )
        picked_up = False
        while True:
            status, payload = _read_work_request_run(active_store, run_id)
            normalized_status = str(status or "").strip().lower()
            if normalized_status == "running":
                picked_up = True
            worker_status, worker_payload = _read_worker_job_run(active_store, worker_job_id)
            normalized_worker_status = str(worker_status or "").strip().lower()
            if normalized_worker_status and normalized_worker_status != "queued":
                picked_up = True
            if normalized_status in _WORK_REQUEST_TERMINAL_STATUSES:
                result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
                result = dict(result) if isinstance(result, dict) else {}
                result.setdefault("run_id", run_id)
                result.setdefault("worker_job", worker_job_id)
                result.setdefault("business", business)
                result.setdefault("kind", str(operation.get("kind") or "").strip())
                result.setdefault("status", normalized_status or status)
                if normalized_status == "completed" and "success" not in result:
                    result["success"] = True
                if result.get("success"):
                    return tool_result(result)
                error_text = str(
                    result.get("error")
                    or result.get("worker_error")
                    or f"{tool_name} {normalized_status or status} on the worker plane"
                ).strip() or f"{tool_name} {normalized_status or status} on the worker plane"
                extra = {k: v for k, v in result.items() if k != "error"}
                extra.update(
                    _terminal_worker_retry_fields(
                        tool_name, run_id, normalized_status or str(status), side_effect=True
                    )
                )
                return tool_error(error_text, **extra)
            repaired = _repair_stale_work_request_from_worker_job(
                active_store,
                run_id=run_id,
                worker_job_id=worker_job_id,
                business=business,
                kind=str(operation.get("kind") or "").strip(),
                worker_status=worker_status,
                worker_payload=worker_payload,
            )
            if repaired is not None:
                repaired_status, repaired_result = repaired
                repaired_result = dict(repaired_result)
                repaired_result.setdefault("run_id", run_id)
                repaired_result.setdefault("worker_job", worker_job_id)
                repaired_result.setdefault("business", business)
                repaired_result.setdefault("kind", str(operation.get("kind") or "").strip())
                if repaired_result.get("success"):
                    return tool_result(repaired_result)
                error_text = str(
                    repaired_result.get("error")
                    or repaired_result.get("worker_error")
                    or f"{tool_name} {repaired_status or worker_status} on the worker plane"
                ).strip() or f"{tool_name} {repaired_status or worker_status} on the worker plane"
                extra = {k: v for k, v in repaired_result.items() if k != "error"}
                extra.update(
                    _terminal_worker_retry_fields(
                        tool_name, run_id, str(repaired_status or worker_status), side_effect=True
                    )
                )
                return tool_error(error_text, **extra)
            now = time.monotonic()
            if not picked_up and now >= pickup_deadline:
                return tool_result(
                    {
                        "success": False,
                        "status": normalized_status or "queued",
                        "detached": True,
                        "run_id": run_id,
                        "worker_job": worker_job_id,
                        "business": business,
                        "kind": str(operation.get("kind") or "").strip(),
                        "note": (
                            f"{tool_name} is queued on the worker plane and survives this session. "
                            "Re-call the tool with EXACTLY the same arguments and the SAME "
                            f"idempotency_key to re-attach and collect the result for run {run_id}. "
                            "Do NOT redraft the content or mint a new idempotency_key — a new key "
                            "starts a SECOND run with real side effects (e.g. a duplicate live post)."
                        ),
                    }
                )
            if now >= deadline:
                return tool_result(
                    {
                        "success": False,
                        "status": normalized_status or "running",
                        "detached": True,
                        "run_id": run_id,
                        "worker_job": worker_job_id,
                        "business": business,
                        "kind": str(operation.get("kind") or "").strip(),
                        "note": (
                            f"{tool_name} is still executing on the worker plane and survives this "
                            "session. Re-call the tool with EXACTLY the same arguments and the SAME "
                            f"idempotency_key to re-attach and collect the result for run {run_id}. "
                            "Do NOT redraft the content or mint a new idempotency_key — a new key "
                            "starts a SECOND run with real side effects (e.g. a duplicate live post)."
                        ),
                    }
                )
            time.sleep(_WORKER_DEFERRAL_POLL_SECONDS)
    except Exception as exc:
        return tool_error(str(exc), success=False)


def _defer_claude_agent_task_to_worker(args: dict) -> str | None:
    """Route business_claude_agent_task through the worker plane when enabled; None ⇒ run inline.

    An EXPLICIT ``wait_ms`` argument widens the gate to any host with a Postgres worker plane —
    including the worker process itself, whose dedicated operator-task drain thread claims the
    enqueued job while the calling CEO turn keeps running. ``wait_ms: 0`` is fire-and-continue
    (enqueue, return detached immediately); a later call with the SAME args + idempotency_key and
    a positive ``wait_ms`` re-attaches and collects. ``wait_ms`` is stripped from the deferred
    payload so the fire and every re-attach hash to the SAME idempotent commit, and so the
    worker-side execution of the job never re-defers itself."""
    wait_ms_raw = args.get("wait_ms")
    explicit_wait = wait_ms_raw is not None
    if not (_operator_tasks_via_worker_enabled() or (explicit_wait and _worker_plane_available())):
        return None
    store = _store()
    business = _resolved_business_slug(args, required=True)
    instruction = str(args.get("instruction") or "").strip()
    if not instruction:
        raise TakyonError("instruction is required")
    idempotency_key = str(args.get("idempotency_key") or "").strip()
    if not idempotency_key:
        raise TakyonError("idempotency_key is required")
    workspace_raw = str(args.get("workspace") or "product/site").strip() or "product/site"
    workspace_rel = _canonical_business_output_relpath(workspace_raw, field="workspace")
    load_takyon_env()
    _require_api_access({"action": "agent.record", "business": business, "requires_api": ["anthropic"]})
    # Freeze session-dependent semantics NOW: the worker process has no session binding, so the
    # refresh_surface default must be resolved with THIS caller's context and passed explicitly.
    normalized_workspace = workspace_rel.strip("/").lower()
    workspace_targets_product_surface = (
        normalized_workspace == "product"
        or normalized_workspace.startswith("product/")
        or normalized_workspace in {"site", "website"}
    )
    refresh_surface = _boolish(
        args.get("refresh_surface"),
        default=workspace_targets_product_surface,
    )
    customer_facing = _workspace_needs_customer_ai_copy_contract(workspace_rel)
    timeout_ms = _clamp_int(
        args.get("timeout_ms"),
        default=1_200_000 if customer_facing else 300_000,
        minimum=30_000,
        maximum=1_800_000,
    )
    refresh_timeout_seconds = _clamp_int(
        args.get("refresh_timeout_seconds"),
        default=600 if customer_facing else 300,
        minimum=15,
        maximum=900,
    )
    deferred_args = {
        **{k: v for k, v in args.items() if k != "wait_ms"},
        "business": business,
        "workspace": workspace_rel,
        "refresh_surface": refresh_surface,
    }
    if explicit_wait:
        wait_seconds = max(0.0, _clamp_int(wait_ms_raw, default=0, minimum=0, maximum=3_600_000) / 1000.0)
    else:
        # Worst case: one bounded turn-cap continuation doubles the SDK run + surface refresh, plus claim slack.
        wait_seconds = 2.0 * (timeout_ms / 1000.0 + float(refresh_timeout_seconds)) + 120.0
    return _run_operator_task_on_worker(
        store=store,
        business=business,
        kind="claude.agent_task",
        tool_name="business_claude_agent_task",
        deferred_args=deferred_args,
        commit_idempotency_key=f"{idempotency_key}:claude-sdk-worker-job",
        wait_seconds=wait_seconds,
        reason=str(args.get("reason") or "Claude Agent SDK task (worker plane)"),
        actor=str(args.get("actor") or "agent"),
    )


def _defer_product_surface_refresh_to_worker(args: dict) -> str | None:
    """Route business_refresh_product_surface through the worker plane when enabled; None ⇒ inline."""
    if not _operator_tasks_via_worker_enabled():
        return None
    if _session_business_slug():
        raise TakyonError("trusted product surface refresh is available only on the authority tool surface")
    store = _store()
    business = _resolved_business_slug(args, required=True)
    idempotency_key = str(args.get("idempotency_key") or "").strip()
    if not idempotency_key:
        raise TakyonError("idempotency_key is required")
    timeout_seconds = _clamp_int(args.get("timeout_seconds"), default=300, minimum=15, maximum=900)
    return _run_operator_task_on_worker(
        store=store,
        business=business,
        kind="product.surface_refresh",
        tool_name="business_refresh_product_surface",
        deferred_args={**args, "business": business},
        commit_idempotency_key=f"{idempotency_key}:surface-refresh-worker-job",
        wait_seconds=float(timeout_seconds) + 180.0,
        reason=str(args.get("reason") or "product surface publication (worker plane)"),
        actor=str(args.get("actor") or "agent"),
    )


def _defer_mobile_release_to_worker(args: dict) -> str | None:
    """Route business_publish_mobile_release through the worker plane when enabled; None ⇒ inline.

    A real EAS build runs for minutes, so when worker deferral is on it belongs off the CEO turn (same
    shape as product.surface_refresh). The money (creative-credit reserve→settle-at-trigger→release)
    lives INSIDE the tool, which the worker re-invokes verbatim — no second money path here. The worker
    re-run sets ``TAKYON_WORKER_PROCESS`` so ``_operator_tasks_via_worker_enabled()`` is False there and
    the deferred run executes inline instead of re-deferring itself."""
    if not _operator_tasks_via_worker_enabled():
        return None
    store = _store()
    business = _resolved_business_slug(args, required=True)
    idempotency_key = str(args.get("idempotency_key") or "").strip()
    if not idempotency_key:
        raise TakyonError("idempotency_key is required to publish a mobile release on the worker plane")
    lane = str(args.get("lane") or "preview").strip().lower()
    # An EAS build + store submit can run long; give a generous re-attach budget with claim slack.
    wait_seconds = 1_800.0 + 180.0
    return _run_operator_task_on_worker(
        store=store,
        business=business,
        kind="store.build",
        tool_name="business_publish_mobile_release",
        deferred_args={**args, "business": business, "lane": lane},
        commit_idempotency_key=f"{idempotency_key}:mobile-release-worker-job",
        wait_seconds=wait_seconds,
        reason=str(args.get("reason") or "mobile release build (worker plane)"),
        actor=str(args.get("actor") or "agent"),
    )


_WORKSPACE_DURABILITY_EXCLUDED_PARTS = frozenset(
    {
        ".cache",
        ".git",
        ".next",
        ".pytest_cache",
        ".turbo",
        ".venv",
        "__pycache__",
        "_takyon",
        "build",
        "dist",
        "node_modules",
        "out",
        "venv",
    }
)


def _scoped_workspace_store(
    prototype_store: Any,
    *,
    root: Path,
    operator_user_id: str | None = None,
    backend_override: Any | None = None,
    base_revision_by_slug: Mapping[str, int] | None = None,
) -> Any:
    scoped_root = Path(root).expanduser().resolve()
    scoped: Any
    prototype_surface = getattr(prototype_store, "_surface_contract", None)
    if isinstance(prototype_store, TakyonStore):
        scoped = TakyonStore(root=scoped_root, operator_user_id=operator_user_id or None)
    else:
        scoped = None
        constructors = []
        if isinstance(prototype_surface, dict):
            constructors.append(lambda: prototype_store.__class__(scoped_root, surface_contract=dict(prototype_surface)))
        constructors.append(lambda: prototype_store.__class__(scoped_root))
        for builder in constructors:
            try:
                scoped = builder()
                break
            except TypeError:
                continue
        if scoped is None:
            scoped = TakyonStore(root=scoped_root, operator_user_id=operator_user_id or None)
        elif isinstance(prototype_surface, dict) and hasattr(scoped, "_surface_contract"):
            scoped._surface_contract = dict(prototype_surface)
    if hasattr(scoped, "_workspace_root_override"):
        setattr(scoped, "_workspace_root_override", scoped_root)
    if not hasattr(scoped, "_workspace_sync_cache"):
        scoped._workspace_sync_cache = set()
    if hasattr(scoped, "_workspace_base_revision"):
        scoped._workspace_base_revision = {
            _slugify(str(key)): int(value or 0)
            for key, value in (dict(base_revision_by_slug or {})).items()
        }
        if getattr(scoped, "_workspace_root_override", None) is not None and scoped._workspace_base_revision:
            _write_workspace_base_revisions(
                getattr(scoped, "_workspace_root_override"),
                scoped._workspace_base_revision,
            )
    if backend_override is not None:
        setattr(scoped, "_workspace_storage_backend_override", backend_override)
    return scoped


@contextmanager
def _mounted_canonical_business_workspace(
    store: "TakyonStore",
    business: str,
    *,
    owner_label: str = "",
):
    from . import storage

    backend = store._workspace_storage_backend()
    slug = _slugify(business)
    parent = storage._workspace_scratch_parent(None)
    prefix = f"takyon-{storage._safe_owner_label(owner_label or slug)}-{slug}-"
    home = Path(tempfile.mkdtemp(prefix=prefix, dir=str(parent))).resolve()
    try:
        try:
            os.chmod(home, 0o700)
        except OSError:
            pass
        workspace = home / "businesses" / slug
        workspace.parent.mkdir(parents=True, exist_ok=True)
        head_revision = store._business_head_revision(slug)
        _write_workspace_base_revisions(home, {slug: head_revision})
        if head_revision > 0:
            storage.materialize_workspace_revision(
                backend,
                slug,
                head_revision,
                workspace,
                delete_local=True,
            )
        else:
            workspace.mkdir(parents=True, exist_ok=True)
        yield home, backend, head_revision
    finally:
        shutil.rmtree(home, ignore_errors=True)


def _workspace_durability_file_hashes(root: Path) -> dict[str, str]:
    resolved = Path(root).resolve()
    if not resolved.exists():
        return {}
    hashes: dict[str, str] = {}
    for path in sorted(resolved.rglob("*")):
        if not path.is_file():
            continue
        rel = path.relative_to(resolved)
        if any(part in _WORKSPACE_DURABILITY_EXCLUDED_PARTS for part in rel.parts):
            continue
        try:
            hashes[rel.as_posix()] = hashlib.sha256(path.read_bytes()).hexdigest()
        except OSError:
            continue
    return hashes


def _verify_workspace_durable_readback(*, worker_root: Path, canonical_root: Path) -> dict[str, Any]:
    worker_files = _workspace_durability_file_hashes(worker_root)
    canonical_files = _workspace_durability_file_hashes(canonical_root)
    worker_only = sorted(set(worker_files) - set(canonical_files))
    canonical_only = sorted(set(canonical_files) - set(worker_files))
    changed = sorted(
        rel
        for rel in set(worker_files).intersection(canonical_files)
        if worker_files[rel] != canonical_files[rel]
    )
    matched = not worker_only and not canonical_only and not changed
    return {
        "matched": matched,
        "worker_root": str(Path(worker_root).resolve()),
        "canonical_root": str(Path(canonical_root).resolve()),
        "worker_digest": hashlib.sha256(_json_dumps(worker_files).encode("utf-8")).hexdigest(),
        "canonical_digest": hashlib.sha256(_json_dumps(canonical_files).encode("utf-8")).hexdigest(),
        "worker_file_count": len(worker_files),
        "canonical_file_count": len(canonical_files),
        "worker_only": worker_only[:20],
        "canonical_only": canonical_only[:20],
        "changed": changed[:20],
    }


def _workspace_durability_mismatch_summary(verification: Mapping[str, Any]) -> str:
    issues: list[str] = []
    changed = [str(item).strip() for item in verification.get("changed") or [] if str(item).strip()]
    worker_only = [str(item).strip() for item in verification.get("worker_only") or [] if str(item).strip()]
    canonical_only = [str(item).strip() for item in verification.get("canonical_only") or [] if str(item).strip()]
    if changed:
        issues.append("changed files " + ", ".join(changed[:3]))
    if worker_only:
        issues.append("missing from canonical " + ", ".join(worker_only[:3]))
    if canonical_only:
        issues.append("unexpected in canonical " + ", ".join(canonical_only[:3]))
    return "; ".join(issues)


def handle_business_claude_agent_task(args: dict, **_: Any) -> str:
    """Run a general Claude Agent SDK worker inside one business filesystem."""
    _refuse_on_autonomous_wake("product edits")
    store = _store()
    business = ""
    workspace_rel = "."
    instruction = ""
    idempotency_key = ""
    worker_instruction = ""
    model = ""
    resolved_guidance_skills: list[str] = []
    operator_user_id = ""
    operator_budget: dict[str, Any] = {}
    worker_invoked = False

    def _record_worker_failure(error_text: str) -> dict[str, Any] | None:
        if not business or not idempotency_key:
            return None
        try:
            return store.commit(
                scope=f"business:{business}",
                operations=[
                    {
                        "action": "agent.record",
                        "business": business,
                        "scope": f"business:{business}/workspace:{workspace_rel}",
                        "status": "failed",
                        "prompt": worker_instruction or instruction,
                        "result": {
                            "source": "claude-agent-sdk",
                            "workspace": workspace_rel,
                            "model": model,
                            "guidance_skills": resolved_guidance_skills,
                            "summary": "",
                            "error": error_text,
                            "surface_refresh": None,
                        },
                    }
                ],
                idempotency_key=f"{idempotency_key}:claude-sdk-agent-record",
                reason=args.get("reason") or "Claude Agent SDK task record",
                actor=args.get("actor") or "agent",
            )
        except Exception:
            return None

    try:
        deferred = _defer_claude_agent_task_to_worker(args)
        if deferred is not None:
            return deferred
        business = _resolved_business_slug(args, required=True)
        worker_session_bound = bool(_session_business_slug())
        instruction = str(args.get("instruction") or "").strip()
        if not instruction:
            raise TakyonError("instruction is required")

        idempotency_key = str(args.get("idempotency_key") or "").strip()
        if not idempotency_key:
            raise TakyonError("idempotency_key is required")

        workspace_raw = str(args.get("workspace") or "product/site").strip() or "product/site"
        workspace_rel = _canonical_business_output_relpath(workspace_raw, field="workspace")
        with store._connect() as conn:
            business_row = store._ensure_business(conn, business)
            _enforce_business_work_focus(
                {"action": "workspace.upsert", "business": business, "workspace": workspace_rel},
                str(business_row.get("work_focus") or "all"),
            )
            operator_user_id = str(business_row.get("owner_user_id") or store._active_operator_user_id() or "").strip()
        load_takyon_env()
        _require_api_access({"action": "agent.record", "business": business, "requires_api": ["anthropic"]})
        normalized_workspace = workspace_rel.strip("/").lower()
        workspace_targets_product_surface = (
            normalized_workspace == "product"
            or normalized_workspace.startswith("product/")
            or normalized_workspace in {"site", "website"}
        )
        # The mobile app workspace (product/app on a mobile_app business) has its OWN build/verify
        # lane (Expo typecheck + the credit-gated store publish) — the web surface refresh is
        # Vite-only and can never run against an Expo tree, so it is FORCED off here (an explicit
        # refresh_surface=true from web habit would otherwise run the Vite pipeline on the Expo
        # tree and fail the whole delegated task after the worker succeeded).
        mobile_app_workspace = False
        if _workspace_is_mobile_app_dir(workspace_rel):
            _arch_leaf = _archetype_leaf()
            business_archetype = str((business_row or {}).get("archetype") or "web_saas")
            try:
                mobile_app_workspace = (
                    _arch_leaf.normalize_archetype(business_archetype, allow_empty=True) == _arch_leaf.MOBILE_APP
                )
            except Exception:
                # An out-of-registry row value (version skew) degrades to the web path rather than
                # hard-failing the delegated task.
                mobile_app_workspace = False
        if mobile_app_workspace:
            refresh_surface = False
        else:
            refresh_surface = _boolish(
                args.get("refresh_surface"),
                default=workspace_targets_product_surface,
            )
        docker_isolated_worker = _should_run_claude_agent_in_docker(workspace_rel)
        customer_facing_product_workspace = _workspace_needs_customer_ai_copy_contract(workspace_rel)
        reuse_session_workspace = bool(
            docker_isolated_worker
            and worker_session_bound
            and getattr(store, "_workspace_root_override", None) is not None
        )
        workspace_context = nullcontext(None)
        workspace_backend = None
        mounted_base_revision = 0
        if docker_isolated_worker and not reuse_session_workspace:
            workspace_context = _mounted_canonical_business_workspace(
                store,
                business,
                owner_label=str(operator_user_id or business),
            )
        if not docker_isolated_worker:
            node = _resolve_runtime_executable("node")
            if not node:
                ensure_runtime = _ensure_javascript_runtime(package_manager=True)
                node = _resolve_runtime_executable("node")
            else:
                ensure_runtime = {"success": True, "installed": False, "capabilities": _runtime_capabilities(("node", "npm", "npx", "corepack", "pnpm", "yarn", "bun"))}
            if not node:
                raise TakyonError(
                    "javascript runtime unavailable for Claude Agent SDK tasks: "
                    f"{ensure_runtime.get('error') or 'node is missing'}"
                )
        # budget_usd bounds are env-overridable so a pricier model lane (e.g. claude-fable-5 at
        # 5x Sonnet's per-token price) can be given headroom per run without editing every call
        # site; defaults unchanged, same knob pattern as TAKYON_BUILD_DOCKER_CPUS/MEMORY.
        budget_usd = _clamp_float(
            args.get("budget_usd"),
            default=_env_positive_float(
                "TAKYON_CLAUDE_AGENT_BUDGET_DEFAULT_USD",
                8.0 if customer_facing_product_workspace else 2.0,
            ),
            minimum=0.05,
            maximum=_env_positive_float("TAKYON_CLAUDE_AGENT_BUDGET_MAX_USD", 25.0),
        )
        operator_budget = _reserve_operator_task_budget(
            business=business,
            operator_user_id=operator_user_id,
            reservation_key=f"{idempotency_key}:claude-sdk-budget",
            estimate_cents=max(1, int(round(budget_usd * 100))),
        )

        max_turns = _clamp_int(
            args.get("max_turns"),
            default=60 if customer_facing_product_workspace else 12,
            minimum=1,
            maximum=90 if customer_facing_product_workspace else 40,
        )
        timeout_ms = _clamp_int(
            args.get("timeout_ms"),
            default=1_200_000 if customer_facing_product_workspace else 300_000,
            minimum=30_000,
            maximum=1_800_000,
        )
        effort = str(
            args.get("effort")
            or ("medium" if customer_facing_product_workspace else os.getenv("TAKYON_CLAUDE_AGENT_EFFORT"))
            or "high"
        ).strip().lower()
        if effort not in {"low", "medium", "high"}:
            effort = "medium" if customer_facing_product_workspace else "high"
        # The configured coding-worker model (model.claude_agent_default) is the SINGLE source of
        # truth for BOTH lanes. The customer-facing branch used to hardcode "claude-sonnet-5" and
        # IGNORE that config, which was a silent trap after the provider split: on any host where
        # TAKYON_CLAUDE_AGENT_MODEL was not exported (a fresh collaborator clone — the env-fetch
        # never propagated it), a product/site build fell to claude-sonnet-5, and the safebox proxy
        # routes claude-* to the platform Anthropic account (credit-dead) -> "Credit balance is too
        # low", while deepseek-* routes to the live DeepSeek endpoint (climuru on Sai's machine,
        # 2026-07-08). Honor the config pin first; keep claude-sonnet-5 only as the customer-facing
        # fallback when no pin is configured. VPS is unchanged (its env var still wins below).
        default_model = _model_from_config("claude_agent_default", "deep_work_default") or (
            "claude-sonnet-5" if customer_facing_product_workspace else DEFAULT_CLAUDE_AGENT_MODEL
        )
        model = str(
            args.get("model")
            or os.getenv("TAKYON_CLAUDE_AGENT_MODEL")
            or default_model
        ).strip()
        guidance_skills: list[str] = []
        guidance_selection_reason = ""
        resolved_guidance_skills: list[str] = []
        guidance_block = ""
        worker_invoked = False
        worker_actual_cents: int | None = None
        install_surface = _boolish(args.get("install"), default=True)
        refresh_timeout_seconds = _clamp_int(
            args.get("refresh_timeout_seconds"),
            default=600 if customer_facing_product_workspace else 300,
            minimum=15,
            maximum=900,
        )
        sdk_result: dict[str, Any] = {}
        surface_refresh: dict[str, Any] | None = None
        worker_attempts = 0
        active_max_turns = max_turns
        turn_cap_retries: list[dict[str, int]] = []
        surface_build_retries: list[dict[str, str]] = []
        agent_record: dict[str, Any] | None = None
        with workspace_context as mounted_context, ExitStack() as scoped_workspaces:
            active_store = store
            mounted_home = None
            if docker_isolated_worker and mounted_context is not None:
                mounted_home, workspace_backend, mounted_base_revision = mounted_context
                active_store = _scoped_workspace_store(
                    store,
                    root=mounted_home,
                    operator_user_id=operator_user_id or None,
                    backend_override=workspace_backend,
                    base_revision_by_slug={business: mounted_base_revision},
                )

            app_summary = active_store.read(scope=f"business:{business}", query="summary", include=["app"], limit=20)
            app = app_summary.get("app") if isinstance(app_summary.get("app"), dict) else {}
            surface_for_worker = app.get("surface") or app.get("surface_contract") or {}
            if not isinstance(surface_for_worker, dict):
                surface_for_worker = {}
            guidance_skills, guidance_selection_reason = _resolve_worker_guidance_skills(
                args,
                workspace_rel,
                surface=surface_for_worker,
                instruction=instruction,
            )
            try:
                resolved_guidance_skills, guidance_block = _compose_worker_guidance_block(guidance_skills)
            except TakyonError:
                # An explicit caller request for a missing guidance skill must fail loud. The
                # auto-selected default design packs degrade to no guidance when a design skill is
                # not installed, rather than failing the whole product build.
                if "guidance_skills" in args:
                    raise
                resolved_guidance_skills, guidance_block = [], ""
                guidance_selection_reason = "design packs unavailable; proceeded without guidance"
            if refresh_surface and workspace_targets_product_surface:
                _enforce_canonical_product_surface_source_path(
                    business=business,
                    existing_source_path=str(surface_for_worker.get("source_path") or "").strip(),
                    requested_source_path=workspace_rel,
                    context="product surface refresh",
                )

            business_root = active_store._business_root(business).resolve()
            workspace_path = active_store._resolve_business_file(
                business,
                workspace_rel,
                require_output_root=True,
                field="workspace",
            ).resolve()
            workspace_path.mkdir(parents=True, exist_ok=True)
            if not workspace_path.is_dir():
                raise TakyonError(f"workspace is not a directory: {workspace_rel}")
            if business_root not in (workspace_path, *workspace_path.parents):
                raise TakyonError("workspace escaped business root")
            if _workspace_needs_runtime_ui_contract(workspace_rel):
                surface_for_worker = _materialized_surface_for_workspace(
                    workspace_path,
                    surface=surface_for_worker,
                )

            script = _repo_root() / "scripts" / "takyon-claude-agent-task.mjs"
            if not script.exists():
                raise TakyonError(f"Claude Agent SDK helper missing: {script}")

            dependency_state = _ensure_repo_node_dependencies(("@anthropic-ai/claude-agent-sdk",))
            if not dependency_state.get("success"):
                missing = ", ".join(dependency_state.get("missing_packages") or ["@anthropic-ai/claude-agent-sdk"])
                raise TakyonError(
                    "Claude Agent SDK dependencies unavailable before worker launch: "
                    f"missing {missing}. {dependency_state.get('error') or 'run npm install in the Takyon repo root'}"
                )

            workspace_contract = WORKSPACE_PATH_CONTRACT.format(workspace=workspace_rel)
            plans_configured = _app_summary_has_configured_plans(app) if _workspace_needs_runtime_ui_contract(workspace_rel) else False
            if _workspace_needs_runtime_ui_contract(workspace_rel):
                _materialize_subuser_app_kit(
                    workspace_path,
                    slug=business,
                    surface=surface_for_worker,
                    plans=app.get("plans") if isinstance(app, dict) else None,
                )
            elif mobile_app_workspace and normalized_workspace == "product/app":
                # The archetype preset's scaffold consumer: seed-once mobile_app_kit/scaffold into
                # product/app + force-refresh the platform-owned _takyon/ boundary. Only the exact
                # app root seeds — a subdirectory task must never nest a second scaffold.
                _materialize_mobile_app_workspace(
                    workspace_path,
                    slug=business,
                    business_name=str((business_row or {}).get("name") or ""),
                    description=str((business_row or {}).get("goal") or ""),
                    surface=surface_for_worker,
                )
            def build_worker_instruction(current_surface: dict[str, Any] | None) -> str:
                worker_instruction_parts = [instruction.rstrip()]
                if guidance_block:
                    worker_instruction_parts.append(guidance_block)
                if _workspace_needs_customer_ai_copy_contract(workspace_rel):
                    worker_instruction_parts.append(CUSTOMER_FACING_AI_COPY_CONTRACT)
                    # The web build gate demands `npm run build` — the Expo tree has no build
                    # script; the mobile gate verifies with tsc and the store publish gate.
                    worker_instruction_parts.append(
                        MOBILE_APP_BUILD_GATE_CONTRACT if mobile_app_workspace else PRODUCT_BUILD_GATE_CONTRACT
                    )
                if mobile_app_workspace:
                    worker_instruction_parts.append(MOBILE_APP_WORKER_CONTRACT)
                if _workspace_needs_runtime_ui_contract(workspace_rel):
                    worker_instruction_parts.append(PUBLIC_LANDING_COMPOSITION_CONTRACT)
                    worker_instruction_parts.append(PRODUCT_VISUAL_CRAFT_CONTRACT)
                    runtime_ui_contract = _runtime_ui_contract_block(current_surface)
                    if runtime_ui_contract:
                        worker_instruction_parts.append(runtime_ui_contract)
                    worker_instruction_parts.append(
                        _subuser_app_worker_contract_block(
                            current_surface,
                            plans_configured=plans_configured,
                        )
                    )
                    worker_instruction_parts.append(_subuser_app_kit_contract_block(current_surface))
                worker_instruction_parts.extend([WORKER_CAPABILITY_CONTRACT, workspace_contract])
                return "\n\n".join(part for part in worker_instruction_parts if part)

            worker_instruction = build_worker_instruction(surface_for_worker)
            payload_base = {
                "business": business,
                "workspace": workspace_rel,
                "cwd": str(workspace_path),
                "root": str(workspace_path),
                "model": model,
                "effort": effort,
                "maxTurns": max_turns,
                "timeoutMs": timeout_ms,
                "maxBudgetUsd": budget_usd,
                "allowBash": bool(
                    _workspace_needs_runtime_ui_contract(workspace_rel)
                    or _workspace_needs_customer_ai_copy_contract(workspace_rel)
                ),
            }

            surface = surface_for_worker if isinstance(surface_for_worker, dict) else {}
            requested_publish_policy = str(surface.get("publish_policy") or _DEFAULT_PRODUCT_PUBLISH_POLICY).strip() or _DEFAULT_PRODUCT_PUBLISH_POLICY
            publish_policy = "publish_after_refresh" if _is_shared_renderer_publish_policy(requested_publish_policy) else requested_publish_policy
            active_worker_instruction = worker_instruction

            # Default worker-progress sink: forward each concise worker step/activity line as a live
            # job/task-progress runtime event (kind="task") bound to the active worker-plane run id, so
            # the long Claude-worker phase surfaces a current step in the tui_gateway instead of going
            # blank. A richer caller may override this sink via _bound_claude_worker_progress(...).
            def _default_worker_progress_sink(progress_line: str) -> None:
                text = str(progress_line or "").strip()
                if not text:
                    return
                _record_claude_agent_runtime_event(
                    business=business,
                    workspace_rel=workspace_rel,
                    kind="task",
                    status="running",
                    detail=text,
                    line=text,
                    trace={"kind": "task", "detail": text, "status": "running"},
                )

            worker_progress_binding = (
                nullcontext()
                if _CLAUDE_WORKER_PROGRESS_SINK.get() is not None
                else _bound_claude_worker_progress(_default_worker_progress_sink)
            )
            scoped_workspaces.enter_context(worker_progress_binding)
            while True:
                worker_attempts += 1
                attempt_payload = {
                    **payload_base,
                    "maxTurns": active_max_turns,
                    "instruction": active_worker_instruction,
                }
                started_line = (
                    f"Claude worker started for {workspace_rel}."
                    if worker_attempts == 1
                    else f"Claude worker started for {workspace_rel} (attempt {worker_attempts})."
                )
                _record_claude_agent_runtime_event(
                    business=business,
                    workspace_rel=workspace_rel,
                    status="output",
                    detail=started_line,
                    line=started_line,
                )
                worker_invoked = True
                try:
                    if docker_isolated_worker:
                        run_cmd, docker_payload, worker_cwd, worker_env = _run_claude_agent_task_in_docker(
                            payload=attempt_payload,
                            workspace_path=workspace_path,
                            timeout_ms=timeout_ms,
                            business=business,
                            operator_user_id=operator_user_id,
                        )
                        proc = _run_claude_agent_task_process(
                            run_cmd=run_cmd,
                            payload=docker_payload,
                            cwd=worker_cwd,
                            timeout_ms=timeout_ms,
                            env=worker_env,
                            business=business,
                            workspace_rel=workspace_rel,
                        )
                    else:
                        # Non-docker host subprocess: same broker-lockdown contract as the docker lane —
                        # ANTHROPIC_BASE_URL = safebox proxy ROOT + a minted operator.session token (real
                        # owner), NO raw provider key. Fails closed if the safebox is unreachable / refuses
                        # the mint (there is no raw-key fallback to inject here anymore).
                        proc = _run_claude_agent_task_process(
                            run_cmd=[node, str(script)],
                            payload=attempt_payload,
                            cwd=str(_repo_root()),
                            timeout_ms=timeout_ms,
                            env=_claude_agent_non_docker_worker_env(business, operator_user_id),
                            business=business,
                            workspace_rel=workspace_rel,
                        )
                except subprocess.TimeoutExpired:
                    # Wall-clock wedge: the worker subprocess ran past timeoutMs+30s and
                    # _run_claude_agent_task_process killed it and re-raised. Do NOT let this escape the
                    # loop and discard the scratch — the SDK runs in permissionMode "acceptEdits", so any
                    # files the worker already wrote are durably on disk in the mounted scratch workspace.
                    # Preserve them: sync scratch->canonical (best-effort, fail-soft), then mark the result
                    # BLOCKED + timed_out and break so the existing anti-re-delegation guard (ceo.md rule
                    # #8) drives a hand-patch / continue-from-partial instead of a cold re-delegation. On
                    # this path active_store is still the scratch-mounted store (the readback reassignment
                    # only happens on the success path), so the sync persists the partial scratch. The
                    # partial is preserved but NOT published: success is False, so the refresh/publish
                    # block is skipped and the tsc/build gate still guards any later publish.
                    worker_actual_cents = None  # don't carry a prior attempt's parsed cost into the estimate settle
                    try:
                        partial_sync_status = active_store._sync_business_workspace_remote(business)
                    except Exception:
                        partial_sync_status = "partial_sync_failed"
                    sdk_result = {
                        "success": False,
                        "blocked": True,
                        "timed_out": True,
                        "worker_timeout_ms": int(timeout_ms),
                        "partial_workspace_sync_status": partial_sync_status,
                        "error": _truncate_text(
                            f"Claude worker timed out after {int(timeout_ms)}ms. Partial workspace edits "
                            f"are preserved in canonical source (sync {partial_sync_status}); do NOT cold "
                            "re-delegate from scratch — inspect the preserved partial and continue from it.",
                            8000,
                        ),
                    }
                    timeout_line = (
                        f"Claude worker timed out for {workspace_rel}; partial edits preserved "
                        f"(sync {partial_sync_status})."
                    )
                    _record_claude_agent_runtime_event(
                        business=business,
                        workspace_rel=workspace_rel,
                        status="blocked",
                        detail=timeout_line,
                        line=timeout_line,
                    )
                    break
                stdout = proc.stdout.strip()
                stderr = proc.stderr.strip()
                try:
                    parsed_result = json.loads(stdout) if stdout else {}
                    sdk_result = parsed_result if isinstance(parsed_result, dict) else {"success": False, "raw_stdout": _truncate_text(stdout)}
                except json.JSONDecodeError:
                    sdk_result = {"success": False, "raw_stdout": _truncate_text(stdout)}
                try:
                    worker_actual_cents = int(sdk_result.get("actual_cost_cents"))
                except (TypeError, ValueError, AttributeError):
                    worker_actual_cents = None
                if proc.returncode != 0:
                    sdk_result.setdefault("success", False)
                    sdk_result["worker_returncode"] = proc.returncode
                    if stderr:
                        sdk_result["worker_stderr"] = _truncate_text(stderr, 12000)
                    default_error = _format_process_exit_detail(
                        proc.returncode,
                        process_label="Claude worker",
                    )
                    sdk_result["error"] = _truncate_text(
                        stderr or sdk_result.get("error") or sdk_result.get("raw_stdout") or default_error,
                        8000,
                    )
                if sdk_result.get("success") and _claude_agent_summary_is_blocked(sdk_result.get("summary")):
                    sdk_result["blocked"] = True
                if sdk_result.get("success"):
                    prefix_repair = _repair_nested_workspace_prefix(workspace_path, workspace_rel)
                    if prefix_repair.get("repaired") or prefix_repair.get("blocked"):
                        sdk_result["workspace_prefix_repair"] = prefix_repair
                    if prefix_repair.get("blocked"):
                        sdk_result["success"] = False
                        sdk_result["error"] = (
                            "Claude Agent SDK output blocked because source files were written under a "
                            f"duplicate workspace prefix and could not be safely repaired: {prefix_repair.get('reason')}"
                        )
                if sdk_result.get("success"):
                    summary_text = _truncate_text(str(sdk_result.get("summary") or "").strip(), 280)
                    if summary_text:
                        _record_claude_agent_runtime_event(
                            business=business,
                            workspace_rel=workspace_rel,
                            status="completed",
                            detail=summary_text,
                            line=summary_text,
                        )
                else:
                    error_text = _truncate_text(str(sdk_result.get("error") or stderr or "Claude worker failed.").strip(), 280)
                    if error_text:
                        _record_claude_agent_runtime_event(
                            business=business,
                            workspace_rel=workspace_rel,
                            status="failed",
                            detail=error_text,
                            line=error_text,
                        )
                if sdk_result.get("success"):
                    # Persist successful worker edits before later refresh/publish logic can fail.
                    # A worker build that cannot reach durable state is NOT a success: fail
                    # closed with an exact blocker rather than reporting success while the
                    # scratch tree (and its real edits) is discarded on exit.
                    sync_status = active_store._sync_business_workspace_remote(business)
                    sdk_result = {**sdk_result, "workspace_sync_status": sync_status}
                    if sync_status != "synced":
                        blocker = "workspace_sync_skipped" if str(sync_status).startswith("skipped_") else "workspace_sync_failed"
                        sdk_result = {
                            **sdk_result,
                            "success": False,
                            "error": (
                                f"{blocker}: worker edits could not be persisted to durable business state "
                                f"(sync returned {sync_status!r}). The scratch build is discarded."
                            ),
                            "blocker": blocker,
                            "workspace_sync_status": sync_status,
                        }
                        _record_claude_agent_runtime_event(
                            business=business,
                            workspace_rel=workspace_rel,
                            status="failed",
                            detail=f"{blocker}: durable persistence unavailable ({sync_status})",
                            line=blocker,
                        )
                    elif docker_isolated_worker and customer_facing_product_workspace:
                        if workspace_backend is None:
                            workspace_backend = store._workspace_storage_backend()
                        readback_home, _readback_backend, readback_revision = scoped_workspaces.enter_context(
                            _mounted_canonical_business_workspace(
                                store,
                                business,
                                owner_label=f"{operator_user_id or business}-readback",
                            )
                        )
                        readback_store = _scoped_workspace_store(
                            store,
                            root=readback_home,
                            operator_user_id=operator_user_id or None,
                            backend_override=workspace_backend,
                            base_revision_by_slug={business: readback_revision},
                        )
                        readback_store._workspace_sync_cache.add(_slugify(business))
                        readback_store._workspace_revision_cache[_slugify(business)] = readback_revision
                        canonical_workspace_path = readback_store._resolve_business_file(
                            business,
                            workspace_rel,
                            require_output_root=True,
                            field="workspace",
                        ).resolve()
                        durability = _verify_workspace_durable_readback(
                            worker_root=workspace_path,
                            canonical_root=canonical_workspace_path,
                        )
                        sdk_result = {
                            **sdk_result,
                            "workspace_durability": durability,
                        }
                        active_store = readback_store
                        if not durability.get("matched"):
                            mismatch_summary = _workspace_durability_mismatch_summary(durability)
                            error_text = "worker_source_not_durable: Claude's product workspace edits diverged after canonical read-back"
                            if mismatch_summary:
                                error_text = f"{error_text}: {mismatch_summary}"
                            sdk_result = {
                                **sdk_result,
                                "success": False,
                                "error": error_text,
                                "blocker": "worker_source_not_durable",
                            }
                            _record_claude_agent_runtime_event(
                                business=business,
                                workspace_rel=workspace_rel,
                                status="failed",
                                detail="worker_source_not_durable: canonical read-back diverged from worker source",
                                line="worker_source_not_durable",
                            )
                        else:
                            workspace_path = canonical_workspace_path
                surface_refresh = None
                if sdk_result.get("success") and refresh_surface:
                    summary = active_store.read(scope=f"business:{business}", query="summary", include=["app"])
                    app = summary.get("app") if isinstance(summary.get("app"), dict) else {}
                    surface = app.get("surface") or app.get("surface_contract") or {}
                    if not isinstance(surface, dict):
                        surface = {}
                    requested_publish_policy = str(surface.get("publish_policy") or _DEFAULT_PRODUCT_PUBLISH_POLICY).strip() or _DEFAULT_PRODUCT_PUBLISH_POLICY
                    publish_policy = "publish_after_refresh" if _is_shared_renderer_publish_policy(requested_publish_policy) else requested_publish_policy
                    surface_refresh_source_path = _enforce_canonical_product_surface_source_path(
                        business=business,
                        existing_source_path=str(surface.get("source_path") or "").strip(),
                        requested_source_path=workspace_rel,
                        context="product surface refresh",
                    )
                    receipt_id = hashlib.sha256(
                        f"{idempotency_key}:surface-refresh:{workspace_rel}:attempt:{worker_attempts}".encode("utf-8")
                    ).hexdigest()[:32]
                    surface_refresh = _finalize_product_surface_refresh(
                        store=active_store,
                        business=business,
                        surface=surface,
                        plans=app.get("plans") if isinstance(app.get("plans"), list) else None,
                        source_path=surface_refresh_source_path,
                        publish_target=_product_publish_target(business, surface.get("publish_target")),
                        requested_publish_policy=requested_publish_policy,
                        publish_policy=publish_policy,
                        install=install_surface,
                        timeout_seconds=refresh_timeout_seconds,
                        receipt_path=f"metrics/receipts/product-surface/{receipt_id}.json",
                        refresh_source="business_claude_agent_task",
                    )
                    surface_refresh = {
                        **surface_refresh,
                        "guidance_skills": resolved_guidance_skills,
                        "guidance_selection_reason": guidance_selection_reason,
                    }
                    active_store._sync_business_workspace_remote(business)
                should_retry_turn_cap = (
                    not sdk_result.get("success")
                    and customer_facing_product_workspace
                    and len(turn_cap_retries) < 1
                    and _claude_agent_hit_turn_cap(sdk_result.get("error") or "")
                )
                if should_retry_turn_cap:
                    next_max_turns: int | None = None
                    if active_max_turns < 60:
                        next_max_turns = 60
                    elif active_max_turns < 90:
                        next_max_turns = 90
                    if next_max_turns and next_max_turns > active_max_turns:
                        turn_cap_retries.append({"from": int(active_max_turns), "to": int(next_max_turns)})
                        retry_note = (
                            f"Claude worker hit the turn cap at {active_max_turns} turns; "
                            f"retrying once with {next_max_turns} turns."
                        )
                        _record_claude_agent_runtime_event(
                            business=business,
                            workspace_rel=workspace_rel,
                            status="output",
                            detail=retry_note,
                            line=retry_note,
                        )
                        active_worker_instruction = _worker_turn_cap_retry_instruction(
                            worker_instruction,
                            prior_max_turns=active_max_turns,
                            next_max_turns=next_max_turns,
                            attempt_number=worker_attempts + 1,
                        )
                        active_max_turns = next_max_turns
                        continue
                # Warm in-session retry on a fixable build/typecheck failure: rather than bail to the
                # CEO (which re-delegates a fresh COLD worker pass), feed the exact build error back to
                # the agent on the SAME warm workspace so it fixes its own defect in one pass. Bounded
                # to two warm retries; forbidden-source / durability blockers are NOT retried here (they
                # fall through to the normal blocked path).
                should_retry_surface_build = (
                    bool(surface_refresh)
                    and surface_refresh.get("status") == "failed"
                    and not _surface_refresh_has_forbidden_source_blockers(surface_refresh)
                    and customer_facing_product_workspace
                    and len(surface_build_retries) < 2
                )
                if should_retry_surface_build:
                    build_error = str((surface_refresh or {}).get("error") or "product build/typecheck failed").strip()
                    surface_build_retries.append({"error": _truncate_text(build_error, 2000)})
                    retry_note = (
                        "Product build/typecheck failed on the canonical read-back; retrying once on the "
                        "warm workspace so the worker fixes it in-session instead of restarting."
                    )
                    _record_claude_agent_runtime_event(
                        business=business,
                        workspace_rel=workspace_rel,
                        status="output",
                        detail=retry_note,
                        line=retry_note,
                    )
                    active_worker_instruction = "\n\n".join(
                        [
                            worker_instruction.rstrip(),
                            "Hermes automatic build-fix retry (attempt "
                            + str(worker_attempts + 1)
                            + "): the product workspace was rebuilt from canonical source and "
                            "`npm run build` / `npm run typecheck` FAILED. Exact error:\n"
                            + _truncate_text(build_error, 4000)
                            + "\n\nContinue from the current workspace state (do NOT restart). Fix ONLY the "
                            "files causing the error above. Both `npm run build` and `npm run typecheck` must "
                            "pass before you finish — run them and confirm green. Do not leave unused "
                            "variables or imports; `tsc --noEmit` rejects them.",
                        ]
                    )
                    continue
                break
            # Warm-retry budget exhausted but the customer-facing product build is STILL failing on a
            # non-forbidden build/typecheck error: the worker diagnosed-but-did-not-fix. Classify this
            # as BLOCKED (not a generic publish failure) so _claude_agent_summary_is_blocked flags it and
            # ceo.md rule #8's anti-re-delegation guard routes it to a hand-patch instead of a cold
            # re-delegation loop. Forbidden-source blockers are handled by the dedicated block below.
            surface_build_still_failed = (
                bool(surface_refresh)
                and surface_refresh.get("status") == "failed"
                and not _surface_refresh_has_forbidden_source_blockers(surface_refresh)
                and customer_facing_product_workspace
                and bool(surface_build_retries)
            )
            if surface_build_still_failed:
                sdk_result["blocked"] = True
                sdk_result["success"] = False
                exhausted_build_error = (
                    _surface_refresh_exact_blocker(surface_refresh or {})
                    or str((surface_refresh or {}).get("error") or "").strip()
                    or "product build/typecheck still failing after warm retries"
                )
                exhausted_blocked_summary = _blocked_message(exhausted_build_error)
                if not _claude_agent_summary_is_blocked(sdk_result.get("summary")):
                    sdk_result["summary"] = exhausted_blocked_summary
                sdk_result.setdefault("error", exhausted_blocked_summary)
            if _surface_refresh_has_forbidden_source_blockers(surface_refresh):
                sdk_result["blocked"] = True
                blocked_summary = _blocked_message(_surface_refresh_exact_blocker(surface_refresh or {}))
                if not _claude_agent_summary_is_blocked(sdk_result.get("summary")):
                    sdk_result["summary"] = blocked_summary
            status = "completed" if sdk_result.get("success") else "failed"
            if sdk_result.get("blocked"):
                status = "blocked"
            if surface_refresh and surface_refresh.get("blocker"):
                status = "blocked"
            record_operations: list[dict[str, Any]] = []
            if surface_refresh:
                record_operations.extend(
                    _product_surface_refresh_operations(
                        business=business,
                        surface_refresh=surface_refresh,
                        surface=surface,
                        publish_target=_product_publish_target(business, surface.get("publish_target")),
                        publish_policy=publish_policy,
                        requested_publish_policy=requested_publish_policy,
                        activate_on_success=True,
                    )
                )
            record_operations.append(
                {
                    "action": "agent.record",
                    "business": business,
                    "scope": f"business:{business}/workspace:{workspace_rel}",
                    "status": status,
                    "prompt": active_worker_instruction,
                    "result": {
                        "source": "claude-agent-sdk",
                        "workspace": workspace_rel,
                        "model": model,
                        "guidance_skills": resolved_guidance_skills,
                        "guidance_selection_reason": guidance_selection_reason,
                        "summary": sdk_result.get("summary") or "",
                        "error": sdk_result.get("error") or None,
                        "blocked": bool(sdk_result.get("blocked")),
                        "worker_returncode": sdk_result.get("worker_returncode"),
                        "worker_stderr": sdk_result.get("worker_stderr"),
                        "raw_stdout": sdk_result.get("raw_stdout"),
                        "worker_attempts": worker_attempts,
                        "turn_cap_retries": turn_cap_retries,
                        "workspace_sync_status": sdk_result.get("workspace_sync_status"),
                        "workspace_durability": sdk_result.get("workspace_durability"),
                        "workspace_prefix_repair": sdk_result.get("workspace_prefix_repair"),
                        "surface_refresh": surface_refresh,
                    },
                }
            )
            agent_record = active_store.commit(
                scope=f"business:{business}",
                operations=record_operations,
                idempotency_key=f"{idempotency_key}:claude-sdk-agent-record",
                reason=args.get("reason") or "Claude Agent SDK task record",
                actor=args.get("actor") or "agent",
            )
        operator_budget = _finalize_operator_task_budget(
            operator_user_id=operator_user_id,
            reservation_key=str(operator_budget.get("reservation_key") or ""),
            reserved_cents=int(operator_budget.get("reserved_cents") or 0),
            consume_reserved=worker_invoked,
            actual_cents=worker_actual_cents,
        )
        # Coding-worker LLM spend slice of the cost/log ledger (operator_cost_events, 0070): the
        # SDK subprocess reports its exact cost/usage on stdout; the settle above is the money
        # truth, this row is the per-call debugging record. Best-effort by construction.
        try:
            from . import cost_events

            _sdk_usage = sdk_result.get("usage") if isinstance(sdk_result.get("usage"), dict) else {}
            cost_events.record_operator_event_autoconn(
                event_kind=cost_events.KIND_LLM_CALL,
                business_slug=business,
                user_id=operator_user_id or None,
                job_id=cost_events.operator_context().get("run_id") or None,
                run_id=cost_events.operator_context().get("run_id") or None,
                task_kind="business_claude_agent_task",
                name=model,
                status=status,
                provider="anthropic",
                model=model,
                input_tokens=_sdk_usage.get("input_tokens"),
                output_tokens=_sdk_usage.get("output_tokens"),
                cache_read_tokens=_sdk_usage.get("cache_read_input_tokens"),
                cache_write_tokens=_sdk_usage.get("cache_creation_input_tokens"),
                cost_microusd=(max(0, int(worker_actual_cents)) * 10_000) if worker_actual_cents is not None else None,
                cost_status="actual" if worker_actual_cents is not None else "unknown",
                reservation_key=str(operator_budget.get("reservation_key") or "") or None,
                error=str(sdk_result.get("error") or "") or None,
                payload={
                    "workspace": workspace_rel,
                    "worker_attempts": worker_attempts,
                    "blocked": bool(sdk_result.get("blocked")),
                    "timed_out": bool(sdk_result.get("timed_out")),
                },
            )
        except Exception:  # noqa: BLE001 — observability must never break the tool
            pass

        result_payload = {
            "success": bool(sdk_result.get("success")) and status == "completed",
            "business": business,
            "workspace": workspace_rel,
            "source": "claude-agent-sdk",
            "model": model,
            "guidance_skills": resolved_guidance_skills,
            "guidance_selection_reason": guidance_selection_reason,
            "blocked": bool(sdk_result.get("blocked")) or status == "blocked",
            "budget": operator_budget,
            "operator_budget": operator_budget,
            "agent_record": agent_record,
            "surface_refresh": surface_refresh,
            "worker_attempts": worker_attempts,
            "turn_cap_retries": turn_cap_retries,
            "summary": sdk_result.get("summary") or "",
            "actual_cost_cents": worker_actual_cents,
            "workspace_sync_status": sdk_result.get("workspace_sync_status"),
            "workspace_durability": sdk_result.get("workspace_durability"),
            "timed_out": bool(sdk_result.get("timed_out")),
            "partial_workspace_sync_status": sdk_result.get("partial_workspace_sync_status"),
            "error": sdk_result.get("error"),
            "worker_returncode": sdk_result.get("worker_returncode"),
            "worker_stderr": sdk_result.get("worker_stderr"),
            "raw_stdout": sdk_result.get("raw_stdout"),
        }
        if status != "completed":
            blocked_error = ""
            if _claude_agent_summary_is_blocked(sdk_result.get("summary")):
                blocked_error = _blocked_message(sdk_result.get("summary"))
            elif _surface_refresh_has_forbidden_source_blockers(surface_refresh):
                blocked_error = _blocked_message(
                    (surface_refresh or {}).get("blocker")
                    or _surface_refresh_exact_blocker(surface_refresh or {})
                )
            error_text = blocked_error or (
                str(
                    sdk_result.get("error")
                    or (surface_refresh or {}).get("blocker")
                    or _surface_refresh_exact_blocker(surface_refresh or {})
                    or "Claude Agent SDK task failed"
                ).strip()
                or "Claude Agent SDK task failed"
            )
            return tool_error(error_text, **result_payload)
        return tool_result(result_payload)
    except Exception as exc:
        if operator_budget and operator_budget.get("reservation_key"):
            try:
                _finalize_operator_task_budget(
                    operator_user_id=operator_user_id,
                    reservation_key=str(operator_budget.get("reservation_key") or ""),
                    reserved_cents=int(operator_budget.get("reserved_cents") or 0),
                    consume_reserved=worker_invoked,
                    actual_cents=worker_actual_cents,
                )
            except Exception:
                pass
        _record_worker_failure(str(exc))
        return tool_error(str(exc), success=False)


# ===========================================================================
# business_seo_add_property — register a subdomain as a URL-prefix property in
# Google Search Console under the operator's service account.
#
# Credential source: the full service-account JSON key (which embeds the
# private key) lives in the Takyon Safebox under the canonical
# TAKYON_GSC_SERVICE_ACCOUNT_KEY alias and is read through the Safebox
# authority — never a key file on disk and never browser OAuth. The same
# service account backs both the read-write (this tool) and read-only
# (business_seo_query_data) Search Console services; only the requested scope
# differs.
#
# The parent domain (e.g. sc-domain:coscale.app) is assumed already
# verified and owned by this service account; this tool only registers
# subdomains under that owner-verified parent. The API has no endpoint to grant
# ownership, so the one-time parent verification/grant is done in the GSC UI.
# ===========================================================================
_GSC_SERVICE_ACCOUNT_ENV = _GSC_KEY_ALIASES[0]  # Safebox secret: service-account JSON content


def _seo_build_credentials(scopes: list[str]) -> Any:
    """Build Google service-account credentials from the Safebox-held key.

    The service-account JSON (client_email + private_key + token_uri) is stored
    as a sensitive Safebox secret under TAKYON_GSC_SERVICE_ACCOUNT_KEY and read
    via the Takyon Safebox authority — no key file on disk, no OAuth browser
    flow. The one service account serves both the readonly and read-write scopes;
    callers pass the scope they need.
    """
    raw = _resolve_gsc_service_account_json()
    if not raw:
        raise TakyonError(
            "Google Search Console access needs the service-account credential in Safebox "
            f"under {_GSC_SERVICE_ACCOUNT_ENV}; it is not configured."
        )
    try:
        from google.oauth2 import service_account
    except Exception as exc:  # pragma: no cover - import guard
        raise TakyonError(
            "Google Search Console support requires google-api-python-client and google-auth"
        ) from exc
    try:
        info = json.loads(raw)
    except (TypeError, ValueError) as exc:
        raise TakyonError(
            f"{_GSC_SERVICE_ACCOUNT_ENV} must contain the service-account JSON key content"
        ) from exc
    return service_account.Credentials.from_service_account_info(info, scopes=scopes)


def _seo_build_search_console_service_rw():
    """Build a Search Console service with read-write scope (webmasters)."""
    try:
        from googleapiclient.discovery import build
    except Exception as exc:  # pragma: no cover - import guard
        raise TakyonError(
            "Google Search Console support requires google-api-python-client and google-auth"
        ) from exc

    credentials = _seo_build_credentials(["https://www.googleapis.com/auth/webmasters"])
    return build("webmasters", "v3", credentials=credentials, cache_discovery=False)


def _seo_list_search_console_sites(service) -> list[dict[str, Any]]:
    response = service.sites().list().execute()
    return response.get("siteEntry", [])


def _seo_add_gsc_property(service, site_url: str) -> dict[str, Any]:
    """Add a URL-prefix property to Search Console after verifying it is a
    subdomain of an already owner-level-verified property in the account.

    Returns a result dict with success, site_url, parent, and already_existed.
    """
    from urllib.parse import urlparse

    site_url = site_url.rstrip("/") + "/"

    parsed = urlparse(site_url)
    if parsed.scheme not in ("http", "https"):
        raise TakyonError(f"site_url must start with http:// or https://, got: {site_url}")

    host = parsed.hostname or ""
    if not host:
        raise TakyonError(f"Could not parse hostname from site_url: {site_url}")

    sites = _seo_list_search_console_sites(service)
    owner_entries = [
        s for s in sites
        if s.get("permissionLevel") in ("siteOwner", "siteFullUser")
    ]
    if not owner_entries:
        raise TakyonError(
            "No owner-level properties found in this Search Console account. "
            "Verify a root domain before adding subdomains."
        )

    # Find a verified parent that covers the target hostname.
    parent: str | None = None
    for entry in owner_entries:
        entry_url = entry["siteUrl"]
        if entry_url.startswith("sc-domain:"):
            domain = entry_url[len("sc-domain:"):]
            if host == domain or host.endswith("." + domain):
                parent = entry_url
                break
        else:
            parent_host = urlparse(entry_url).hostname or ""
            if parent_host and (host == parent_host or host.endswith("." + parent_host)):
                parent = entry_url
                break

    if parent is None:
        owner_list = ", ".join(e["siteUrl"] for e in owner_entries)
        raise TakyonError(
            f"{site_url} is not a subdomain of any owner-level property. "
            f"Approved properties: {owner_list}"
        )

    existing_urls = {s["siteUrl"] for s in sites}
    if site_url in existing_urls:
        return {"success": True, "site_url": site_url, "parent": parent, "already_existed": True}

    service.sites().add(siteUrl=site_url).execute()
    return {"success": True, "site_url": site_url, "parent": parent, "already_existed": False}


def handle_business_seo_add_property(args: dict, **_: Any) -> str:
    try:
        site_url = str(args.get("site_url") or "").strip()
        if not site_url:
            raise TakyonError("site_url is required")
        business = _resolved_business_slug(args, required=False)
        if business:
            idem = hashlib.sha256(
                f"business-seo-add-property:{business}:{site_url.rstrip('/') + '/'}".encode("utf-8")
            ).hexdigest()
            result = json.loads(
                handle_business_register_search_console(
                    {
                        "business": business,
                        "site_url": site_url,
                        "idempotency_key": f"business-seo-add-property:{idem}",
                        "reason": args.get("reason") or "register search console property",
                        "actor": args.get("actor") or "agent",
                    }
                )
            )
            return tool_result(
                {
                    "success": bool(result.get("success")),
                    "site_url": site_url.rstrip("/") + "/",
                    "business": business,
                    "registered_via": "business_register_search_console",
                    "receipt": result.get("receipt"),
                    "status": result.get("status"),
                    "value": result.get("value") or result,
                }
            )
        result = safebox.gsc_add_property(site_url)
        return tool_result(result)
    except Exception as exc:
        return tool_error(str(exc), success=False)


# ===========================================================================
# business_seo_query_data — Search Console + DataForSEO keyword evidence for
# SEO/GEO decisions. One business-scoped tool, four modes:
#   gsc-sites          → list accessible Search Console properties
#   gsc-query          → page/query metrics (clicks/impressions/ctr/position)
#   keyword-historical → DataForSEO Google Ads Search Volume for a known list
#   keyword-ideas      → DataForSEO Google Ads expansion of a seed topic/page URL
#
# GSC is read-only and free; it raises a clear TakyonError when creds are missing
# so the skill degrades to repo-inferred strategy. The keyword modes are PAID:
# they replace the old (free) Google Ads Keyword Planner backend with DataForSEO,
# which bills per request, so they are gated through the operator web-spend seam
# (agent/web_spend_meter.py — same rail as the CEO's web_search) and priced in
# agent/usage_pricing.py under the "dataforseo" namespace. They fail closed:
# missing safebox creds → dataforseo_unconfigured; over budget / unpriced / no
# meter in a business session → SpendBlocked — nothing spends and the skill
# degrades to inferred strategy. GSC auth reuses the shared Safebox service-account
# resolver (_seo_build_credentials, above); the DataForSEO login/password pair
# resolves through the same Safebox gate (no os.getenv side door, no key file).
# ===========================================================================
_DEFAULT_GEO_TARGET_ID = "2840"   # United States (Google criteria id; DataForSEO location_code uses the same ids)
_DATAFORSEO_BASE_URL = "https://api.dataforseo.com"
# DataForSEO Keywords Data → Google Ads result rows carry `monthly_searches[].month` as an
# integer 1-12. The previous Google Ads backend emitted the protobuf enum name ("JANUARY"…),
# so we map back to that exact shape to keep the tool result contract stable for the skill.
_SEO_MONTH_NAMES = (
    "JANUARY", "FEBRUARY", "MARCH", "APRIL", "MAY", "JUNE",
    "JULY", "AUGUST", "SEPTEMBER", "OCTOBER", "NOVEMBER", "DECEMBER",
)
# Back-compat: callers that still pass the legacy Google Ads language constant id get mapped to
# a DataForSEO language_code. New callers should pass `language_code` directly.
_SEO_LEGACY_LANGUAGE_ID_TO_CODE = {"1000": "en"}


def _seo_resolve_sensitive_env(name: str) -> str:
    """Resolve a sensitive credential strictly through the Takyon safebox gate.

    One path for every SEO-tool secret: the value comes from the safebox
    authority — fetched from the remote secret server with the
    ``TAKYON_SAFEBOX_TOKEN`` "tk key" on client planes, or read from the
    Safebox-host's own ``.env`` when this process IS the authority. There is no
    bare ``os.getenv`` side door for secrets. Returns "" when the safebox has no
    value or is unavailable, so callers can raise one uniform error.
    """
    try:
        from . import safebox

        return str(safebox.read_env_backed_value(name) or "").strip()
    except Exception:
        return ""


def _seo_build_search_console_service():
    """Build a Search Console service with readonly scope (webmasters.readonly)."""
    try:
        from googleapiclient.discovery import build
    except Exception as exc:  # pragma: no cover - import guard
        raise TakyonError(
            "Google Search Console support requires google-api-python-client and google-auth"
        ) from exc

    credentials = _seo_build_credentials(["https://www.googleapis.com/auth/webmasters.readonly"])
    return build("searchconsole", "v1", credentials=credentials, cache_discovery=False)


def _seo_query_search_console(
    service,
    *,
    site_url: str,
    start_date: str,
    end_date: str,
    dimensions: list[str] | None = None,
    row_limit: int = 1000,
    start_row: int = 0,
    search_type: str = "web",
    dimension_filters: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    body: dict[str, Any] = {
        "startDate": start_date,
        "endDate": end_date,
        "rowLimit": row_limit,
        "startRow": start_row,
        "type": search_type,
    }
    if dimensions:
        body["dimensions"] = dimensions
    if dimension_filters:
        body["dimensionFilterGroups"] = [
            {
                "groupType": "and",
                "filters": dimension_filters,
            }
        ]
    return service.searchanalytics().query(siteUrl=site_url, body=body).execute()


def _seo_resolve_dataforseo_auth() -> tuple[str, str]:
    """Resolve the DataForSEO login/password pair strictly through the Safebox gate.

    Same boundary as every other paid-provider key: the values come from the Safebox
    authority (no bare ``os.getenv`` side door, no on-disk credential file). Fails closed
    with a clear ``dataforseo_unconfigured`` error when either half is absent, so the SEO
    skill degrades to repo-inferred strategy rather than spending or fabricating.
    """
    login = _seo_resolve_sensitive_env("DATAFORSEO_LOGIN")
    password = _seo_resolve_sensitive_env("DATAFORSEO_PASSWORD")
    if not login or not password:
        raise TakyonError(
            "dataforseo_unconfigured: DATAFORSEO_LOGIN and DATAFORSEO_PASSWORD must be "
            "resolvable from the Takyon safebox before keyword data can be fetched"
        )
    return login, password


def _seo_require_metered_business_scope() -> None:
    """The paid DataForSEO keyword modes must run inside a business scope so the spend is
    metered against that business's budget. In global/non-business scope the operator
    web-spend meter takes no hold (it returns None by design), which would let the paid call
    run ungated — so refuse here instead (fail closed), matching the no-ungated-paid rule.
    The free GSC modes are unaffected."""
    if not _session_business_slug():
        raise TakyonError(
            "keyword modes require a business scope: paid DataForSEO calls are metered "
            "against a business budget and are refused outside a business session"
        )


def _seo_dataforseo_location_code(args: dict) -> int:
    """Resolve a DataForSEO ``location_code`` (Google criteria id). Prefer an explicit
    ``location_code``; fall back to the first legacy ``geo_target_ids`` entry; default US."""
    direct = str(args.get("location_code") or "").strip()
    if direct:
        try:
            return int(direct)
        except ValueError:
            pass
    for item in _as_list(args.get("geo_target_ids")):
        token = str(item).strip()
        if not token:
            continue
        try:
            return int(token)
        except ValueError:
            continue
    return int(_DEFAULT_GEO_TARGET_ID)


def _seo_dataforseo_language_code(args: dict) -> str:
    """Resolve a DataForSEO ``language_code`` ("en"). Prefer an explicit ``language_code``;
    fall back to a legacy Google Ads ``language_id``; default English."""
    direct = str(args.get("language_code") or "").strip()
    if direct:
        return direct
    legacy = str(args.get("language_id") or "").strip()
    return _SEO_LEGACY_LANGUAGE_ID_TO_CODE.get(legacy, "en")


def _seo_call_dataforseo(
    path: str,
    payload: dict[str, Any],
    *,
    login: str,
    password: str,
    timeout: int = 60,
) -> list[dict[str, Any]]:
    """POST one task to a DataForSEO ``/live`` endpoint with Basic Auth and return its result
    rows. Raises ``TakyonError`` on any HTTP/parse/status failure so the metered wrapper releases
    the reservation and nothing is recorded as spent on a failed read."""
    import base64

    url = f"{_DATAFORSEO_BASE_URL}{path}"
    body = json.dumps([payload]).encode("utf-8")  # DataForSEO expects an array of task objects
    token = base64.b64encode(f"{login}:{password}".encode("utf-8")).decode("ascii")
    request = urllib.request.Request(
        url,
        data=body,
        headers={"Authorization": f"Basic {token}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read().decode("utf-8")
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            detail = exc.read().decode("utf-8")[:500]
        except Exception:
            detail = ""
        raise TakyonError(f"DataForSEO HTTP {exc.code} for {path}: {detail or exc.reason}") from exc
    except urllib.error.URLError as exc:
        raise TakyonError(f"DataForSEO request failed for {path}: {exc.reason}") from exc

    try:
        parsed = json.loads(raw)
    except Exception as exc:
        raise TakyonError(f"DataForSEO returned non-JSON for {path}") from exc

    if parsed.get("status_code") != 20000:
        raise TakyonError(
            f"DataForSEO error {parsed.get('status_code')}: {parsed.get('status_message') or 'unknown'}"
        )
    tasks = parsed.get("tasks") or []
    if not tasks:
        return []
    task0 = tasks[0] or {}
    if task0.get("status_code") != 20000:
        raise TakyonError(
            f"DataForSEO task error {task0.get('status_code')}: {task0.get('status_message') or 'unknown'}"
        )
    return [item for item in (task0.get("result") or []) if isinstance(item, dict)]


def _seo_metered_dataforseo(
    op: str,
    path: str,
    payload: dict[str, Any],
    *,
    login: str,
    password: str,
) -> list[dict[str, Any]]:
    """Reserve → call → settle one paid DataForSEO request through the operator web-spend seam
    (same rail as the CEO's web_search), priced off ``("dataforseo", op)`` in usage_pricing.

    Fails closed: a ``SpendBlocked`` (over budget, unpriced, or no meter registered in a business
    session) raised by ``reserve_paid_call`` propagates before any provider call, so nothing is
    spent; any HTTP/parse error releases the reservation in ``finally``. The flat $0.075/request
    price is independent of keyword count, so ``units`` is always 1."""
    from agent.web_spend_meter import (
        release_paid_call,
        reserve_paid_call,
        settle_paid_call,
    )

    handle = reserve_paid_call(
        pricing_key=("dataforseo", op),
        provider="dataforseo",
        op=op,
        units=1,
        purpose="seo_keyword_research",
    )
    settled = False
    try:
        rows = _seo_call_dataforseo(path, payload, login=login, password=password)
        settle_paid_call(handle, units=1)
        settled = True
        return rows
    finally:
        if handle is not None and not settled:
            release_paid_call(handle, error="dataforseo_call_failed")


def _seo_normalize_dataforseo_item(item: dict[str, Any]) -> dict[str, Any]:
    """Map one DataForSEO Google Ads keyword row into the stable tool result shape the SEO skill
    already reads. DataForSEO bids are floats in USD; the previous Google Ads backend emitted
    integer micros, so we convert (×1e6) to keep ``*_micros`` field semantics. ``cpc`` is surfaced
    as an additive real field. ``close_variants`` has no DataForSEO equivalent, so it stays an empty
    list rather than being fabricated (keyword-ideas already returns variants as their own rows)."""

    def _bid_to_micros(value: Any) -> int | None:
        if value in (None, ""):
            return None
        try:
            return int(round(float(value) * 1_000_000))
        except (TypeError, ValueError):
            return None

    monthly: list[dict[str, Any]] = []
    for month in (item.get("monthly_searches") or []):
        if not isinstance(month, dict):
            continue
        raw_month = month.get("month")
        try:
            month_int = int(raw_month)
        except (TypeError, ValueError):
            month_int = 0
        # Guard the 1..12 range explicitly: Python negative indexing means month 0
        # would silently resolve to _SEO_MONTH_NAMES[-1] ("DECEMBER") without raising.
        month_name = _SEO_MONTH_NAMES[month_int - 1] if 1 <= month_int <= 12 else str(raw_month or "")
        monthly.append(
            {
                "year": month.get("year"),
                "month": month_name,
                "monthly_searches": month.get("search_volume"),
            }
        )

    return {
        "keyword": item.get("keyword") or "",
        "avg_monthly_searches": item.get("search_volume"),
        "competition": str(item.get("competition") or ""),
        "competition_index": item.get("competition_index"),
        "low_top_of_page_bid_micros": _bid_to_micros(item.get("low_top_of_page_bid")),
        "high_top_of_page_bid_micros": _bid_to_micros(item.get("high_top_of_page_bid")),
        "cpc": item.get("cpc"),
        "monthly_search_volumes": monthly,
        "close_variants": [],
    }


def _seo_dataforseo_keyword_metrics(
    *,
    keywords: list[str],
    location_code: int,
    language_code: str,
    login: str,
    password: str,
) -> list[dict[str, Any]]:
    """keyword-historical: demand/competition for a known keyword list via DataForSEO Keywords
    Data → Google Ads Search Volume (live). One request covers up to 1000 keywords."""
    if not keywords:
        raise TakyonError("keywords must not be empty")
    payload = {
        "keywords": keywords[:1000],
        "location_code": location_code,
        "language_code": language_code,
    }
    rows = _seo_metered_dataforseo(
        "search_volume",
        "/v3/keywords_data/google_ads/search_volume/live",
        payload,
        login=login,
        password=password,
    )
    return [_seo_normalize_dataforseo_item(item) for item in rows]


def _seo_dataforseo_keyword_ideas(
    *,
    keywords: list[str] | None = None,
    page_url: str | None = None,
    location_code: int,
    language_code: str,
    include_adult_keywords: bool = False,
    limit: int = 100,
    login: str,
    password: str,
) -> list[dict[str, Any]]:
    """keyword-ideas: expand a seed via DataForSEO Keywords Data → Google Ads. A keyword seed uses
    keywords_for_keywords (capped at 20 seeds by the endpoint); a pure page/URL seed uses
    keywords_for_site. Both preserve Keyword Planner semantics (volume/competition/CPC)."""
    seed_terms = [str(item).strip() for item in (keywords or []) if str(item).strip()]
    normalized_page_url = str(page_url or "").strip()

    if seed_terms:
        op = "keywords_for_keywords"
        path = "/v3/keywords_data/google_ads/keywords_for_keywords/live"
        # keywords_for_keywords/live has no `target`/URL-seed parameter (only
        # keywords_for_site does), so a page_url passed alongside keywords is ignored
        # here rather than sent as an unsupported field that the API would reject.
        payload: dict[str, Any] = {
            "keywords": seed_terms[:20],
            "location_code": location_code,
            "language_code": language_code,
            "include_adult_keywords": bool(include_adult_keywords),
        }
    elif normalized_page_url:
        op = "keywords_for_site"
        path = "/v3/keywords_data/google_ads/keywords_for_site/live"
        payload = {
            "target": normalized_page_url,
            "location_code": location_code,
            "language_code": language_code,
            "include_adult_keywords": bool(include_adult_keywords),
        }
    else:
        raise TakyonError("keyword-ideas requires keywords and/or page_url")

    rows = _seo_metered_dataforseo(op, path, payload, login=login, password=password)
    normalized = [_seo_normalize_dataforseo_item(item) for item in rows]
    return normalized[: max(1, int(limit))]


def handle_business_seo_query_data(args: dict, **_: Any) -> str:
    try:
        mode = str(args.get("mode") or "").strip().lower()
        if not mode:
            raise TakyonError("mode is required")

        if mode == "gsc-sites":
            service = _seo_build_search_console_service()
            sites = _seo_list_search_console_sites(service)
            return tool_result({"success": True, "mode": mode, "site_entries": sites, "count": len(sites)})

        if mode == "gsc-query":
            site_url = str(args.get("site_url") or "").strip()
            start_date = str(args.get("start_date") or "").strip()
            end_date = str(args.get("end_date") or "").strip()
            if not site_url:
                raise TakyonError("site_url is required for gsc-query")
            if not start_date or not end_date:
                raise TakyonError("start_date and end_date are required for gsc-query")
            dimensions = [
                str(item).strip()
                for item in _as_list(args.get("dimensions") or ["query", "page"])
                if str(item).strip()
            ]
            filters: list[dict[str, Any]] | None = None
            page_filter = str(args.get("page_filter") or "").strip()
            if page_filter:
                filters = [{"dimension": "page", "operator": "equals", "expression": page_filter}]
            service = _seo_build_search_console_service()
            response = _seo_query_search_console(
                service,
                site_url=site_url,
                start_date=start_date,
                end_date=end_date,
                dimensions=dimensions or None,
                row_limit=int(args.get("row_limit") or 1000),
                start_row=int(args.get("start_row") or 0),
                search_type=str(args.get("search_type") or "web").strip() or "web",
                dimension_filters=filters,
            )
            rows = list(response.get("rows") or [])
            return tool_result(
                {
                    "success": True,
                    "mode": mode,
                    "site_url": site_url,
                    "date_range": {"start_date": start_date, "end_date": end_date},
                    "dimensions": dimensions,
                    "row_count": len(rows),
                    "totals": {
                        "clicks": response.get("clicks"),
                        "impressions": response.get("impressions"),
                        "ctr": response.get("ctr"),
                        "position": response.get("position"),
                    },
                    "response": response,
                }
            )

        if mode == "keyword-historical":
            raw_keywords = [
                str(item).strip() for item in _as_list(args.get("keywords")) if str(item).strip()
            ]
            if not raw_keywords:
                raise TakyonError("keywords are required for keyword-historical")
            _seo_require_metered_business_scope()
            login, password = _seo_resolve_dataforseo_auth()
            location_code = _seo_dataforseo_location_code(args)
            language_code = _seo_dataforseo_language_code(args)
            rows = _seo_dataforseo_keyword_metrics(
                keywords=raw_keywords,
                location_code=location_code,
                language_code=language_code,
                login=login,
                password=password,
            )
            return tool_result(
                {
                    "success": True,
                    "mode": mode,
                    "provider": "dataforseo",
                    "location_code": location_code,
                    "language_code": language_code,
                    "keywords": raw_keywords,
                    "row_count": len(rows),
                    "rows": rows,
                }
            )

        if mode == "keyword-ideas":
            raw_keywords = [
                str(item).strip() for item in _as_list(args.get("keywords")) if str(item).strip()
            ]
            page_url = str(args.get("page_url") or args.get("url_seed") or "").strip()
            if not raw_keywords and not page_url:
                raise TakyonError("keyword-ideas requires keywords and/or page_url")
            _seo_require_metered_business_scope()
            login, password = _seo_resolve_dataforseo_auth()
            location_code = _seo_dataforseo_location_code(args)
            language_code = _seo_dataforseo_language_code(args)
            rows = _seo_dataforseo_keyword_ideas(
                keywords=raw_keywords,
                page_url=page_url or None,
                location_code=location_code,
                language_code=language_code,
                include_adult_keywords=_boolish(args.get("include_adult_keywords"), default=False),
                limit=int(args.get("limit") or 100),
                login=login,
                password=password,
            )
            return tool_result(
                {
                    "success": True,
                    "mode": mode,
                    "provider": "dataforseo",
                    "location_code": location_code,
                    "language_code": language_code,
                    "keywords": raw_keywords,
                    "page_url": page_url,
                    "row_count": len(rows),
                    "rows": rows,
                }
            )

        raise TakyonError("mode must be one of: gsc-sites, gsc-query, keyword-historical, keyword-ideas")
    except Exception as exc:
        return tool_error(str(exc), success=False)


